export type CliCommandOptions = Record<string, any>;

/**
 * Process-level dependencies used by an imported CLI command execution.
 *
 * Every dependency is scoped to one async execution. This deliberately avoids
 * mutating process globals, so independent in-process tests can run in
 * parallel without sharing providers, output, environment, or clocks.
 */
export interface CliCommandDependencies {
  terminalControlProviderRegistry?: TerminalControlProviderRegistry;
  terminalProcessSource?: TerminalProcessSource;
  createAgentSessionProvider?: (
    agent: "codex",
    options: Readonly<CliCommandOptions>
  ) => CodingAgentSessionProvider;
  codexLocalSessionAdapter?: CodexLocalSessionAdapter | ((
    options: Readonly<CliCommandOptions>
  ) => CodexLocalSessionAdapter);
  codexThreadLifecycleProvider?: TerminalThreadLifecycleCandidateProvider;
  loadClaudeAgentRows?: (
    options: Readonly<CliCommandOptions>,
    observation: { required?: boolean }
  ) => ClaudeAgentRow[];
  agentVersionForRunningProcess?: (
    agent: ExecutorKind,
    pid: number,
    options: Readonly<CliCommandOptions>
  ) => string | undefined;
  codexProcessBirthForPid?: (pid: number) => string;
  stdout?: (text: string) => void;
  cwd?: string | (() => string);
  env?: NodeJS.ProcessEnv;
  pid?: number;
  now?: () => Date | number;
  /** Monotonic clock for terminal composer settling; production uses performance.now. */
  monotonicNowMs?: () => number;
  sleep?: (milliseconds: number) => Promise<void>;
  sleepSync?: (milliseconds: number) => void;
  exit?: (code: number) => never;
  runtimeLog?: (
    level: "info" | "warn" | "error",
    event: string,
    fields: Record<string, unknown>
  ) => void;
}

export interface ParsedCliCommand {
  command?: string;
  options: CliCommandOptions;
}

export interface CliCommandExecutionResult {
  exitCode: number;
  stdout: string;
}

interface CliExecutionContext {
  dependencies: Readonly<CliCommandDependencies>;
  exitCode: number;
  stdout: string[];
}

const cliExecutionStorage = new AsyncLocalStorage<CliExecutionContext>();

function cliContext(): CliExecutionContext | undefined {
  return cliExecutionStorage.getStore();
}

function cliDependencies(): Readonly<CliCommandDependencies> {
  return cliContext()?.dependencies ?? {};
}

function writeCliStdout(text: string): void {
  const context = cliContext();
  if (!context) {
    throw new Error("CLI output requires an active executeCliCommand context");
  }
  context.stdout.push(text);
  context.dependencies.stdout?.(text);
}

function setCliExitCode(exitCode: number): void {
  const context = cliContext();
  if (!context) {
    throw new Error("CLI exit status requires an active executeCliCommand context");
  }
  context.exitCode = exitCode;
}

function cliCwd(): string {
  const configured = cliDependencies().cwd;
  return typeof configured === "function"
    ? configured()
    : configured ?? process.cwd();
}

function cliEnv(): NodeJS.ProcessEnv {
  return cliDependencies().env ?? process.env;
}

function cliPid(): number {
  return cliDependencies().pid ?? process.pid;
}

function cliNow(): Date {
  const value = cliDependencies().now?.();
  return value instanceof Date
    ? new Date(value.getTime())
    : new Date(value ?? Date.now());
}

function cliNowMs(): number {
  return cliNow().getTime();
}

async function cliSleep(milliseconds: number): Promise<void> {
  const injected = cliDependencies().sleep;
  if (injected) {
    await injected(milliseconds);
    return;
  }
  await new Promise<void>((resolve) => setTimeout(resolve, milliseconds));
}

function cliExit(code: number): never {
  const injected = cliDependencies().exit;
  if (injected) {
    return injected(code);
  }
  return process.exit(code);
}

class TurnBindingSupersededError extends Error {
  readonly code = "AKK_TURN_BINDING_SUPERSEDED";

  constructor(message: string) {
    super(message);
    this.name = "TurnBindingSupersededError";
  }
}

class InlineCodexSessionAdapter implements CodexLocalSessionAdapter {
  private readonly threads: CodexThreadRow[];
  private readonly processes: CodexProcessSnapshot[];
  private readonly processBatches: CodexProcessSnapshot[][];
  private processBatchIndex = 0;
  private readonly rollouts: Map<string, string>;
  private readonly activeSessionIdentities: Map<
    number,
    NativeAgentSessionIdentity
  >;

  constructor({
    threads,
    processes,
    rollouts,
    activeSessionIdentities
  }: {
    threads?: CodexThreadRow[];
    processes?: CodexProcessSnapshot[] | CodexProcessSnapshot[][];
    rollouts?: Record<string, string>;
    activeSessionIdentities?: Record<string, unknown>;
  }) {
    this.threads = Array.isArray(threads) ? threads : [];
    this.processBatches = Array.isArray(processes?.[0])
      ? processes as CodexProcessSnapshot[][]
      : [];
    this.processes = Array.isArray(processes) && !Array.isArray(processes[0]) ? processes as CodexProcessSnapshot[] : [];
    this.rollouts = new Map(Object.entries(rollouts ?? {}));
    this.activeSessionIdentities = new Map(
      Object.entries(activeSessionIdentities ?? {}).flatMap(([pidValue, value]) => {
        const pid = Number(pidValue);
        if (!Number.isSafeInteger(pid) || pid <= 1 || !isRecord(value)) {
          return [];
        }
        const sessionId = stringValue(value.sessionId ?? value.session_id);
        if (!sessionId) {
          return [];
        }
        return [[pid, {
          sessionId,
          ...(stringValue(value.processUuid ?? value.process_uuid)
            ? {
                processUuid: stringValue(
                  value.processUuid ?? value.process_uuid
                )
              }
            : {}),
          ...(stringValue(value.processBirth ?? value.process_birth)
            ? {
                processBirth: stringValue(
                  value.processBirth ?? value.process_birth
                )
              }
            : {}),
          ...(isRecord(value.rollout) &&
              stringValue(value.rollout.fd) &&
              stringValue(value.rollout.device) &&
              stringValue(value.rollout.inode) &&
              stringValue(value.rollout.path)
            ? {
                rollout: {
                  fd: stringValue(value.rollout.fd) as string,
                  device: stringValue(value.rollout.device) as string,
                  inode: stringValue(value.rollout.inode) as string,
                  path: stringValue(value.rollout.path) as string
                }
              }
            : {}),
          evidence:
            stringValue(value.evidence) ?? "static_exact_fixture"
        }]];
      })
    );
  }

  async listThreadRows(): Promise<CodexThreadRow[]> {
    return this.threads;
  }

  async readRollout(rolloutPath: string): Promise<string | undefined> {
    return this.rollouts.get(rolloutPath);
  }

  async listProcessSnapshots(): Promise<CodexProcessSnapshot[]> {
    if (this.processBatches.length > 0) {
      const batch = this.processBatches[Math.min(this.processBatchIndex, this.processBatches.length - 1)];
      this.processBatchIndex += 1;
      return batch;
    }

    return this.processes;
  }

  async resolveActiveSessionIdentityForPid(
    pid: number
  ): Promise<NativeAgentSessionIdentity | undefined> {
    return this.activeSessionIdentities.get(pid);
  }
}

export function parseCliCommand(argv: readonly string[]): ParsedCliCommand {
  const [command, ...rawArgs] = argv;
  return {
    command,
    options: parseArgs(rawArgs)
  };
}

export async function executeCliCommand(
  commandName: string | undefined,
  options: CliCommandOptions = {},
  dependencies: CliCommandDependencies = {}
): Promise<CliCommandExecutionResult> {
  const context: CliExecutionContext = {
    dependencies,
    exitCode: 0,
    stdout: []
  };
  return cliExecutionStorage.run(context, async () => {
    runtimeLog("info", "cli_start", {
      command: commandName ?? "help",
      cwd: cliCwd(),
      option_keys: Object.keys(options).sort()
    });
    try {
      await dispatchCliCommand(commandName, options);
      runtimeLog("info", "cli_finish", {
        command: commandName ?? "help",
        exit_code: context.exitCode
      });
      return {
        exitCode: context.exitCode,
        stdout: context.stdout.join("")
      };
    } catch (error) {
      runtimeLog("error", "cli_error", {
        command: commandName ?? "help",
        message: error instanceof Error ? error.message : String(error),
        stack: error instanceof Error ? error.stack : undefined
      });
      throw error;
    }
  });
}

async function dispatchCliCommand(commandName, options) {
  await resolveConversationSelectorOption(commandName, options);
  preflightStoreWriter(commandName, options);
  if (commandName === "help" || commandName === "--help" || commandName === "-h") {
    usage();
  } else if (commandName === "version" || commandName === "--version" || commandName === "-v") {
    printVersion();
  } else if (commandName === "delegate") {
    await runDelegate(options);
  } else if (commandName === "list") {
    await runList(options);
  } else if (commandName === "status") {
    await runStatus(options);
  } else if (commandName === "send") {
    await runSend(options);
  } else if (commandName === "new-thread" || commandName === "clear-thread") {
    await runNewThread(options);
  } else if (commandName === "list-resumable-threads" || commandName === "threads") {
    await runListResumableThreads(options);
  } else if (commandName === "native-inspect" || commandName === "native-status") {
    await runNativeInspect(options);
  } else if (commandName === "resume-thread") {
    await runResumeThread(options);
  } else if (commandName === "reconcile-binding") {
    await runReconcileBinding(options);
  } else if (commandName === "respond") {
    await runRespond(options);
  } else if (commandName === "approve") {
    await runApprove(options);
  } else if (commandName === "cancel") {
    await runCancel(options);
  } else if (commandName === "renew") {
    await runRenew(options);
  } else if (commandName === "reconcile-monitors") {
    await runReconcileMonitors(options);
  } else if (commandName === "close") {
    await runClose(options);
  } else if (commandName === "transcript") {
    runTranscript(options);
  } else if (commandName === "install-openclaw") {
    runInstallOpenClaw(options);
  } else if (commandName === "doctor") {
    runDoctor(options);
  } else if (commandName === "callback") {
    runCallback(options);
  } else if (commandName === "retry-callback") {
    runRetryCallback(options);
  } else if (commandName === "monitor") {
    await runMonitor(options);
  } else {
    usage();
    setCliExitCode(commandName ? 1 : 0);
  }
}

function preflightStoreWriter(commandName, options): void {
  if (!STORE_MUTATION_COMMANDS.has(String(commandName ?? ""))) {
    return;
  }
  const statePath = stringValue(options.state);
  const storeDir = statePath
    ? pathsForConversationDir(path.dirname(expandHome(statePath))).storeDir
    : storeDirFromOptions(options);
  assertStoreWriterCompatible(storeDir);
}

function runInstallOpenClaw(options) {
  const root = packageRootDir();
  const skillOnly = options.skillOnly === true;
  if (options.workspace !== undefined) {
    throw new Error(
      "--workspace was removed from install-openclaw; AKK now discovers verified terminal panes across workspaces. Configure autoApprove.rules[].workspaces only for trusted automatic approvals."
    );
  }
  if (options.defaultAgent !== undefined) {
    throw new Error(
      "--default-agent was removed; AKK now selects the only eligible idle terminal pane"
    );
  }
  if (options.mode !== undefined) {
    throw new Error("--mode was removed; Agent Knock Knock discovers supported terminal providers automatically");
  }
  if (skillOnly && options.verify === true) {
    throw new Error(
      "--skill-only cannot be combined with --verify"
    );
  }

  const needsOpenClaw = !skillOnly || options.noRestart !== true || options.verify === true;
  const openclawBin = needsOpenClaw
    ? options.openclawBin ?? resolveExecutable("openclaw")
    : options.openclawBin;
  const skillSource = path.join(root, "templates", "openclaw-skills", "agent-knock-knock", "SKILL.md");
  const skillDest = expandHome(options.skillPath ?? "~/.openclaw/skills/agent-knock-knock/SKILL.md");
  const steps: Array<Record<string, unknown>> = [];

  if (!skillOnly) {
    const pluginInstall = installOpenClawPlugin(openclawBin, root);
    steps.push({
      name: "plugin_installed",
      path: root,
      mode: pluginInstall.mode
    });

    const configOperations: Array<{ path: string; value: unknown }> = [
      {
        path: "plugins.entries.agent-knock-knock.enabled",
        value: true
      },
    ];
    runCheckedCommand(
      openclawBin,
      ["config", "set", "--batch-json", JSON.stringify(configOperations)],
      { label: "openclaw config set" }
    );
    steps.push({
      name: "plugin_configured",
      plugin: "agent-knock-knock",
      updated: configOperations.map((operation) => operation.path)
    });
  }

  fs.mkdirSync(path.dirname(skillDest), { recursive: true });
  fs.copyFileSync(skillSource, skillDest);
  steps.push({
    name: "skill_installed",
    path: skillDest
  });

  if (options.noRestart !== true) {
    runCheckedCommand(openclawBin, ["gateway", "restart"], {
      label: "openclaw gateway restart"
    });
    steps.push({
      name: "gateway_restarted"
    });
  }

  const pendingRestart = !skillOnly && options.noRestart === true;
  const verification = options.verify === true
    ? buildDoctorReport({
        ...options,
        openclawBin
      })
    : undefined;
  const ready = verification
    ? verification.ok === true && !pendingRestart
    : false;
  const nextActions = installNextActions({
    pendingRestart,
    verification
  });

  printJson({
    installed: true,
    ready,
    pending_restart: pendingRestart,
    mode: skillOnly ? "skill_only" : "full",
    execution_mode: "terminal_provider",
    terminal_providers: ["tmux", "herdr"],
    package_root: root,
    openclaw_bin: openclawBin ?? null,
    steps,
    ...(verification ? { verification } : {}),
    next_actions: nextActions
  });
}

function canonicalWorkspace(value: unknown): string {
  const requested = path.resolve(String(required(value, "--workspace is required")));
  let canonical: string;
  let stat: fs.Stats;
  try {
    canonical = fs.realpathSync(requested);
    stat = fs.statSync(canonical);
  } catch {
    throw new Error(`--workspace does not exist: ${requested}`);
  }
  if (!stat.isDirectory()) {
    throw new Error(`--workspace must be a directory: ${requested}`);
  }
  return canonical;
}

function matchesConfiguredWorkspace(
  configuredWorkspace: unknown,
  candidateWorkspace: unknown
): boolean {
  if (configuredWorkspace === undefined) {
    return true;
  }
  if (candidateWorkspace === undefined || candidateWorkspace === null) {
    return false;
  }
  try {
    return canonicalWorkspace(configuredWorkspace) ===
      canonicalWorkspace(candidateWorkspace);
  } catch {
    return false;
  }
}

function assertConfiguredWorkspace(
  configuredWorkspace: unknown,
  candidateWorkspace: unknown,
  subject: string
): void {
  if (configuredWorkspace === undefined) {
    return;
  }
  const configured = canonicalWorkspace(configuredWorkspace);
  let candidate: string;
  try {
    candidate = canonicalWorkspace(candidateWorkspace);
  } catch {
    throw new Error(
      `refusing ${subject}; its working directory cannot be verified against expected workspace ${configured}`
    );
  }
  if (candidate !== configured) {
    throw new Error(
      `refusing ${subject}; workspace ${candidate} does not match expected workspace ${configured}`
    );
  }
}

function installNextActions({
  pendingRestart,
  verification
}: {
  pendingRestart: boolean;
  verification?: Record<string, any>;
}): Array<{ action: string; command: string }> {
  if (pendingRestart) {
    return [
      {
        action: "apply_plugin_changes",
        command: "openclaw gateway restart"
      },
      {
        action: "verify",
        command: "agent-knock-knock doctor"
      }
    ];
  }

  if (verification && verification.ok !== true) {
    const chain = isRecord(verification.openclaw) ? verification.openclaw : {};
    const checks = Array.isArray(chain.checks) ? chain.checks : [];
    const remediation = checks.flatMap((check) =>
      isRecord(check) && Array.isArray(check.remediation)
        ? check.remediation.filter((command): command is string => typeof command === "string")
        : []
    );
    return [...new Set(remediation)].map((command) => ({
      action: "repair",
      command
    }));
  }

  if (!verification) {
    return [{
      action: "verify",
      command: "agent-knock-knock doctor"
    }];
  }

  return [{
    action: "start_shared_terminal",
    command: "tmux new -s akk-work -c \"$PWD\" codex # use claude instead when preferred"
  }];
}

function installOpenClawPlugin(openclawBin, root) {
  const linked = spawnSync(openclawBin, ["plugins", "install", "--link", root], {
    encoding: "utf8",
    maxBuffer: 1024 * 1024 * 10
  });
  if (linked.error) {
    throw new Error(`openclaw plugins install failed to start: ${linked.error.message}`);
  }
  if (linked.status === 0) {
    return { mode: "linked" };
  }

  const failure = cleanProcessText(linked.stderr || linked.stdout)
    ?? `openclaw plugins install exited with status ${linked.status}`;
  const canRetryWithForce = /plugin already exists:/i.test(failure) ||
    /install cancelled;\s*rerun with --force\b/i.test(failure);
  if (!canRetryWithForce) {
    throw new Error(failure);
  }

  runCheckedCommand(openclawBin, ["plugins", "install", "--force", root], {
    label: "openclaw plugins replace"
  });
  return { mode: "replaced" };
}

function runDoctor(options) {
  const report = buildDoctorReport(options);
  printJson(report);
  if (!report.ok) {
    setCliExitCode(1);
  }
}

function buildDoctorReport(options): Record<string, any> {
  if (options.mode !== undefined) {
    throw new Error("--mode was removed; Agent Knock Knock checks supported terminal providers automatically");
  }
  if (options.workspace !== undefined) {
    throw new Error(
      "--workspace was removed from doctor; AKK now discovers verified terminal panes across workspaces"
    );
  }
  const timeoutMs = options.timeoutMs === undefined
    ? undefined
    : positiveMilliseconds(options.timeoutMs, "--timeout-ms");
  const openclawBin = String(options.openclawBin ?? resolveOptionalExecutable("openclaw"));
  const executables = {
    openclaw: openclawBin,
    ...(options.tmuxBin ? { tmux: String(options.tmuxBin) } : {}),
    herdr: String(options.herdrBin ?? resolveOptionalExecutable("herdr")),
    ...(options.codexBin ? { codex: String(options.codexBin) } : {}),
    ...(options.claudeBin ? { claude: String(options.claudeBin) } : {})
  };
  const checks = [
    {
      command: "node",
      status: "ok" as const,
      available: true,
      executable: process.execPath,
      version: process.versions.node,
      version_supported: versionAtLeast(process.versions.node, MINIMUM_NODE_VERSION),
      minimum_version: MINIMUM_NODE_VERSION
    },
    ...runDoctorCapabilityProbes(
      {
        ...(timeoutMs === undefined ? {} : { timeoutMs }),
        executables
      }
    )
  ];
  const root = packageRootDir();
  const packageFiles = [
    "dist/src/cli.js",
    "dist/src/cli-core.js",
    "dist/src/openclaw-plugin.js",
    "templates/openclaw-skills/agent-knock-knock/SKILL.md",
    "openclaw.plugin.json"
  ].map((relativePath) => {
    const filePath = path.join(root, relativePath);
    return {
      path: filePath,
      exists: fs.existsSync(filePath)
    };
  });
  const capabilities = evaluateDoctorCapabilities(checks);
  const filesOk = packageFiles.every((check) => check.exists);
  const openclaw = runOpenClawChainDiagnostics({
    openclawBin,
    ...(timeoutMs === undefined ? {} : { timeoutMs })
  });
  const ok =
    capabilities.readiness === "ready" &&
    filesOk &&
    openclaw.ready;
  return {
    ok,
    readiness: ok
      ? "ready"
      : capabilities.readiness === "not_ready"
        ? "not_ready"
        : "partially_ready",
    selected_mode: capabilities.available_transports[0] ?? "terminal_provider",
    available_transports: capabilities.available_transports,
    live_terminal: {
      checked: false,
      required_for_install_readiness: false,
      detail:
        "Installation readiness checks tmux or exact-version Herdr and at least one supported CLI. " +
        "AKK verifies a live eligible pane when delegation begins."
    },
    package_root: root,
    checks,
    package_files: packageFiles,
    capabilities: {
      tmux: capabilities.tmux,
      herdr: capabilities.herdr
    },
    openclaw,
    notes: [
      `Node.js ${MINIMUM_NODE_VERSION}+ and OpenClaw are required.`,
      "AKK supports Codex and Claude Code through shared tmux or local Herdr terminals.",
      "Doctor does not require a live coding-agent pane; delegation discovers and verifies one at send time.",
      "Claude terminal completion is hook-free and fails closed unless the local transcript schema is verified.",
      "Herdr support is exact-version gated to 0.8.0/protocol 19 and uses local Unix sockets."
    ]
  };
}

function positiveMilliseconds(value: unknown, optionName: string): number {
  const parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed <= 0) {
    throw new Error(`${optionName} must be a positive number`);
  }
  return Math.ceil(parsed);
}

function versionAtLeast(version: string, minimum: string): boolean {
  const parsed = version.split(".").slice(0, 3).map((part) => Number.parseInt(part, 10));
  const required = minimum.split(".").slice(0, 3).map((part) => Number.parseInt(part, 10));
  if (
    parsed.length !== 3 ||
    required.length !== 3 ||
    [...parsed, ...required].some((part) => !Number.isInteger(part) || part < 0)
  ) {
    return false;
  }
  for (let index = 0; index < 3; index += 1) {
    if (parsed[index] !== required[index]) {
      return parsed[index] > required[index];
    }
  }
  return true;
}

async function listActiveSessionsWithTerminalControl(
  provider,
  options,
  terminalProvider: TerminalControlProvider = createTerminalControlProvider(options)
): Promise<ActiveCodexProcess[]> {
  const activeSessions = await provider.listActiveSessions();
  const activePids = new Set(activeSessions.map((session) => session.pid));
  const processTree = activePids.size > 0
    ? await createTerminalProcessSource(options).listProcessSnapshots(
        (snapshot) => activePids.has(snapshot.pid),
        { includeCwd: false, includeAncestors: true }
      )
    : [];
  return createTerminalAgentBridge(options, terminalProvider).attachProcesses(
    provider.agent,
    activeSessions,
    { processTree }
  );
}

function createRuntimeTerminalControlProviderRegistry(
  options
): TerminalControlProviderRegistry {
  const injected = cliDependencies().terminalControlProviderRegistry;
  if (injected) {
    return injected;
  }
  return createProviderRegistry([
    options.terminalsJson || options.terminalScreensJson || options.processesJson
      ? new StaticTerminalControlProvider({
          panes: options.terminalsJson
            ? parseJsonOption(options.terminalsJson, "--terminals-json")
            : [],
          screens: options.terminalScreensJson
            ? parseJsonOption(options.terminalScreensJson, "--terminal-screens-json")
            : {}
        })
      : new TmuxTerminalControlProvider(),
    ...(
      options.terminalsJson || options.terminalScreensJson || options.processesJson
        ? []
        : [new HerdrTerminalControlProvider()]
    )
  ]);
}

function createTerminalControlProvider(
  options,
  registry: TerminalControlProviderRegistry =
    createRuntimeTerminalControlProviderRegistry(options)
): TerminalControlProvider {
  return registry.asProvider();
}

function createTerminalProcessSource(options): TerminalProcessSource {
  const injected = cliDependencies().terminalProcessSource;
  if (injected) {
    return injected;
  }
  if (options.processesJson) {
    return new StaticTerminalProcessSource(
      parseJsonOption(options.processesJson, "--processes-json")
    );
  }
  return new SystemTerminalProcessSource();
}

function loadClaudeAgentRows(
  options: Record<string, any> = {},
  observation: { required?: boolean } = {}
): ClaudeAgentRow[] {
  const injected = cliDependencies().loadClaudeAgentRows;
  if (injected) {
    return injected(options, observation);
  }
  let value: unknown;
  if (options.claudeAgentsJson !== undefined) {
    value = typeof options.claudeAgentsJson === "string"
      ? parseJsonOption(options.claudeAgentsJson, "--claude-agents-json")
      : options.claudeAgentsJson;
  } else if (options.processesJson || options.terminalsJson || options.terminalScreensJson) {
    return [];
  } else {
    const claudeExecutable = resolveOptionalExecutable("claude");
    if (!claudeExecutable) {
      if (observation.required) {
        throw new Error(
          "Claude agent session observation is unavailable because the Claude CLI could not be resolved"
        );
      }
      return [];
    }
    const result = spawnSync(claudeExecutable, ["agents", "--json", "--all"], {
      encoding: "utf8",
      maxBuffer: 1024 * 1024 * 10,
      timeout: 10_000
    });
    if (result.error || result.status !== 0) {
      runtimeLog("warn", "claude_agents_list_failed", {
        status: result.status ?? null,
        error: result.error?.message,
        stderr: textSummary(cleanProcessText(result.stderr))
      });
      if (observation.required) {
        throw new Error(
          "Claude agent session observation failed; refusing to treat the process as a virgin session"
        );
      }
      return [];
    }
    try {
      value = JSON.parse(result.stdout);
    } catch {
      runtimeLog("warn", "claude_agents_list_invalid_json", {
        stdout: textSummary(result.stdout)
      });
      if (observation.required) {
        throw new Error(
          "Claude agent session observation returned invalid JSON; refusing to treat the process as a virgin session"
        );
      }
      return [];
    }
  }

  const rows = Array.isArray(value)
    ? value
    : isRecord(value) && Array.isArray(value.agents)
      ? value.agents
      : undefined;
  if (!rows) {
    if (observation.required) {
      throw new Error(
        "Claude agent session observation returned an unsupported result shape; refusing to treat the process as a virgin session"
      );
    }
    return [];
  }
  return rows.flatMap((row): ClaudeAgentRow[] => {
    if (!isRecord(row) || !Number.isInteger(Number(row.pid))) {
      return [];
    }
    return [{
      pid: Number(row.pid),
      ...(stringValue(row.cwd) ? { cwd: stringValue(row.cwd) } : {}),
      ...(stringValue(row.kind) ? { kind: stringValue(row.kind) } : {}),
      ...(stringValue(row.sessionId) ? { sessionId: stringValue(row.sessionId) } : {}),
      ...(Number.isSafeInteger(Number(row.startedAt)) && Number(row.startedAt) > 0
        ? { startedAt: Number(row.startedAt) }
        : {}),
      ...(stringValue(row.status) ? { status: stringValue(row.status) } : {}),
      ...(stringValue(row.waitingFor)
        ? { waitingFor: stringValue(row.waitingFor) }
        : {})
    }];
  });
}

function createRuntimeTerminalAgentRegistry(options) {
  return createProductionTerminalAgentRegistry({
    overrides: [
      createCodexTerminalAgentAdapter({
        async detectDurableCompletion(request: TerminalDurableCompletionRequest) {
          const runtime = isRecord(request.context) ? request.context : undefined;
          const conversation = runtime?.conversation;
          const nativeTakeover = isRecord(runtime?.nativeTakeover)
            ? runtime?.nativeTakeover
            : undefined;
          if (!isRecord(conversation)) {
            return undefined;
          }
          const exactCompletion = detectExactBoundCodexCompletion({
            conversation,
            nativeTakeover,
            request,
            runtime,
            options
          });
          if (exactCompletion.handled) {
            return exactCompletion.completion;
          }
          const contextMatches = await loadCodexTerminalContexts({
            nativeTakeover,
            options
          });
          const matches: TerminalCompletionEvidence[] = [];
          const detectionErrors: string[] = [];
          for (const contextMatch of contextMatches) {
            try {
              const evidence = detectCodexDurableCompletion({
                ...request,
                context: contextMatch.context
              });
              if (evidence) {
                matches.push({
                  ...evidence,
                  confidence: contextMatch.confidence as "high" | "medium" | "low",
                  metadata: {
                    ...evidence.metadata,
                    context_match: contextMatch.match,
                    session: contextMatch.context.source
                  }
                });
              }
            } catch (error) {
              detectionErrors.push(
                error instanceof Error ? error.message : String(error)
              );
            }
          }
          if (detectionErrors.length > 0) {
            throw new Error(
              `could not inspect every plausible Codex completion: ${detectionErrors.join("; ")}`
            );
          }
          if (matches.length > 1) {
            throw new Error(
              "multiple same-cwd Codex sessions match the managed terminal request"
            );
          }
          return matches[0];
        }
      }),
      createClaudeTerminalAgentAdapter({
        agentRows: loadClaudeAgentRows(options),
        detectPendingApproval(request: TerminalDurableCompletionRequest) {
          return detectClaudeTranscriptPendingApproval(request, {
            claudeHome: expandHome(options.claudeHome),
            agentRows: loadClaudeAgentRows(options)
          });
        },
        async detectDurableCompletion(request: TerminalDurableCompletionRequest) {
          return detectClaudeTranscriptCompletion(request, {
            claudeHome: expandHome(options.claudeHome),
            agentRows: loadClaudeAgentRows(options)
          });
        }
      })
    ]
  });
}

function detectExactBoundCodexCompletion({
  conversation,
  nativeTakeover,
  request,
  runtime,
  options
}: {
  conversation: Record<string, any>;
  nativeTakeover?: Record<string, any>;
  request: TerminalDurableCompletionRequest;
  runtime?: Record<string, any>;
  options: Record<string, any>;
}): { handled: boolean; completion?: TerminalCompletionEvidence } {
  const submission = terminalBridgeSubmission(conversation);
  const acceptanceEvidence = isRecord(submission?.acceptance_evidence)
    ? submission.acceptance_evidence
    : undefined;
  const anchor = isRecord(nativeTakeover?.codex_rollout_acceptance_anchor)
    ? nativeTakeover.codex_rollout_acceptance_anchor
    : undefined;
  if (submission?.status !== "agent_accepted") {
    return { handled: false };
  }
  const exactRequired = requiresExactBoundCodexCompletion(
    conversation,
    options
  );
  if (!exactRequired) {
    return { handled: false };
  }
  if (acceptanceEvidence?.source !== "codex_rollout") {
    throw new Error(
      "[codex_exact_bound_rollout:invalid_acceptance_evidence] " +
      "the accepted modern Codex Turn has no exact rollout acceptance evidence"
    );
  }
  if (!anchor) {
    throw new Error(
      "[codex_exact_bound_rollout:invalid_anchor] " +
      "the accepted modern Codex Turn has no exact rollout byte anchor"
    );
  }

  const nativeRollout = isRecord(runtime?.nativeRollout)
    ? runtime.nativeRollout
    : undefined;
  const result = detectCodexBoundRolloutCompletion({
    anchor: anchor as unknown as CodexRolloutAcceptanceAnchor,
    acceptanceEvidence:
      acceptanceEvidence as unknown as TerminalSubmissionAcceptanceEvidence,
    currentIdentity: {
      sessionId:
        stringValue(runtime?.nativeSessionId) ??
        stringValue(runtime?.sessionId) ??
        "",
      processUuid: stringValue(runtime?.nativeProcessUuid),
      processBirth: stringValue(runtime?.nativeProcessBirth),
      ...(nativeRollout
        ? {
            rollout: {
              fd: String(nativeRollout.fd ?? ""),
              device: String(nativeRollout.device ?? ""),
              inode: String(nativeRollout.inode ?? ""),
              path: String(nativeRollout.path ?? "")
            }
          }
        : {})
    },
    requestHash:
      stringValue(request.requestHash) ??
      stringValue(nativeTakeover?.terminal_bridge_request_hash) ??
      ""
  });
  if (result.status === "failure") {
    throw new Error(
      `[codex_exact_bound_rollout:${result.diagnostics.code}] ${
        result.diagnostics.detail ?? "the exact bound rollout is not safely inspectable"
      }`
    );
  }
  if (result.status === "pending") {
    return { handled: true };
  }
  return {
    handled: true,
    completion: {
      ...result.completion,
      metadata: {
        ...result.completion.metadata,
        context_match: "exact_bound_rollout",
        detector_code: result.diagnostics.code
      }
    }
  };
}

function requiresExactBoundCodexCompletion(
  conversation: Record<string, any>,
  options: Record<string, any>
): boolean {
  const nativeTakeover = isRecord(conversation.native_session_takeover)
    ? conversation.native_session_takeover
    : undefined;
  const submission = terminalBridgeSubmission(conversation);
  if (submission?.status !== "agent_accepted") {
    return false;
  }
  const hasExactArtifacts =
    isRecord(nativeTakeover?.codex_rollout_acceptance_anchor) &&
    isRecord(submission.acceptance_evidence) &&
    submission.acceptance_evidence.source === "codex_rollout";
  const modernProductionTurn =
    Number(nativeTakeover?.terminal_agent_identity_protocol) === 1 &&
    !allowsSyntheticTerminalAcceptance(options);
  return hasExactArtifacts || modernProductionTurn;
}

function createTerminalAgentBridge(
  options,
  terminalProvider: TerminalControlProvider = createTerminalControlProvider(options),
  registry = createRuntimeTerminalAgentRegistry(options)
): TerminalAgentBridge {
  const processSource = createTerminalProcessSource(options);
  const dependencies = cliDependencies();
  return new TerminalAgentBridge({
    registry,
    terminalProvider,
    ...(dependencies.monotonicNowMs
      ? { nowMs: dependencies.monotonicNowMs }
      : {}),
    ...(dependencies.sleep ? { sleep: dependencies.sleep } : {}),
    async verifyIdentity({ agent, pid, terminalControl, runtime }) {
      const adapter = registry.require(agent);
      const requestedTerminal = terminalProvider.endpoint(terminalControl);
      const resolvedTerminal = await terminalProvider.resolve(requestedTerminal);
      const expectedWorkspace =
        options.workspace ?? resolvedTerminal.route.currentPath ??
        terminalControl.currentPath;
      if (!expectedWorkspace) {
        throw new Error(
          `refusing terminal access to ${terminalControl.target}; its workspace is unavailable`
        );
      }
      const snapshots = await processSource.listProcessSnapshots(
        (candidate) => candidate.pid === pid,
        {
          includeCwd: true,
          includeAncestors: true
        }
      );
      const snapshot = snapshots.find((candidate) => candidate.pid === pid);
      if (!snapshot || !adapter.classifyProcess(snapshot)) {
        throw new Error(
          `terminal conversation agent ${agent} with pid ${pid} is no longer active`
        );
      }
      if (!terminalProvider.containsProcess(
        resolvedTerminal,
        snapshot,
        snapshots
      )) {
        throw new Error(
          `terminal conversation agent ${agent} with pid ${pid} no longer belongs to pane ${terminalControl.target}`
        );
      }
      assertConfiguredWorkspace(
        expectedWorkspace,
        snapshot.cwd,
        `terminal access to ${terminalControl.target} by agent process ${pid}`
      );
      assertConfiguredWorkspace(
        expectedWorkspace,
        resolvedTerminal.route.currentPath,
        `terminal access to ${terminalControl.target} by terminal endpoint`
      );
      const requiresNativeIdentity = Boolean(
        runtime?.nativeSessionId ||
        runtime?.nativeProcessUuid ||
        runtime?.nativeProcessBirth ||
        runtime?.nativeRollout ||
        runtime?.requireNativeProcessUuid ||
        runtime?.requireExactClaudeAgentRow ||
        runtime?.nativeProcessStartedAt ||
        runtime?.exactClaudeAgentState ||
        runtime?.requireNativeRolloutIdentity ||
        runtime?.expectedNativeSessionId ||
        runtime?.expectedEmptyNativeSession ||
        runtime?.allowedPreMaterializationNativeIdentity ||
        runtime?.allowedAdditionalNativeIdentities?.length
      );
      const currentNativeIdentity = requiresNativeIdentity
        ? await resolveCurrentNativeAgentSessionIdentity({
            options,
            agent,
            pid,
            cwd: snapshot.cwd ?? resolvedTerminal.route.currentPath,
            preferredSessionId:
              runtime?.allowedPreMaterializationNativeIdentity &&
                (runtime.expectedNativeSessionId ?? runtime.nativeSessionId) &&
                runtime.allowedPreMaterializationNativeIdentity.sessionId !==
                  (runtime.expectedNativeSessionId ?? runtime.nativeSessionId)
                ? (runtime.expectedNativeSessionId ?? runtime.nativeSessionId)
                : undefined,
            allowedCompanionIdentity:
              runtime?.allowedPreMaterializationNativeIdentity,
            allowedAdditionalIdentities:
              runtime?.allowedAdditionalNativeIdentities
          })
        : undefined;
      assertNativeAgentIdentityForRuntime({
        runtime,
        currentIdentity: currentNativeIdentity,
        agent,
        pid
      });
      if (runtime?.requireExactClaudeAgentRow === true) {
        if (
          agent !== "claude" ||
          !Number.isSafeInteger(runtime.nativeProcessStartedAt) ||
          Number(runtime.nativeProcessStartedAt) <= 0 ||
          !runtime.nativeSessionId
        ) {
          throw new Error(
            `native ${agent} inspection has an incomplete exact process identity; ` +
            "refresh list before controlling the terminal"
          );
        }
        const agentRows = loadClaudeAgentRows(options, { required: true });
        const observation = adapter.observeThreadLifecycle?.({
          operation: { kind: "new_thread" },
          phase: "before",
          pid,
          processStartedAt: runtime.nativeProcessStartedAt,
          cwd: snapshot.cwd ?? resolvedTerminal.route.currentPath,
          agentRows
        });
        const exactRows = agentRows.filter((row) => row.pid === pid);
        const expectedState = runtime.exactClaudeAgentState ?? "idle";
        const stateMatches = expectedState === "idle"
          ? observation?.idle === true
          : (
              observation?.idle === false &&
              exactRows.length === 1 &&
              exactRows[0].status === "waiting" &&
              exactRows[0].waitingFor === "dialog open"
            );
        if (
          observation?.status !== "observed" ||
          !stateMatches ||
          observation.nativeThreadId !== runtime.nativeSessionId
        ) {
          throw new Error(
            `native Claude agents identity, cwd, or idle state changed for process ${pid}; ` +
            "refresh list before controlling the terminal"
          );
        }
      }
      return {
        terminalControl: terminalProvider.toControlRef(
          resolvedTerminal,
          terminalControl.capabilities
        )
      };
    }
  });
}

function terminalControlFromTakeover(nativeTakeover): TerminalControlRef | undefined {
  if (!isRecord(nativeTakeover)) {
    return undefined;
  }
  const terminalControl = nativeTakeover["terminal_control"];
  if (
    !isRecord(terminalControl) ||
    !(terminalControl.kind === "tmux" || terminalControl.kind === "herdr")
  ) {
    return undefined;
  }
  const target = stringValue(terminalControl.target);
  const session = stringValue(terminalControl.session);
  const panePid = Number(terminalControl.panePid);
  if (!target || !session || !Number.isSafeInteger(panePid) || panePid <= 0) {
    return undefined;
  }
  const storedCapabilities = Array.isArray(terminalControl.capabilities)
    ? terminalControl.capabilities.filter(isTerminalControlCapability)
    : [];
  const capabilities = storedCapabilities.length > 0
    ? storedCapabilities
    : [
        "screen_status",
        "send_keys",
        "terminal_approval",
        "screen_completion",
        "durable_completion",
        "terminal_cancel"
      ] as TerminalControlCapability[];
  let control: TerminalControlRef;
  if (terminalControl.kind === "tmux") {
    const window = Number(terminalControl.window);
    const pane = Number(terminalControl.pane);
    if (!Number.isInteger(window) || !Number.isInteger(pane)) {
      return undefined;
    }
    control = {
      kind: "tmux",
      target,
      session,
      window,
      pane,
      panePid,
      currentCommand: stringValue(terminalControl.currentCommand),
      currentPath: stringValue(terminalControl.currentPath),
      socketPath: stringValue(terminalControl.socketPath),
      // State written before adapter capabilities were persisted always represented Codex.
      capabilities
    };
  } else {
    const socketPath = stringValue(terminalControl.socketPath);
    const workspaceId = stringValue(terminalControl.workspaceId);
    const tabId = stringValue(terminalControl.tabId);
    const paneId = stringValue(terminalControl.paneId);
    const terminalId = stringValue(terminalControl.terminalId);
    if (!socketPath || !workspaceId || !tabId || !paneId || !terminalId) {
      return undefined;
    }
    control = {
      kind: "herdr",
      target,
      socketPath,
      session,
      sessionDir: stringValue(terminalControl.sessionDir),
      workspaceId,
      tabId,
      paneId,
      terminalId,
      panePid,
      currentCommand: stringValue(terminalControl.currentCommand),
      currentPath: stringValue(terminalControl.currentPath),
      capabilities
    };
  }
  const endpointEvidence = nativeTakeover["terminal_endpoint"];
  if (endpointEvidence !== undefined) {
    try {
      associateTerminalEndpointEvidence(control, endpointEvidence);
    } catch {
      return undefined;
    }
  }
  return control;
}

function terminalEndpointTakeoverFields(
  terminalControl: TerminalControlRef
): { terminal_control: TerminalControlRef; terminal_endpoint?: TerminalControlEvidence } {
  return {
    terminal_control: terminalControl,
    ...(hasCanonicalTerminalEndpoint(terminalControl)
      ? { terminal_endpoint: terminalControlEvidence(terminalControl) }
      : {})
  };
}

/**
 * Add canonical endpoint evidence to a verified v0.11.x Turn without changing
 * its public route-shaped terminal id or provider-owned control payload.
 * Callers must already hold the terminal, Store-writer, and Turn state locks.
 */
function refineTerminalTurnEndpoint({
  conversation,
  statePath,
  terminalControl
}: {
  conversation: Conversation;
  statePath: string;
  terminalControl: TerminalControlRef;
}): Conversation {
  const takeover = isRecord(conversation.native_session_takeover)
    ? conversation.native_session_takeover
    : undefined;
  const storedControl = terminalControlFromTakeover(takeover);
  if (
    !takeover ||
    !storedControl ||
    takeover.terminal_endpoint !== undefined ||
    !hasCanonicalTerminalEndpoint(terminalControl)
  ) {
    return conversation;
  }
  if (!terminalControlsShareIncarnation(storedControl, terminalControl)) {
    throw new Error(
      `cannot refine Turn ${turnIdForConversation(conversation)} terminal ` +
      "endpoint after its terminal incarnation changed"
    );
  }
  const terminalEndpoint = terminalControlEvidence(terminalControl);
  // Validate that the additive evidence agrees with the exact legacy route
  // before making it durable. This also restores the in-memory association on
  // the old provider-owned control object.
  associateTerminalEndpointEvidence(storedControl, terminalEndpoint);
  const refined: Conversation = {
    ...conversation,
    native_session_takeover: {
      ...takeover,
      terminal_endpoint: terminalEndpoint
    }
  };
  saveState(statePath, refined);
  return refined;
}

function terminalRuntimeIdentityForConversation(
  conversation,
  terminalControl: TerminalControlRef
): TerminalRuntimeIdentity {
  const nativeTakeover = isRecord(conversation?.native_session_takeover)
    ? conversation.native_session_takeover
    : undefined;
  const nativeSessionId = stringValue(nativeTakeover?.native_session_id);
  const terminalIdentity = parseTerminalConversationId(nativeSessionId);
  const explicitSessionId = stringValue(nativeTakeover?.terminal_agent_session_id) ??
    (terminalIdentity ? undefined : nativeSessionId);
  const nativeRollout = isRecord(nativeTakeover?.terminal_agent_rollout)
    ? nativeTakeover.terminal_agent_rollout
    : undefined;
  const strictNativeIdentity =
    Number(nativeTakeover?.terminal_agent_identity_protocol) === 1;
  const expectedNativeSessionId = stringValue(
    nativeTakeover?.terminal_agent_expected_session_id
  );
  const requireNativeProcessUuid =
    strictNativeIdentity && executorForConversation(conversation).kind === "claude";
  const requireNativeRolloutIdentity =
    strictNativeIdentity && executorForConversation(conversation).kind === "codex";
  const runtime: TerminalRuntimeIdentity = {
    pid: Number.isInteger(Number(nativeTakeover?.terminal_agent_pid))
      ? Number(nativeTakeover?.terminal_agent_pid)
      : terminalIdentity?.pid,
    sessionId: explicitSessionId,
    nativeSessionId: stringValue(nativeTakeover?.terminal_agent_session_id),
    nativeProcessUuid: stringValue(
      nativeTakeover?.terminal_agent_process_uuid
    ),
    nativeProcessBirth: stringValue(
      nativeTakeover?.terminal_agent_process_birth
    ),
    requireNativeProcessUuid,
    requireNativeRolloutIdentity,
    ...(nativeRollout
      ? {
          nativeRollout: {
            fd: String(nativeRollout.fd ?? ""),
            device: String(nativeRollout.device ?? ""),
            inode: String(nativeRollout.inode ?? ""),
            path: String(nativeRollout.path ?? "")
          }
        }
      : {}),
    expectedEmptyNativeSession:
      strictNativeIdentity &&
      !stringValue(nativeTakeover?.terminal_agent_session_id),
    expectedNativeSessionId:
      strictNativeIdentity &&
      !stringValue(nativeTakeover?.terminal_agent_session_id)
        ? expectedNativeSessionId
        : undefined,
    cwd: stringValue(nativeTakeover?.source_cwd) ?? terminalControl.currentPath,
    conversationId: stringValue(conversation?.conversation_id),
    messageId: stringValue(nativeTakeover?.terminal_bridge_message_id),
    terminalTarget: terminalControl.target
  };
  if (executorForConversation(conversation).kind !== "codex") {
    return runtime;
  }
  const storeDir = managedSessionStoreDirForConversation(conversation);
  if (!storeDir) {
    return runtime;
  }
  const managedSession = tryLoadManagedSession(
    storeDir,
    sessionIdForConversation(conversation)
  );
  const binding = managedSession?.binding;
  const expectedThreadId = runtime.nativeSessionId ??
    runtime.expectedNativeSessionId;
  if (
    !managedSession ||
    managedSession.agent !== "codex" ||
    managedSession.status !== "bound" ||
    !binding ||
    binding.binding_id !== stringValue(conversation.terminal_binding_id) ||
    binding.generation !== Number(conversation.terminal_binding_generation) ||
    binding.native_thread_id !== expectedThreadId ||
    binding.native_process.pid !== runtime.pid ||
    !terminalControlsShareIncarnation(binding.terminal_control, terminalControl)
  ) {
    return runtime;
  }
  return withCodexCompanionFences(
    runtime,
    codexAllowedCompanionSetForManagedSession({
      storeDir,
      session: managedSession
    })
  );
}

function terminalDurableRequestForConversation(
  conversation,
  terminalControl: TerminalControlRef
): TerminalDurableCompletionRequest {
  const nativeTakeover = isRecord(conversation?.native_session_takeover)
    ? conversation.native_session_takeover
    : undefined;
  const runtime = terminalRuntimeIdentityForConversation(conversation, terminalControl);
  const requestText = String(
    nativeTakeover?.terminal_bridge_request_text ?? conversation?.user_request ?? ""
  );
  return {
    sessionId: runtime.sessionId,
    cwd: stringValue(nativeTakeover?.source_cwd),
    requestText,
    requestHash: stringValue(nativeTakeover?.terminal_bridge_request_hash),
    startedAt: stringValue(nativeTakeover?.terminal_bridge_started_at),
    context: {
      conversation,
      nativeTakeover,
      ...runtime
    }
  };
}

async function migrateLegacyTerminalAgentIdentity({
  conversation,
  statePath,
  logPath,
  options
}) {
  const nativeTakeover = isRecord(conversation?.native_session_takeover)
    ? conversation.native_session_takeover
    : undefined;
  const terminalControl = terminalControlFromTakeover(nativeTakeover);
  if (!nativeTakeover || !terminalControl) {
    return conversation;
  }
  const runtime = terminalRuntimeIdentityForConversation(conversation, terminalControl);
  if (Number.isInteger(runtime.pid) && Number(runtime.pid) > 0) {
    return conversation;
  }

  const executor = executorForConversation(conversation);
  const nativeSessionId = stringValue(nativeTakeover.native_session_id);
  if (
    executor.kind !== "codex" ||
    !nativeSessionId ||
    parseTerminalConversationId(nativeSessionId)
  ) {
    return conversation;
  }

  let matchedProcess: ActiveTerminalProcess | undefined;
  try {
    const registry = createRuntimeTerminalAgentRegistry(options);
    const adapter = registry.require("codex");
    const snapshots = await createTerminalProcessSource(options).listProcessSnapshots(
      (snapshot) => adapter.classifyProcess(snapshot) !== undefined,
      { includeAncestors: true }
    );
    const terminalProvider = createTerminalControlProvider(options);
    const resolvedTerminal = await terminalProvider.resolve(
      terminalProvider.endpoint(terminalControl)
    );

    const candidates = snapshots.flatMap((snapshot): ActiveTerminalProcess[] => {
      const classified = adapter.classifyProcess(snapshot);
      return classified ? [{ ...classified, agent: "codex" }] : [];
    });
    const matches = candidates.filter((candidate) =>
      candidate.sessionId === nativeSessionId &&
      terminalProvider.containsProcess(resolvedTerminal, candidate, snapshots)
    );
    if (matches.length !== 1) {
      return conversation;
    }
    matchedProcess = matches[0];
  } catch (error) {
    runtimeLog("warn", "legacy_terminal_agent_identity_migration_failed", {
      conversation_id: conversation.conversation_id,
      terminal_target: terminalControl.target,
      reason: error instanceof Error ? error.message : String(error)
    });
    return conversation;
  }
  if (!matchedProcess) {
    return conversation;
  }

  const releaseLock = acquireFileLock(`${statePath}.lock`);
  let migratedConversation = conversation;
  let migrated = false;
  try {
    const current = loadState(statePath);
    const currentTakeover = isRecord(current.native_session_takeover)
      ? current.native_session_takeover
      : undefined;
    const currentControl = terminalControlFromTakeover(currentTakeover);
    if (!currentTakeover || !currentControl) {
      return current;
    }
    const currentRuntime = terminalRuntimeIdentityForConversation(current, currentControl);
    if (Number.isInteger(currentRuntime.pid) && Number(currentRuntime.pid) > 0) {
      return current;
    }
    if (
      currentTakeover.native_session_id !== nativeSessionId ||
      !terminalControlsShareIncarnation(currentControl, terminalControl)
    ) {
      return current;
    }

    const migratedAt = cliNow().toISOString();
    migratedConversation = {
      ...current,
      native_session_takeover: {
        ...currentTakeover,
        terminal_agent_pid: matchedProcess.pid,
        terminal_agent_session_id: matchedProcess.sessionId,
        terminal_agent_identity_migrated_at: migratedAt
      },
      updated_at: migratedAt
    };
    saveState(statePath, migratedConversation);
    migrated = true;
  } finally {
    releaseLock();
  }

  if (migrated) {
    appendEvent(logPath, {
      ts: cliNow().toISOString(),
      conversation_id: migratedConversation.conversation_id,
      event: "terminal_agent_identity_migrated",
      terminal_target: terminalControl.target,
      terminal_agent_pid: matchedProcess.pid,
      native_session_id: nativeSessionId
    });
    runtimeLog("info", "terminal_agent_identity_migrated", {
      conversation_id: migratedConversation.conversation_id,
      terminal_target: terminalControl.target,
      terminal_agent_pid: matchedProcess.pid
    });
  }
  return migratedConversation;
}

function isTerminalControlCapability(value: unknown): value is TerminalControlCapability {
  return typeof value === "string" && [
    "screen_status",
    "send_keys",
    "terminal_approval",
    "screen_completion",
    "durable_completion",
    "terminal_cancel"
  ].includes(value);
}

function assertSafeAbortedTerminalRetryBinding({
  owner,
  receipt,
  storeDir,
  terminalControl,
  messageId
}: {
  owner: Conversation;
  receipt: Record<string, any>;
  storeDir: string;
  terminalControl: TerminalControlRef;
  messageId: string;
}): void {
  if (!(receipt.status === "aborted" && receipt.safe_to_retry === true)) {
    return;
  }
  const sessionId = sessionIdForConversation(owner);
  const managedSession = tryLoadManagedSession(storeDir, sessionId);
  const binding = managedSession?.binding;
  const receiptBindingId = stringValue(receipt.binding_id);
  const receiptBindingGeneration = Number(receipt.binding_generation);
  const receiptNativeThreadId = stringValue(receipt.native_thread_id);
  const ownerTakeover = isRecord(owner.native_session_takeover)
    ? owner.native_session_takeover
    : undefined;
  const ownerControl = terminalControlFromTakeover(ownerTakeover);
  const ownerNativeThreadId = stringValue(owner.native_thread_id) ??
    stringValue(ownerTakeover?.terminal_agent_session_id) ??
    stringValue(ownerTakeover?.terminal_agent_expected_session_id);
  const ownerAgentPid = Number(ownerTakeover?.terminal_agent_pid);
  if (
    !managedSession ||
    managedSession.status !== "bound" ||
    !binding ||
    !receiptBindingId ||
    !Number.isSafeInteger(receiptBindingGeneration) ||
    !receiptNativeThreadId ||
    receiptBindingId !== stringValue(owner.terminal_binding_id) ||
    receiptBindingGeneration !== Number(owner.terminal_binding_generation) ||
    receiptNativeThreadId !== ownerNativeThreadId ||
    binding.binding_id !== receiptBindingId ||
    binding.generation !== receiptBindingGeneration ||
    binding.native_thread_id !== receiptNativeThreadId ||
    !Number.isSafeInteger(ownerAgentPid) ||
    binding.native_process.pid !== ownerAgentPid ||
    !ownerControl ||
    !terminalControlsShareIncarnation(ownerControl, terminalControl) ||
    !terminalControlsShareIncarnation(binding.terminal_control, terminalControl)
  ) {
    throw new Error(
      `terminal idempotency key ${messageId} belongs to a safe-aborted Turn ` +
      "whose Session binding is no longer current; no terminal input was sent"
    );
  }
}

function stableDelegateTerminalRoute({
  options,
  request,
  workspace,
  requestedAgent
}: {
  options: Record<string, any>;
  request: string;
  workspace?: string;
  requestedAgent?: ExecutorKind;
}):
  | { kind: "terminal"; conversationId: string; workspace: string }
  | { kind: "session"; sessionId: string; workspace: string }
  | undefined {
  const messageId = stringValue(options.messageId);
  if (!messageId) {
    return undefined;
  }
  const storeDir = path.resolve(storeDirFromOptions(options));
  const requestHash = terminalBridgeRequestFingerprint(
    terminalSubmissionPayload(request)
  );
  const bodyHash = createHash("sha256").update(request).digest("hex");
  const requestedOpenClawSession = stringValue(options.openclawSession);
  const matches = listConversations(storeDir).flatMap((owner) =>
    terminalBridgeSubmissionReceipts(owner)
      .filter((receipt) => stringValue(receipt.message_id) === messageId)
      .map((receipt) => ({ owner, receipt }))
  );
  if (matches.length === 0) {
    return undefined;
  }
  const routed = matches.map(({ owner, receipt }) => {
    const ownerStoreDir = managedSessionStoreDirForConversation(owner);
    const takeover = isRecord(owner.native_session_takeover)
      ? owner.native_session_takeover
      : undefined;
    const terminalControl = terminalControlFromTakeover(takeover);
    const conversationId = stringValue(takeover?.native_session_id);
    let eventMessages: Record<string, any>[] = [];
    const eventLogPath = stringValue(owner.event_log_path);
    if (eventLogPath) {
      try {
        eventMessages = readNdjsonLog(eventLogPath)
          .filter((event) =>
            isRecord(event.message) && event.message.id === messageId
          )
          .map((event) => event.message as Record<string, any>);
      } catch {
        eventMessages = [];
      }
    }
    if (eventMessages.length > 1) {
      throw new Error(
        `terminal idempotency key ${messageId} has duplicate durable messages`
      );
    }
    const eventMessage = eventMessages[0];
    const messageType = stringValue(receipt.message_type) ??
      (isRecord(eventMessage) ? stringValue(eventMessage.type) : undefined);
    const storedBodyHash = stringValue(receipt.message_body_hash) ??
      (isRecord(eventMessage) && typeof eventMessage.body === "string"
        ? createHash("sha256").update(eventMessage.body).digest("hex")
        : undefined);
    const ownerWorkspace = canonicalWorkspace(owner.workspace);
    if (
      !ownerStoreDir ||
      path.resolve(ownerStoreDir) !== storeDir ||
      (stringValue(receipt.store_dir) !== undefined &&
        path.resolve(String(receipt.store_dir)) !== storeDir) ||
      !terminalControl ||
      !conversationId ||
      stringValue(receipt.request_hash) !== requestHash ||
      messageType !== "task" ||
      storedBodyHash !== bodyHash ||
      (requestedOpenClawSession &&
        (stringValue(receipt.openclaw_session) ?? owner.openclaw_session) !==
          requestedOpenClawSession) ||
      (requestedAgent && executorForConversation(owner).kind !== requestedAgent) ||
      (workspace && ownerWorkspace !== workspace)
    ) {
      throw new Error(
        `terminal idempotency key ${messageId} does not match its original ` +
        "delegate request boundary; no terminal input was sent"
      );
    }
    return {
      owner,
      receipt,
      conversationId,
      workspace: ownerWorkspace,
      terminalControl
    };
  });
  const authoritative = routed.filter(({ receipt }) =>
    !(receipt.status === "aborted" && receipt.safe_to_retry === true)
  );
  if (authoritative.length > 1) {
    throw new Error(
      `terminal idempotency key ${messageId} has multiple durable delegate receipts`
    );
  }
  const firstRoute = routed[0];
  if (
    !firstRoute ||
    routed.some((entry) =>
      entry.conversationId !== firstRoute.conversationId ||
      !terminalControlsShareIncarnation(
        entry.terminalControl,
        firstRoute.terminalControl
      )
    )
  ) {
    throw new Error(
      `terminal idempotency key ${messageId} has conflicting terminal routes`
    );
  }
  const selected = authoritative[0] ?? routed.at(-1);
  if (!selected) {
    return undefined;
  }
  if (
    selected.receipt.status === "aborted" &&
    selected.receipt.safe_to_retry === true
  ) {
    const sessionId = sessionIdForConversation(selected.owner);
    const ownerControl = terminalControlFromTakeover(
      isRecord(selected.owner.native_session_takeover)
        ? selected.owner.native_session_takeover
        : undefined
    );
    if (!ownerControl) {
      throw new Error(
        `terminal idempotency key ${messageId} has no durable terminal route`
      );
    }
    assertSafeAbortedTerminalRetryBinding({
      owner: selected.owner,
      receipt: selected.receipt,
      storeDir,
      terminalControl: ownerControl,
      messageId
    });
    return {
      kind: "session",
      sessionId,
      workspace: selected.workspace
    };
  }
  return {
    kind: "terminal",
    conversationId: selected.conversationId,
    workspace: selected.workspace
  };
}

async function runDelegate(options) {
  const request = required(options.request, "--request is required");
  const workspace = options.workspace === undefined
    ? undefined
    : canonicalWorkspace(options.workspace);
  const requestedAgent = options.agent === undefined
    ? undefined
    : resolveExecutor({ kind: options.agent }).kind;
  const stableRoute = stableDelegateTerminalRoute({
    options,
    request,
    workspace,
    requestedAgent
  });
  if (stableRoute) {
    await runSend(stableRoute.kind === "session"
      ? {
          ...options,
          session: stableRoute.sessionId,
          conversation: undefined,
          message: request,
          workspace: stableRoute.workspace,
          background: true
        }
      : {
          ...options,
          conversation: stableRoute.conversationId,
          session: undefined,
          message: request,
          workspace: stableRoute.workspace,
          background: true
        });
    return;
  }
  const scan = await buildTerminalListGroup({
    options: {
      ...options,
      workspace,
      noApprovalScan: false
    },
    agentFilter: requestedAgent,
    statusFilter: undefined
  });
  if (scan.summary.error) {
    throw new Error(`terminal discovery failed: ${scan.summary.error}`);
  }

  const scopedCandidates = workspace === undefined
    ? scan.terminalControlled
    : scan.terminalControlled.filter((candidate) => {
        try {
          return canonicalWorkspace(candidate.workspace) === workspace;
        } catch {
          return false;
        }
      });
  const eligible = scopedCandidates.filter((candidate) => {
    if (candidate.activity_state !== "idle") {
      return false;
    }
    const terminalControl = isRecord(candidate.terminal_control)
      ? candidate.terminal_control as unknown as TerminalControlRef
      : undefined;
    return !terminalControl || terminalDispatchOwnership(terminalControl).state === "none";
  });
  if (eligible.length === 0) {
    const observed = scopedCandidates.length > 0
      ? ` Found ${scopedCandidates.length} matching pane(s), but none is idle.`
      : "";
    const requestedExecutor = requestedAgent
      ? executorDefinitionForKind(requestedAgent)
      : undefined;
    const workspaceDetail = workspace
      ? ` in ${workspace}`
      : "";
    throw new Error(
      `No idle ${requestedExecutor?.displayName ?? "Codex or Claude Code"} pane is available${workspaceDetail}.${observed} ` +
      `Start ${requestedAgent ?? "codex or claude"} inside tmux or Herdr${workspaceDetail}, wait until it is idle, then retry.`
    );
  }
  if (eligible.length > 1) {
    const candidates = eligible
      .map((candidate) => {
        const identity =
          `${candidate.agent}, ${candidate.terminal_control?.target ?? candidate.id}`;
        return workspace
          ? `${candidate.short_ref} (${identity})`
          : `${candidate.short_ref} (${identity}, ${candidate.workspace ?? "workspace unknown"})`;
      })
      .join(", ");
    const scope = requestedAgent
      ? executorDefinitionForKind(requestedAgent).displayName
      : "coding-agent";
    const ambiguity = workspace
      ? `match ${workspace}`
      : "are available across workspaces";
    throw new Error(
      `Multiple idle ${scope} panes ${ambiguity}: ${candidates}. ` +
      "Use /akk codex: <task>, /akk claude: <task>, or /akk @short-ref: <message> to choose one explicitly."
    );
  }

  const selectedWorkspace = canonicalWorkspace(eligible[0].workspace);
  await runSend({
    ...options,
    conversation: eligible[0].id,
    message: request,
    workspace: selectedWorkspace,
    background: true
  });
}

function startTerminalBridgeMonitor({
  statePath,
  logPath,
  agentTimeoutMinutes,
  agentHardTimeoutMinutes,
  pollIntervalMs,
  codexHome,
  claudeHome
}) {
  const args = [
    cliEntryPath(),
    "monitor",
    "--terminal-bridge",
    "--state",
    statePath,
    "--log",
    logPath,
    "--agent-timeout-minutes",
    String(agentTimeoutMinutes),
    "--agent-hard-timeout-minutes",
    String(agentHardTimeoutMinutes),
    "--poll-interval-ms",
    String(pollIntervalMs)
  ];
  if (codexHome) {
    args.push("--codex-home", codexHome);
  }
  if (claudeHome) {
    args.push("--claude-home", claudeHome);
  }
  const child = spawn(process.execPath, args, {
    detached: true,
    stdio: "ignore",
    cwd: cliCwd(),
    env: environmentWithoutGatewayTokens()
  });
  child.unref();
  return child;
}

function startTerminalBridgeMonitorForConversation({ conversation, statePath, logPath, options }) {
  if (
    !terminalBridgeEnabled(conversation) ||
    options.disableTerminalBridgeMonitor === true
  ) {
    return undefined;
  }
  const nativeTakeover = isRecord(conversation.native_session_takeover)
    ? conversation.native_session_takeover
    : undefined;
  return startTerminalBridgeMonitor({
    statePath,
    logPath,
    agentTimeoutMinutes: Number(
      options.agentTimeoutMinutes ??
        nativeTakeover?.["terminal_bridge_inactivity_timeout_minutes"] ??
        DEFAULT_AGENT_TIMEOUT_MINUTES
    ),
    agentHardTimeoutMinutes: Number(
      options.agentHardTimeoutMinutes ??
        nativeTakeover?.["terminal_bridge_hard_timeout_minutes"] ??
        DEFAULT_AGENT_HARD_TIMEOUT_MINUTES
    ),
    pollIntervalMs: Number(options.monitorPollIntervalMs ?? DEFAULT_MONITOR_POLL_INTERVAL_MS),
    codexHome: options.codexHome,
    claudeHome: options.claudeHome ?? nativeTakeover?.["claude_home"]
  });
}

function startTerminalBridgeMonitorHandoffWatchdog({
  conversation,
  statePath,
  logPath,
  options
}) {
  if (
    options.disableTerminalBridgeMonitor === true ||
    !terminalBridgeEnabled(conversation)
  ) {
    return undefined;
  }
  const nativeTakeover = isRecord(conversation.native_session_takeover)
    ? conversation.native_session_takeover
    : undefined;
  const terminalMessageId = stringValue(
    nativeTakeover?.terminal_bridge_message_id
  );
  if (!terminalMessageId) {
    return undefined;
  }

  const args = [
    cliEntryPath(),
    "monitor",
    "--terminal-bridge-handoff",
    "--state",
    statePath,
    "--log",
    logPath,
    "--expected-terminal-message-id",
    terminalMessageId
  ];
  const monitorPollIntervalMs = Number(options.monitorPollIntervalMs);
  if (Number.isFinite(monitorPollIntervalMs) && monitorPollIntervalMs > 0) {
    args.push(
      "--monitor-poll-interval-ms",
      String(monitorPollIntervalMs)
    );
  }
  const handoffPollIntervalMs = Number(options.monitorHandoffPollIntervalMs);
  if (Number.isFinite(handoffPollIntervalMs) && handoffPollIntervalMs > 0) {
    args.push(
      "--monitor-handoff-poll-interval-ms",
      String(handoffPollIntervalMs)
    );
  }
  const claudeHome =
    options.claudeHome ?? nativeTakeover?.["claude_home"];
  if (options.codexHome) {
    args.push("--codex-home", options.codexHome);
  }
  if (claudeHome) {
    args.push("--claude-home", claudeHome);
  }

  const child = spawn(process.execPath, args, {
    detached: true,
    stdio: "ignore",
    cwd: cliCwd(),
    env: environmentWithoutGatewayTokens()
  });
  child.unref();
  return child;
}

function ensureTerminalBridgeMonitorAfterApproval({
  conversation,
  statePath,
  logPath,
  terminalControl,
  options,
  reason = "approval_resolved"
}) {
  const nativeTakeover = isRecord(conversation.native_session_takeover)
    ? conversation.native_session_takeover
    : undefined;
  const terminalMessageId = stringValue(
    nativeTakeover?.terminal_bridge_message_id
  );
  const activeMonitor = terminalMessageId
    ? activeTerminalBridgeMonitorOwner(statePath, terminalMessageId)
    : undefined;
  const launchedMonitor = activeMonitor
    ? undefined
    : startTerminalBridgeMonitorForConversation({
        conversation,
        statePath,
        logPath,
        options
      });
  const handoffWatchdog = activeMonitor
    ? startTerminalBridgeMonitorHandoffWatchdog({
        conversation,
        statePath,
        logPath,
        options
      })
    : undefined;
  const monitorPid = activeMonitor?.ownerPid ?? launchedMonitor?.pid;
  const agentTimeoutMinutes = Number(
    options.agentTimeoutMinutes ??
      nativeTakeover?.terminal_bridge_inactivity_timeout_minutes ??
      DEFAULT_AGENT_TIMEOUT_MINUTES
  );
  const agentHardTimeoutMinutes = Number(
    options.agentHardTimeoutMinutes ??
      nativeTakeover?.terminal_bridge_hard_timeout_minutes ??
      DEFAULT_AGENT_HARD_TIMEOUT_MINUTES
  );
  if (activeMonitor) {
    appendEvent(logPath, {
      ts: cliNow().toISOString(),
      conversation_id: conversation.conversation_id,
      event: "terminal_bridge_monitor_reused",
      pid: activeMonitor.ownerPid ?? null,
      terminal_control: terminalControl,
      reason,
      agent_timeout_minutes: agentTimeoutMinutes,
      agent_hard_timeout_minutes: agentHardTimeoutMinutes
    });
    runtimeLog("info", "terminal_bridge_monitor_reused", {
      conversation_id: conversation.conversation_id,
      monitor_pid: activeMonitor.ownerPid ?? null,
      terminal_target: terminalControl.target,
      reason
    });
    if (handoffWatchdog) {
      appendEvent(logPath, {
        ts: cliNow().toISOString(),
        conversation_id: conversation.conversation_id,
        event: "terminal_bridge_monitor_handoff_watchdog_launch",
        pid: handoffWatchdog.pid ?? null,
        monitor_owner_pid: activeMonitor.ownerPid ?? null,
        terminal_bridge_message_id: terminalMessageId,
        terminal_control: terminalControl,
        reason
      });
      runtimeLog("info", "terminal_bridge_monitor_handoff_watchdog_launch", {
        conversation_id: conversation.conversation_id,
        watchdog_pid: handoffWatchdog.pid ?? null,
        monitor_owner_pid: activeMonitor.ownerPid ?? null,
        terminal_target: terminalControl.target,
        reason
      });
    }
  } else if (launchedMonitor) {
    appendEvent(logPath, {
      ts: cliNow().toISOString(),
      conversation_id: conversation.conversation_id,
      event: "terminal_bridge_monitor_launch",
      pid: launchedMonitor.pid ?? null,
      terminal_control: terminalControl,
      reason,
      agent_timeout_minutes: agentTimeoutMinutes,
      agent_hard_timeout_minutes: agentHardTimeoutMinutes
    });
    runtimeLog("info", "terminal_bridge_monitor_launch", {
      conversation_id: conversation.conversation_id,
      monitor_pid: launchedMonitor.pid ?? null,
      terminal_target: terminalControl.target,
      reason
    });
  }
  return {
    activeMonitor,
    launchedMonitor,
    handoffWatchdog,
    monitorPid
  };
}

function terminalBridgeEnabled(conversation): boolean {
  const nativeTakeover = isRecord(conversation.native_session_takeover)
    ? conversation.native_session_takeover
    : undefined;
  return nativeTakeover?.["terminal_bridge"] === true;
}

function withTerminalBridgeState({
  conversation,
  message,
  requestText,
  startedAt,
  agentTimeoutMinutes,
  agentHardTimeoutMinutes,
  preSendScreenFingerprint,
  codexRolloutAcceptanceAnchor,
  claudeTranscriptAnchor,
  claudeHome
}) {
  const nativeTakeover = isRecord(conversation.native_session_takeover)
    ? conversation.native_session_takeover
    : {};
  return {
    ...conversation,
    native_session_takeover: {
      ...nativeTakeover,
      terminal_bridge: true,
      terminal_bridge_started_at: startedAt,
      terminal_bridge_message_id: message.id,
      terminal_bridge_request_text: requestText,
      terminal_bridge_request_hash: terminalBridgeRequestFingerprint(requestText),
      terminal_bridge_pre_send_screen_fingerprint: preSendScreenFingerprint,
      codex_rollout_acceptance_anchor: codexRolloutAcceptanceAnchor,
      claude_transcript_anchor: claudeTranscriptAnchor,
      claude_home: claudeHome,
      terminal_bridge_completion_claim: undefined,
      terminal_bridge_approval_dispatch: undefined,
      terminal_bridge_detector_diagnostic: undefined,
      terminal_bridge_monitor_lock_version: TERMINAL_BRIDGE_MONITOR_LOCK_VERSION,
      terminal_bridge_monitor_started_at: startedAt,
      terminal_bridge_last_activity_at: startedAt,
      terminal_bridge_inactivity_timeout_minutes: agentTimeoutMinutes,
      terminal_bridge_hard_timeout_minutes: agentHardTimeoutMinutes,
      terminal_bridge_inactivity_deadline_at: deadlineAt(startedAt, agentTimeoutMinutes),
      terminal_bridge_hard_deadline_at: deadlineAt(startedAt, agentHardTimeoutMinutes)
    },
    updated_at: startedAt
  };
}

type TerminalBridgeSubmissionStatus =
  | "prepared"
  | "text_injected"
  | "enter_dispatched"
  | "agent_accepted"
  | "not_accepted"
  // Legacy `submitted` proves only that tmux accepted the Enter dispatch.
  | "submitted"
  | "uncertain"
  | "aborted";

function withTerminalBridgeSubmission({
  conversation,
  messageId,
  messageType,
  messageBody,
  requestText,
  status,
  preparedAt,
  textInjectedAt,
  enterDispatchedAt,
  agentAcceptedAt,
  notAcceptedAt,
  submittedAt,
  uncertainAt,
  abortedAt,
  error,
  acceptanceEvidence,
  lastProvenStage,
  safeToRetry
}: {
  conversation: Conversation;
  messageId: string;
  messageType?: "task" | "answer";
  messageBody?: string;
  requestText: string;
  status: TerminalBridgeSubmissionStatus;
  preparedAt: string;
  textInjectedAt?: string;
  enterDispatchedAt?: string;
  agentAcceptedAt?: string;
  notAcceptedAt?: string;
  submittedAt?: string;
  uncertainAt?: string;
  abortedAt?: string;
  error?: string;
  acceptanceEvidence?: TerminalSubmissionAcceptanceEvidence;
  lastProvenStage?: "prepared" | "text_injected" | "enter_dispatched" | "agent_accepted";
  safeToRetry?: boolean;
}): Conversation {
  const nativeTakeover = isRecord(conversation.native_session_takeover)
    ? conversation.native_session_takeover
    : {};
  const previousSubmission = isRecord(nativeTakeover.terminal_bridge_submission)
    ? nativeTakeover.terminal_bridge_submission
    : undefined;
  const receiptsValue = nativeTakeover.terminal_bridge_submission_receipts;
  if (receiptsValue !== undefined && !Array.isArray(receiptsValue)) {
    throw new Error("terminal submission receipt history is malformed");
  }
  const storedReceipts = (Array.isArray(receiptsValue) ? receiptsValue : [])
    .map((value) => {
      if (!isRecord(value) || !stringValue(value.message_id)) {
        throw new Error("terminal submission receipt history is malformed");
      }
      return value;
    });
  const storedReceiptIds = new Set<string>();
  for (const receipt of storedReceipts) {
    const receiptId = String(receipt.message_id);
    if (storedReceiptIds.has(receiptId)) {
      throw new Error(`terminal submission receipt ${receiptId} is duplicated`);
    }
    storedReceiptIds.add(receiptId);
  }
  // A v0.10.1 Turn has only the latest singleton receipt. Seed it into the
  // append-only history before recording a later response so upgrading cannot
  // erase the only proof that an older message was already dispatched.
  const previousSubmissionId = stringValue(previousSubmission?.message_id);
  const previousReceipts = previousSubmissionId &&
    !storedReceiptIds.has(previousSubmissionId)
    ? [...storedReceipts, previousSubmission as Record<string, any>]
    : storedReceipts;
  const matchingReceipts = previousReceipts.filter((receipt) =>
    stringValue(receipt.message_id) === messageId
  );
  if (matchingReceipts.length > 1) {
    throw new Error(`terminal submission receipt ${messageId} is duplicated`);
  }
  const previousReceipt = matchingReceipts[0];
  const previousGenerationSubmission =
    stringValue(previousSubmission?.message_id) === messageId
      ? previousSubmission
      : undefined;
  if (
    previousReceipt &&
    previousGenerationSubmission &&
    canonicalJson(previousReceipt) !== canonicalJson(previousGenerationSubmission)
  ) {
    throw new Error(
      `terminal submission receipt ${messageId} conflicts with its current generation`
    );
  }
  const durableMessageType = messageType ??
    (stringValue(previousReceipt?.message_type) === "answer"
      ? "answer"
      : stringValue(previousReceipt?.message_type) === "task"
        ? "task"
        : stringValue(previousGenerationSubmission?.message_type) === "answer"
          ? "answer"
          : stringValue(previousGenerationSubmission?.message_type) === "task"
            ? "task"
            : undefined);
  const messageBodyHash = messageBody !== undefined
    ? createHash("sha256").update(messageBody).digest("hex")
    : stringValue(previousReceipt?.message_body_hash) ??
      stringValue(previousGenerationSubmission?.message_body_hash);
  const previousDispatcherPid = Number(
    previousGenerationSubmission?.dispatcher_pid
  );
  const dispatcherPid = status === "prepared" ||
    !Number.isSafeInteger(previousDispatcherPid) ||
    previousDispatcherPid <= 1
    ? cliPid()
    : previousDispatcherPid;
  const provenStage = lastProvenStage ?? terminalSubmissionLastProvenStage(
    status,
    stringValue(previousGenerationSubmission?.last_proven_stage)
  );
  const validatedAcceptanceEvidence = status === "agent_accepted"
    ? terminalAcceptanceEvidenceForConversation(
        conversation,
        requestText,
        acceptanceEvidence
      )
    : undefined;
  const storedControl = terminalControlFromTakeover(nativeTakeover);
  const requestHash = terminalBridgeRequestFingerprint(requestText);
  const candidateImmutableReceiptFields = {
    session_id: sessionIdForConversation(conversation),
    turn_id: turnIdForConversation(conversation),
    message_id: messageId,
    binding_id: stringValue(conversation.terminal_binding_id),
    binding_generation: Number.isSafeInteger(
      Number(conversation.terminal_binding_generation)
    )
      ? Number(conversation.terminal_binding_generation)
      : undefined,
    ...(durableMessageType ? { message_type: durableMessageType } : {}),
    ...(messageBodyHash ? { message_body_hash: messageBodyHash } : {}),
    request_hash: requestHash,
    executor_kind: executorForConversation(conversation).kind,
    openclaw_session: conversation.openclaw_session,
    store_dir: managedSessionStoreDirForConversation(conversation),
    native_thread_id:
      stringValue(conversation.native_thread_id) ??
      stringValue(nativeTakeover.terminal_agent_session_id) ??
      stringValue(nativeTakeover.terminal_agent_expected_session_id),
    terminal_target: storedControl?.target,
    terminal_socket_path: storedControl?.socketPath ?? null,
    terminal_pane_pid: storedControl?.panePid,
    terminal_endpoint:
      storedControl && hasCanonicalTerminalEndpoint(storedControl)
        ? terminalControlEvidence(storedControl)
        : previousReceipt?.terminal_endpoint
  };
  const immutableReceiptFields = Object.fromEntries(
    Object.entries(candidateImmutableReceiptFields).map(([key, value]) => [
      key,
      value === undefined && previousReceipt?.[key] !== undefined
        ? previousReceipt[key]
        : value
    ])
  );
  if (previousReceipt) {
    for (const [key, value] of Object.entries(candidateImmutableReceiptFields)) {
      if (
        previousReceipt[key] !== undefined &&
        value !== undefined &&
        canonicalJson(previousReceipt[key]) !== canonicalJson(value)
      ) {
        throw new Error(
          `terminal submission receipt ${messageId} changed immutable ${key}`
        );
      }
    }
  }
  const nextSubmission = {
    status,
    ...immutableReceiptFields,
    prepared_at: preparedAt,
    dispatcher_pid: dispatcherPid,
    last_proven_stage: provenStage,
    ...(textInjectedAt ? { text_injected_at: textInjectedAt } : {}),
    ...(enterDispatchedAt ? { enter_dispatched_at: enterDispatchedAt } : {}),
    ...(agentAcceptedAt ? { agent_accepted_at: agentAcceptedAt } : {}),
    ...(notAcceptedAt ? { not_accepted_at: notAcceptedAt } : {}),
    ...(submittedAt ? { submitted_at: submittedAt } : {}),
    ...(uncertainAt ? { uncertain_at: uncertainAt } : {}),
    ...(abortedAt ? { aborted_at: abortedAt } : {}),
    ...(error ? { error: textSummary(error) } : {}),
    ...(safeToRetry !== undefined ? { safe_to_retry: safeToRetry } : {}),
    ...(validatedAcceptanceEvidence
      ? { acceptance_evidence: validatedAcceptanceEvidence }
      : {})
  };
  const nextReceipts = previousReceipt
    ? previousReceipts.map((receipt) =>
        stringValue(receipt.message_id) === messageId
          ? nextSubmission
          : receipt
      )
    : [...previousReceipts, nextSubmission];
  return {
    ...conversation,
    native_session_takeover: {
      ...nativeTakeover,
      terminal_bridge_submission: nextSubmission,
      terminal_bridge_submission_receipts: nextReceipts
    },
    updated_at:
      agentAcceptedAt ?? notAcceptedAt ?? uncertainAt ?? abortedAt ??
      enterDispatchedAt ?? textInjectedAt ?? submittedAt ?? preparedAt
  };
}

function terminalAcceptanceEvidenceForConversation(
  conversation: Conversation,
  requestText: string,
  evidence: unknown
): TerminalSubmissionAcceptanceEvidence {
  return validateTerminalSubmissionAcceptanceEvidence(
    evidence,
    terminalAcceptanceEvidenceExpectation(conversation, requestText)
  );
}

function terminalAcceptanceEvidenceExpectation(
  conversation: Conversation,
  requestText: string
): {
  source: TerminalSubmissionAcceptanceEvidence["source"];
  nativeThreadId: string;
  requestHash: string;
} {
  const nativeTakeover = isRecord(conversation.native_session_takeover)
    ? conversation.native_session_takeover
    : undefined;
  const executor = executorForConversation(conversation).kind;
  const nativeThreadId = stringValue(conversation.native_thread_id) ??
    stringValue(nativeTakeover?.terminal_agent_session_id) ??
    stringValue(nativeTakeover?.terminal_agent_expected_session_id);
  if (!nativeThreadId) {
    throw new Error(
      "native acceptance evidence cannot be bound without an exact native thread"
    );
  }
  const requestHash = terminalBridgeRequestFingerprint(requestText);
  if (!requestHash) {
    throw new Error("native acceptance evidence has no exact request hash");
  }
  return {
    source: executor === "codex" ? "codex_rollout" : "claude_transcript",
    nativeThreadId,
    requestHash
  };
}

function replayExactActiveTerminalSubmission({
  options,
  terminalControl,
  requestText,
  expectedStoreDir,
  expectedSessionId,
  expectedTurnId,
  expectedMessageType = "task",
  expectedStatePath
}: {
  options: Record<string, any>;
  terminalControl: TerminalControlRef;
  requestText: string;
  expectedStoreDir: string;
  expectedSessionId?: string;
  expectedTurnId?: string;
  expectedMessageType?: "task" | "answer";
  expectedStatePath?: string;
}): boolean {
  const messageId = stringValue(options.messageId);
  if (!messageId) {
    return false;
  }
  const terminalPayload = terminalSubmissionPayload(requestText);
  const requestHash = terminalBridgeRequestFingerprint(terminalPayload);
  if (!requestHash) {
    return false;
  }
  const loadedLedger = loadTerminalBridgeDispatchLedger(terminalControl);
  const ledgerReceiptMatches = terminalLedgerReceiptHistory(loadedLedger)
    .filter((receipt) => stringValue(receipt.message_id) === messageId);
  if (ledgerReceiptMatches.length > 1) {
    throw new Error(
      `terminal idempotency key ${messageId} has multiple terminal-ledger receipts`
    );
  }
  const ledgerReceipt = ledgerReceiptMatches[0];
  const loadedLedgerMessageId = stringValue(loadedLedger?.message_id);
  const loadedLedgerStoreDir = stringValue(loadedLedger?.store_dir);
  const loadedLedgerStatePath = stringValue(loadedLedger?.state_path);
  const loadedLedgerOwner = loadedLedger && loadedLedgerMessageId === messageId
    ? loadTerminalDispatchLedgerOwner(loadedLedger)
    : undefined;
  const expectedMessageBodyHash = createHash("sha256")
    .update(requestText)
    .digest("hex");
  if (
    ledgerReceipt &&
    !(ledgerReceipt.status === "aborted" && ledgerReceipt.safe_to_retry === true) &&
    (
      !terminalDispatchRecordMatchesControl(ledgerReceipt, terminalControl) ||
      (stringValue(ledgerReceipt.store_dir) !== undefined &&
        path.resolve(String(ledgerReceipt.store_dir)) !==
          path.resolve(expectedStoreDir)) ||
      (expectedSessionId && stringValue(ledgerReceipt.session_id) !== undefined &&
        stringValue(ledgerReceipt.session_id) !== expectedSessionId) ||
      (expectedTurnId && stringValue(ledgerReceipt.turn_id) !== undefined &&
        stringValue(ledgerReceipt.turn_id) !== expectedTurnId) ||
      (expectedStatePath && stringValue(ledgerReceipt.state_path) !== undefined &&
        !sameCanonicalStatePath(ledgerReceipt.state_path, expectedStatePath)) ||
      (stringValue(ledgerReceipt.message_type) !== undefined &&
        stringValue(ledgerReceipt.message_type) !== expectedMessageType) ||
      (stringValue(ledgerReceipt.message_body_hash) !== undefined &&
        stringValue(ledgerReceipt.message_body_hash) !== expectedMessageBodyHash) ||
      (stringValue(ledgerReceipt.request_hash) !== undefined &&
        stringValue(ledgerReceipt.request_hash) !== requestHash) ||
      (stringValue(options.openclawSession) !== undefined &&
        stringValue(ledgerReceipt.openclaw_session) !== undefined &&
        stringValue(ledgerReceipt.openclaw_session) !==
          stringValue(options.openclawSession))
    )
  ) {
    throw new Error(
      `terminal idempotency key ${messageId} does not match its durable ` +
      "terminal receipt; no terminal input was sent"
    );
  }
  if (
    loadedLedger &&
    loadedLedgerMessageId === messageId &&
    (
      !terminalDispatchRecordMatchesControl(loadedLedger, terminalControl) ||
      (loadedLedgerStoreDir !== undefined &&
        path.resolve(loadedLedgerStoreDir) !== path.resolve(expectedStoreDir)) ||
      (expectedSessionId && stringValue(loadedLedger.session_id) !== undefined &&
        stringValue(loadedLedger.session_id) !== expectedSessionId) ||
      (expectedTurnId && stringValue(loadedLedger.turn_id) !== undefined &&
        stringValue(loadedLedger.turn_id) !== expectedTurnId) ||
      (expectedStatePath && loadedLedgerStatePath !== undefined &&
        !sameCanonicalStatePath(loadedLedgerStatePath, expectedStatePath)) ||
      (stringValue(loadedLedger.message_type) !== undefined &&
        stringValue(loadedLedger.message_type) !== expectedMessageType) ||
      (stringValue(loadedLedger.request_hash) !== undefined &&
        stringValue(loadedLedger.request_hash) !== requestHash) ||
      (stringValue(options.openclawSession) !== undefined &&
        loadedLedgerOwner !== undefined &&
        loadedLedgerOwner.openclaw_session !==
          stringValue(options.openclawSession))
    )
  ) {
    throw new Error(
      `terminal idempotency key ${messageId} does not match its original ` +
      "Store, Session, Turn, OpenClaw session, message, or terminal binding; " +
      "no terminal input was sent"
    );
  }
  if (replayExactStoredTerminalSubmission({
    options,
    terminalControl,
    requestText,
    requestHash,
    messageId,
    expectedStoreDir,
    expectedSessionId,
    expectedTurnId,
    expectedMessageType,
    expectedStatePath
  })) {
    return true;
  }
  if (
    ledgerReceipt &&
    (
      loadedLedgerMessageId !== messageId ||
      !["submitted", "enter_dispatched", "agent_accepted"].includes(
        String(ledgerReceipt.status)
      ) ||
      !["submitted", "enter_dispatched", "agent_accepted"].includes(
        String(loadedLedger?.status)
      )
    )
  ) {
    throw new Error(
      `terminal idempotency key ${messageId} already has durable ` +
      `${String(ledgerReceipt.status)} proof and cannot be dispatched again; ` +
      "no terminal input was sent"
    );
  }
  const incarnationLedger = resolveTerminalDispatchLedgerPaneIncarnation(
    terminalControl,
    loadedLedger
  );
  const ledger = reconcilePreparedTerminalDispatchLedger(
    terminalControl,
    incarnationLedger
  );
  if (
    !ledger ||
    !["submitted", "enter_dispatched", "agent_accepted"].includes(
      String(ledger.status)
    ) ||
    !terminalDispatchRecordMatchesControl(ledger, terminalControl) ||
    stringValue(ledger.message_id) !== messageId ||
    (
      stringValue(ledger.message_type) !== undefined &&
      stringValue(ledger.message_type) !== expectedMessageType
    ) ||
    stringValue(ledger.request_hash) !== requestHash
  ) {
    return false;
  }
  const owner = loadTerminalDispatchLedgerOwner(ledger);
  const ledgerStoreDir = stringValue(ledger.store_dir);
  const ownerStoreDir = owner
    ? managedSessionStoreDirForConversation(owner)
    : undefined;
  if (
    !owner ||
    TERMINAL_DISPATCH_RELEASE_STATUSES.has(owner.status) ||
    !ledgerStoreDir ||
    !ownerStoreDir ||
    path.resolve(ledgerStoreDir) !== path.resolve(expectedStoreDir) ||
    path.resolve(ownerStoreDir) !== path.resolve(expectedStoreDir) ||
    (expectedSessionId && sessionIdForConversation(owner) !== expectedSessionId) ||
    (expectedTurnId && turnIdForConversation(owner) !== expectedTurnId) ||
    (expectedStatePath && !sameCanonicalStatePath(ledger.state_path, expectedStatePath)) ||
    (
      stringValue(options.openclawSession) &&
      owner.openclaw_session !== stringValue(options.openclawSession)
    )
  ) {
    return false;
  }
  const submission = terminalBridgeSubmission(owner);
  const nativeTakeover = isRecord(owner.native_session_takeover)
    ? owner.native_session_takeover
    : undefined;
  if (
    stringValue(nativeTakeover?.terminal_bridge_message_id) !== messageId ||
    stringValue(submission?.message_id) !== messageId ||
    (
      stringValue(submission?.message_type) !== undefined &&
      stringValue(submission?.message_type) !== expectedMessageType
    ) ||
    stringValue(submission?.request_hash) !== requestHash
  ) {
    return false;
  }
  const executor = executorForConversation(owner);
  const nativeThreadId = stringValue(owner.native_thread_id) ??
    stringValue(nativeTakeover?.terminal_agent_session_id) ??
    stringValue(nativeTakeover?.terminal_agent_expected_session_id) ??
    sessionIdForConversation(owner);
  const proofLevel = String(ledger.status) as
    | "submitted"
    | "enter_dispatched"
    | "agent_accepted";
  const replayReceipt = terminalSubmissionReplayReceipt({
    proofLevel,
    evidence: ledger.acceptance_evidence,
    expected: {
      source: executor.kind === "codex"
        ? "codex_rollout"
        : "claude_transcript",
      nativeThreadId,
      requestHash
    }
  });
  const logPath = stringValue(ledger.event_log_path) ??
    stringValue(owner.event_log_path);
  let loggedMessage: unknown;
  if (logPath) {
    try {
      loggedMessage = readNdjsonLog(logPath).find((event) =>
        isRecord(event.message) && event.message.id === messageId
      )?.message;
    } catch {
      loggedMessage = undefined;
    }
  }
  if (
    isRecord(loggedMessage) &&
    (
      loggedMessage.type !== expectedMessageType ||
      loggedMessage.body !== requestText ||
      loggedMessage.conversation_id !== owner.conversation_id ||
      loggedMessage.session_id !== sessionIdForConversation(owner) ||
      loggedMessage.turn_id !== turnIdForConversation(owner)
    )
  ) {
    return false;
  }
  const durableMessageType = stringValue(ledger.message_type) ??
    stringValue(submission?.message_type) ??
    (isRecord(loggedMessage) ? stringValue(loggedMessage.type) : undefined);
  if (durableMessageType !== expectedMessageType) {
    return false;
  }
  const replayedMessage = isRecord(loggedMessage)
    ? loggedMessage
    : createMessage({
        conversation: owner,
        id: messageId,
        from: "openclaw",
        to: executor.actor,
        type: expectedMessageType,
        body: requestText,
        metadata: {
          executor_kind: executor.kind,
          executor_session: executor.session
        }
      });
  const acceptanceInvalid = replayReceipt.submission_outcome === "uncertain";
  printJson({
    session_id: sessionIdForConversation(owner),
    turn_id: turnIdForConversation(owner),
    conversation: owner,
    message: replayedMessage,
    delivered: replayReceipt.delivered,
    status: replayReceipt.status,
    submission_outcome: replayReceipt.submission_outcome,
    background: true,
    callback_expected: !acceptanceInvalid && Boolean(
      owner.gateway_method ?? ledger.callback_expected
    ),
    terminal_control: terminalControl,
    executor,
    replayed: replayReceipt.replayed,
    delivery_receipt: replayReceipt.delivery_receipt,
    ...(replayReceipt.do_not_retry
      ? { do_not_retry: replayReceipt.do_not_retry }
      : {}),
    reason: replayReceipt.delivered
      ? "AKK replayed the durable native acceptance receipt and sent no additional terminal input."
      : acceptanceInvalid
        ? "AKK replayed an invalid native acceptance receipt as uncertain and sent no additional terminal input."
        : "AKK replayed the original transport proof without upgrading it and sent no additional terminal input.",
    openclaw_next_action: replayReceipt.delivered
      ? openClawYieldNextAction({
          conversationId: owner.conversation_id,
          sessionId: sessionIdForConversation(owner),
          turnId: turnIdForConversation(owner),
          source: "terminal_control",
          callbackExpected: Boolean(owner.gateway_method ?? ledger.callback_expected)
        })
      : {
          action: "inspect",
          conversation_id: owner.conversation_id,
          session_id: sessionIdForConversation(owner),
          turn_id: turnIdForConversation(owner),
          do_not_retry: true,
          reason: acceptanceInvalid
            ? "Stored native acceptance evidence is invalid."
            : "Only terminal transport is proven."
        }
  });
  return true;
}

function validateStoredTerminalSubmissionMatch({
  owner,
  receipt,
  options,
  terminalControl,
  requestText,
  requestHash,
  expectedStoreDir,
  expectedSessionId,
  expectedTurnId,
  expectedMessageType,
  expectedStatePath
}: {
  owner: Conversation;
  receipt: Record<string, any>;
  options: Record<string, any>;
  terminalControl: TerminalControlRef;
  requestText: string;
  requestHash: string;
  expectedStoreDir: string;
  expectedSessionId?: string;
  expectedTurnId?: string;
  expectedMessageType: "task" | "answer";
  expectedStatePath?: string;
}): Record<string, any> | undefined {
  const messageId = required(
    stringValue(receipt.message_id),
    "stored terminal receipt message id is required"
  );
  const ownerStoreDir = managedSessionStoreDirForConversation(owner);
  const nativeTakeover = isRecord(owner.native_session_takeover)
    ? owner.native_session_takeover
    : undefined;
  const storedControl = terminalControlFromTakeover(nativeTakeover);
  const receiptStoreDir = stringValue(receipt.store_dir) ?? ownerStoreDir;
  const receiptSessionId = stringValue(receipt.session_id) ??
    sessionIdForConversation(owner);
  const receiptTurnId = stringValue(receipt.turn_id) ??
    turnIdForConversation(owner);
  const receiptOpenClawSession = stringValue(receipt.openclaw_session) ??
    owner.openclaw_session;
  const receiptTerminalEvidence = receipt.terminal_endpoint !== undefined
    ? receipt.terminal_endpoint
    : {
        kind: "tmux",
        target: stringValue(receipt.terminal_target) ?? storedControl?.target,
        socket_path: receipt.terminal_socket_path === null
          ? null
          : stringValue(receipt.terminal_socket_path) ??
            storedControl?.socketPath ??
            null,
        pane_pid: Number(
          receipt.terminal_pane_pid ?? storedControl?.panePid
        )
      };
  const requestedOpenClawSession = stringValue(options.openclawSession);
  if (
    !ownerStoreDir ||
    !receiptStoreDir ||
    path.resolve(ownerStoreDir) !== path.resolve(expectedStoreDir) ||
    path.resolve(receiptStoreDir) !== path.resolve(expectedStoreDir) ||
    !storedControl ||
    !terminalControlsShareIncarnation(storedControl, terminalControl) ||
    !terminalControlEvidenceMatches(
      receiptTerminalEvidence,
      terminalControl
    ) ||
    receiptSessionId !== sessionIdForConversation(owner) ||
    receiptTurnId !== turnIdForConversation(owner) ||
    (expectedSessionId && receiptSessionId !== expectedSessionId) ||
    (expectedTurnId && receiptTurnId !== expectedTurnId) ||
    (expectedStatePath && !sameCanonicalStatePath(owner.state_path, expectedStatePath)) ||
    (requestedOpenClawSession && receiptOpenClawSession !== requestedOpenClawSession) ||
    stringValue(receipt.request_hash) !== requestHash ||
    (stringValue(receipt.executor_kind) !== undefined &&
      stringValue(receipt.executor_kind) !== executorForConversation(owner).kind)
  ) {
    throw new Error(
      `terminal idempotency key ${messageId} does not match its original ` +
      "Store, Session, Turn, OpenClaw session, or terminal binding; no terminal input was sent"
    );
  }

  const logPath = stringValue(owner.event_log_path);
  let loggedMessages: Record<string, any>[] = [];
  if (logPath) {
    try {
      loggedMessages = readNdjsonLog(logPath)
        .filter((event) =>
          isRecord(event.message) && event.message.id === messageId
        )
        .map((event) => event.message as Record<string, any>);
    } catch {
      loggedMessages = [];
    }
  }
  if (loggedMessages.length > 1) {
    throw new Error(
      `terminal idempotency key ${messageId} has duplicate durable messages`
    );
  }
  const loggedMessage = loggedMessages[0];
  if (
    isRecord(loggedMessage) &&
    (
      loggedMessage.type !== expectedMessageType ||
      loggedMessage.body !== requestText ||
      loggedMessage.conversation_id !== owner.conversation_id ||
      loggedMessage.session_id !== sessionIdForConversation(owner) ||
      loggedMessage.turn_id !== turnIdForConversation(owner)
    )
  ) {
    throw new Error(
      `terminal idempotency key ${messageId} does not match its durable message; no terminal input was sent`
    );
  }
  const durableMessageType = stringValue(receipt.message_type) ??
    (isRecord(loggedMessage) ? stringValue(loggedMessage.type) : undefined);
  const durableMessageBodyHash = stringValue(receipt.message_body_hash) ??
    (isRecord(loggedMessage) && typeof loggedMessage.body === "string"
      ? createHash("sha256").update(loggedMessage.body).digest("hex")
      : undefined);
  const expectedMessageBodyHash = createHash("sha256")
    .update(requestText)
    .digest("hex");
  if (
    durableMessageType !== expectedMessageType ||
    durableMessageBodyHash !== expectedMessageBodyHash
  ) {
    throw new Error(
      `terminal idempotency key ${messageId} was already used for a different message; no terminal input was sent`
    );
  }
  return loggedMessage;
}

function replayExactStoredTerminalSubmission({
  options,
  terminalControl,
  requestText,
  requestHash,
  messageId,
  expectedStoreDir,
  expectedSessionId,
  expectedTurnId,
  expectedMessageType,
  expectedStatePath
}: {
  options: Record<string, any>;
  terminalControl: TerminalControlRef;
  requestText: string;
  requestHash: string;
  messageId: string;
  expectedStoreDir: string;
  expectedSessionId?: string;
  expectedTurnId?: string;
  expectedMessageType: "task" | "answer";
  expectedStatePath?: string;
}): boolean {
  const allMatches = listConversations(expectedStoreDir).flatMap((owner) =>
    terminalBridgeSubmissionReceipts(owner)
      .filter((receipt) => stringValue(receipt.message_id) === messageId)
      .map((receipt) => ({ owner, receipt }))
  );
  const validatedMatches = allMatches.map((match) => ({
    ...match,
    loggedMessage: validateStoredTerminalSubmissionMatch({
      ...match,
      options,
      terminalControl,
      requestText,
      requestHash,
      expectedStoreDir,
      expectedSessionId,
      expectedTurnId,
      expectedMessageType,
      expectedStatePath
    })
  }));
  const matches = validatedMatches.filter(({ receipt }) =>
    !(receipt.status === "aborted" && receipt.safe_to_retry === true)
  );
  if (matches.length > 1) {
    throw new Error(
      `terminal idempotency key ${messageId} has multiple durable receipts in one Store`
    );
  }
  const match = matches[0];
  if (!match) {
    for (const { owner, receipt } of validatedMatches) {
      assertSafeAbortedTerminalRetryBinding({
        owner,
        receipt,
        storeDir: expectedStoreDir,
        terminalControl,
        messageId
      });
    }
    // A prepared-stage failure with a restored ledger proves that tmux was
    // untouched. The same exact id may therefore start a fresh attempt; all
    // immutable boundaries above were still validated before allowing it.
    return false;
  }
  const { owner, receipt, loggedMessage } = match;
  const nativeTakeover = isRecord(owner.native_session_takeover)
    ? owner.native_session_takeover
    : undefined;
  const currentSubmission = terminalBridgeSubmission(owner);

  const isCurrentSubmission =
    stringValue(currentSubmission?.message_id) === messageId;
  if (
    isCurrentSubmission &&
    !TERMINAL_DISPATCH_RELEASE_STATUSES.has(owner.status)
  ) {
    return false;
  }
  if (!["submitted", "enter_dispatched", "agent_accepted"].includes(
    String(receipt.status)
  )) {
    throw new Error(
      `terminal idempotency key ${messageId} has durable ${String(receipt.status)} ` +
      "proof and must not be retried; no terminal input was sent"
    );
  }

  const executor = executorForConversation(owner);
  const nativeThreadId = stringValue(receipt.native_thread_id) ??
    stringValue(owner.native_thread_id) ??
    stringValue(nativeTakeover?.terminal_agent_session_id) ??
    stringValue(nativeTakeover?.terminal_agent_expected_session_id) ??
    sessionIdForConversation(owner);
  const proofLevel = String(receipt.status) as
    | "submitted"
    | "enter_dispatched"
    | "agent_accepted";
  const replayReceipt = terminalSubmissionReplayReceipt({
    proofLevel,
    evidence: receipt.acceptance_evidence,
    expected: {
      source: executor.kind === "codex"
        ? "codex_rollout"
        : "claude_transcript",
      nativeThreadId,
      requestHash
    }
  });
  const replayedMessage = isRecord(loggedMessage)
    ? loggedMessage
    : createMessage({
        conversation: owner,
        id: messageId,
        from: "openclaw",
        to: executor.actor,
        type: expectedMessageType,
        body: requestText,
        metadata: {
          executor_kind: executor.kind,
          executor_session: executor.session
        }
      });
  const acceptanceInvalid = replayReceipt.submission_outcome === "uncertain";
  const callbackExpected = Boolean(owner.gateway_method);
  printJson({
    session_id: sessionIdForConversation(owner),
    turn_id: turnIdForConversation(owner),
    conversation: owner,
    message: replayedMessage,
    delivered: replayReceipt.delivered,
    status: replayReceipt.status,
    submission_outcome: replayReceipt.submission_outcome,
    background: true,
    callback_expected: !acceptanceInvalid && callbackExpected,
    terminal_control: terminalControl,
    executor,
    replayed: true,
    delivery_receipt: replayReceipt.delivery_receipt,
    ...(replayReceipt.do_not_retry
      ? { do_not_retry: replayReceipt.do_not_retry }
      : {}),
    reason: replayReceipt.delivered
      ? "AKK replayed the stored durable native acceptance receipt and sent no additional terminal input."
      : acceptanceInvalid
        ? "AKK replayed an invalid stored native acceptance receipt as uncertain and sent no additional terminal input."
        : "AKK replayed the stored transport proof without upgrading it and sent no additional terminal input.",
    openclaw_next_action: replayReceipt.delivered
      ? openClawYieldNextAction({
          conversationId: owner.conversation_id,
          sessionId: sessionIdForConversation(owner),
          turnId: turnIdForConversation(owner),
          source: "terminal_control",
          callbackExpected
        })
      : {
          action: "inspect",
          conversation_id: owner.conversation_id,
          session_id: sessionIdForConversation(owner),
          turn_id: turnIdForConversation(owner),
          do_not_retry: true,
          reason: acceptanceInvalid
            ? "Stored native acceptance evidence is invalid."
            : "Only terminal transport is proven."
        }
  });
  return true;
}

function terminalSubmissionLastProvenStage(
  status: TerminalBridgeSubmissionStatus,
  previous?: string
): "prepared" | "text_injected" | "enter_dispatched" | "agent_accepted" {
  if (status === "agent_accepted") {
    return "agent_accepted";
  }
  if (
    status === "enter_dispatched" ||
    status === "submitted" ||
    status === "not_accepted"
  ) {
    return "enter_dispatched";
  }
  if (
    status === "uncertain" &&
    ["prepared", "text_injected", "enter_dispatched", "agent_accepted"].includes(
      previous ?? ""
    )
  ) {
    return previous as "prepared" | "text_injected" | "enter_dispatched" | "agent_accepted";
  }
  return status === "text_injected" ? "text_injected" : "prepared";
}

function terminalBridgeSubmission(
  conversation
): Record<string, any> | undefined {
  const nativeTakeover = isRecord(conversation?.native_session_takeover)
    ? conversation.native_session_takeover
    : undefined;
  return isRecord(nativeTakeover?.terminal_bridge_submission)
    ? nativeTakeover.terminal_bridge_submission
    : undefined;
}

function terminalBridgeSubmissionReceipts(
  conversation: Conversation
): Record<string, any>[] {
  const nativeTakeover = isRecord(conversation.native_session_takeover)
    ? conversation.native_session_takeover
    : undefined;
  const historyValue = nativeTakeover?.terminal_bridge_submission_receipts;
  if (historyValue !== undefined && !Array.isArray(historyValue)) {
    throw new Error("terminal submission receipt history is malformed");
  }
  const receipts = (Array.isArray(historyValue) ? historyValue : []).map(
    (value) => {
      if (!isRecord(value) || !stringValue(value.message_id)) {
        throw new Error("terminal submission receipt history is malformed");
      }
      return value;
    }
  );
  const ids = new Set<string>();
  for (const receipt of receipts) {
    const id = String(receipt.message_id);
    if (ids.has(id)) {
      throw new Error(`terminal submission receipt ${id} is duplicated`);
    }
    ids.add(id);
  }
  const current = terminalBridgeSubmission(conversation);
  const currentId = stringValue(current?.message_id);
  if (current && currentId && ids.has(currentId)) {
    const historical = receipts.find((receipt) =>
      stringValue(receipt.message_id) === currentId
    );
    if (!historical || canonicalJson(historical) !== canonicalJson(current)) {
      throw new Error(
        `terminal submission receipt ${currentId} conflicts with its current generation`
      );
    }
  }
  return current && currentId && !ids.has(currentId)
    ? [...receipts, current]
    : receipts;
}

function unresolvedTerminalBridgeSubmission(conversation): Record<string, any> | undefined {
  const submission = terminalBridgeSubmission(conversation);
  return submission &&
    ["prepared", "text_injected", "enter_dispatched", "not_accepted", "uncertain"]
      .includes(String(submission.status))
    ? submission
    : undefined;
}

function assertNoUnresolvedTerminalBridgeSubmission(
  storeDir: string,
  terminalControl: TerminalControlRef,
  currentConversationId: string,
  requestText: string
): void {
  const requestHash = terminalBridgeRequestFingerprint(requestText);
  for (const candidate of listConversations(storeDir)) {
    const submission = terminalBridgeSubmission(candidate);
    if (
      candidate.conversation_id === currentConversationId ||
      !submission ||
      TERMINAL_DISPATCH_RELEASE_STATUSES.has(
        effectiveTurnStatus(candidate)
      ) ||
      ![
        "prepared",
        "text_injected",
        "enter_dispatched",
        "agent_accepted",
        "submitted",
        "not_accepted",
        "uncertain"
      ].includes(String(submission.status))
    ) {
      continue;
    }
    if (
      ["submitted", "agent_accepted"].includes(String(submission.status)) &&
      stringValue(submission.request_hash) !== requestHash
    ) {
      continue;
    }
    const nativeTakeover = isRecord(candidate.native_session_takeover)
      ? candidate.native_session_takeover
      : undefined;
    if (
      terminalControlsShareIncarnation(
        terminalControlFromTakeover(nativeTakeover),
        terminalControl
      )
    ) {
      throw new Error(
        `terminal ${terminalControl.target} has a conflicting ${String(submission.status)} ` +
        `AKK submission in ${candidate.conversation_id}; inspect that conversation and pane, ` +
        "then close it before retrying"
      );
    }
  }
}

function stallOtherTerminalBridgeConversationsForUncertainDispatch({
  storeDir,
  terminalControl,
  currentConversationId,
  uncertainMessageId
}: {
  storeDir: string;
  terminalControl: TerminalControlRef;
  currentConversationId: string;
  uncertainMessageId: string;
}): string[] {
  const stalledConversationIds: string[] = [];
  for (const listed of listConversations(storeDir)) {
    if (
      listed.conversation_id === currentConversationId ||
      !SESSION_SEND_BLOCKING_STATUSES.has(listed.status)
    ) {
      continue;
    }
    const listedTakeover = isRecord(listed.native_session_takeover)
      ? listed.native_session_takeover
      : undefined;
    if (
      listedTakeover?.terminal_bridge !== true ||
      !terminalControlsShareIncarnation(
        terminalControlFromTakeover(listedTakeover),
        terminalControl
      )
    ) {
      continue;
    }
    const listedStatePath = stringValue(listed.state_path);
    if (!listedStatePath) {
      continue;
    }
    const releaseStateLock = acquireFileLock(`${listedStatePath}.lock`);
    try {
      const current = loadState(listedStatePath);
      const currentTakeover = isRecord(current.native_session_takeover)
        ? current.native_session_takeover
        : undefined;
      if (
        !SESSION_SEND_BLOCKING_STATUSES.has(current.status) ||
        currentTakeover?.terminal_bridge !== true ||
        !terminalControlsShareIncarnation(
          terminalControlFromTakeover(currentTakeover),
          terminalControl
        )
      ) {
        continue;
      }
      const stalledAt = cliNow().toISOString();
      const stalledConversation = {
        ...current,
        status: "stalled" as const,
        stalled_at: stalledAt,
        stalled_reason: TERMINAL_BRIDGE_UNCERTAIN_COLLATERAL_STALL_REASON,
        native_session_takeover: {
          ...currentTakeover,
          terminal_bridge_uncertain_dispatch_fence: {
            message_id: uncertainMessageId,
            observed_at: stalledAt,
            previous_status: current.status
          }
        },
        updated_at: stalledAt
      };
      saveState(listedStatePath, stalledConversation);
      try {
        appendEvent(logPathForStatePath(listedStatePath), {
          ts: stalledAt,
          conversation_id: current.conversation_id,
          event: "terminal_bridge_stalled_by_uncertain_dispatch",
          terminal_control: terminalControl,
          uncertain_message_id: uncertainMessageId
        });
      } catch {
        // The stalled state and terminal-level ledger are the authoritative fence.
      }
      stalledConversationIds.push(current.conversation_id);
    } finally {
      releaseStateLock();
    }
  }
  return stalledConversationIds;
}

interface TerminalBridgeCollateralStallRepairEvidence {
  uncertainMessageId: string;
  ownerConversationId: string;
  restoredStatus: "idle";
}

function exactTerminalBridgeCollateralStallRepairEvidence({
  conversation,
  storeDir
}: {
  conversation: Conversation;
  storeDir: string;
}): TerminalBridgeCollateralStallRepairEvidence | undefined {
  if (
    conversation.status !== "stalled" ||
    conversation.stalled_reason !==
      TERMINAL_BRIDGE_UNCERTAIN_COLLATERAL_STALL_REASON
  ) {
    return undefined;
  }
  const takeover = isRecord(conversation.native_session_takeover)
    ? conversation.native_session_takeover
    : undefined;
  const fence = isRecord(
    takeover?.terminal_bridge_uncertain_dispatch_fence
  )
    ? takeover.terminal_bridge_uncertain_dispatch_fence
    : undefined;
  const uncertainMessageId = stringValue(fence?.message_id);
  const fenceObservedAt = stringValue(fence?.observed_at);
  const previousStatus = stringValue(fence?.previous_status);
  const ownMessageId = stringValue(takeover?.terminal_bridge_message_id);
  const ownSubmission = terminalBridgeSubmission(conversation);
  const completionClaim = isRecord(takeover?.terminal_bridge_completion_claim)
    ? takeover.terminal_bridge_completion_claim
    : undefined;
  const callbackDelivery = isRecord(conversation.callback_delivery)
    ? conversation.callback_delivery
    : undefined;
  const callbackMessage = isRecord(callbackDelivery?.message)
    ? callbackDelivery.message
    : undefined;
  const idleSince = stringValue(conversation.idle_since);
  const deliveredAt = stringValue(callbackDelivery?.delivered_at);
  const claimedAt = stringValue(completionClaim?.claimed_at);
  const fenceAtMs = validTimestampMs(fenceObservedAt);
  const idleAtMs = validTimestampMs(idleSince);
  const deliveredAtMs = validTimestampMs(deliveredAt);
  const claimedAtMs = validTimestampMs(claimedAt);
  if (
    takeover?.terminal_bridge !== true ||
    !uncertainMessageId ||
    !fenceObservedAt ||
    fenceAtMs === undefined ||
    uncertainMessageId === ownMessageId ||
    (previousStatus !== undefined && previousStatus !== "idle") ||
    conversation.stalled_at !== fenceObservedAt ||
    conversation.updated_at !== fenceObservedAt ||
    !idleSince ||
    idleAtMs === undefined ||
    idleAtMs > fenceAtMs ||
    !ownMessageId ||
    ownSubmission?.status !== "agent_accepted" ||
    stringValue(ownSubmission.message_id) !== ownMessageId ||
    stringValue(ownSubmission.session_id) !==
      sessionIdForConversation(conversation) ||
    stringValue(ownSubmission.turn_id) !== turnIdForConversation(conversation) ||
    !completionClaim ||
    stringValue(completionClaim.terminal_bridge_message_id) !== ownMessageId ||
    completionClaim.outcome !== "success" ||
    !claimedAt ||
    claimedAtMs === undefined ||
    claimedAtMs > fenceAtMs ||
    callbackDelivery?.status !== "delivered" ||
    callbackDelivery.final_status !== "idle" ||
    callbackDelivery.preserve_conversation_status !== true ||
    !callbackMessage ||
    callbackMessage.type !== "done" ||
    callbackMessage.requires_response !== false ||
    stringValue(callbackMessage.id) !==
      stringValue(completionClaim.callback_message_id) ||
    stringValue(callbackMessage.conversation_id) !==
      conversation.conversation_id ||
    stringValue(callbackMessage.session_id) !==
      sessionIdForConversation(conversation) ||
    stringValue(callbackMessage.turn_id) !== turnIdForConversation(conversation) ||
    stringValue(
      isRecord(callbackMessage.metadata)
        ? callbackMessage.metadata.terminal_bridge_message_id
        : undefined
    ) !== ownMessageId ||
    !deliveredAt ||
    deliveredAtMs === undefined ||
    deliveredAtMs > fenceAtMs
  ) {
    return undefined;
  }
  const control = terminalControlForManagedConversation(conversation);
  if (!control) {
    return undefined;
  }
  // The target state lock is already held by the caller. Rescan owner state
  // now instead of trusting the unlocked discovery snapshot used to find the
  // target candidate.
  const ownerCandidates = listConversations(storeDir).filter((candidate) => {
    if (candidate.conversation_id === conversation.conversation_id) {
      return false;
    }
    const candidateTakeover = isRecord(candidate.native_session_takeover)
      ? candidate.native_session_takeover
      : undefined;
    const candidateSubmission = terminalBridgeSubmission(candidate);
    return candidateTakeover?.terminal_bridge === true &&
      stringValue(candidateTakeover.terminal_bridge_message_id) ===
        uncertainMessageId &&
      stringValue(candidateSubmission?.message_id) === uncertainMessageId &&
      terminalControlsShareIncarnation(
        terminalControlForManagedConversation(candidate),
        control
      );
  });
  if (ownerCandidates.length !== 1) {
    return undefined;
  }
  const ownerListed = ownerCandidates[0];
  const ownerStatePath = stringValue(ownerListed.state_path);
  if (!ownerStatePath) {
    return undefined;
  }
  let owner: Conversation;
  let ownerEvents: Record<string, any>[];
  let events: Record<string, any>[];
  try {
    owner = loadState(ownerStatePath);
    ownerEvents = readNdjsonLog(
      stringValue(owner.event_log_path) ?? logPathForStatePath(ownerStatePath)
    );
    const statePath = stringValue(conversation.state_path);
    if (!statePath) {
      return undefined;
    }
    events = readNdjsonLog(
      stringValue(conversation.event_log_path) ??
        logPathForStatePath(statePath)
    );
  } catch {
    return undefined;
  }
  const ownerTakeover = isRecord(owner.native_session_takeover)
    ? owner.native_session_takeover
    : undefined;
  const ownerSubmission = terminalBridgeSubmission(owner);
  const ownerClosedAt = stringValue(owner.closed_at);
  const ownerClosedAtMs = validTimestampMs(ownerClosedAt);
  if (
    owner.conversation_id !== ownerListed.conversation_id ||
    owner.status !== "closed" ||
    !ownerClosedAt ||
    ownerClosedAtMs === undefined ||
    ownerClosedAtMs < fenceAtMs ||
    !stringValue(owner.close_reason) ||
    owner.updated_at !== ownerClosedAt ||
    ownerTakeover?.terminal_bridge !== true ||
    stringValue(ownerTakeover.terminal_bridge_message_id) !==
      uncertainMessageId ||
    ownerSubmission?.status !== "uncertain" ||
    stringValue(ownerSubmission.message_id) !== uncertainMessageId ||
    stringValue(ownerSubmission.session_id) !== sessionIdForConversation(owner) ||
    stringValue(ownerSubmission.turn_id) !== turnIdForConversation(owner) ||
    isRecord(ownerTakeover.terminal_bridge_uncertain_dispatch_fence) ||
    !terminalControlsShareIncarnation(
      terminalControlForManagedConversation(owner),
      control
    )
  ) {
    return undefined;
  }
  const callbackMessageId = stringValue(callbackMessage.id) as string;
  const hasCompletionClaim = events.some((event) =>
    event.event === "terminal_bridge_completion_claimed" &&
    event.conversation_id === conversation.conversation_id &&
    event.terminal_bridge_message_id === ownMessageId &&
    event.callback_message_id === callbackMessageId &&
    event.completion_fingerprint === completionClaim.completion_fingerprint &&
    event.completion_id === completionClaim.completion_id &&
    event.outcome === "success" &&
    event.ts === claimedAt
  );
  const hasCompletionDetected = events.some((event) =>
    event.event === "terminal_bridge_completion_detected" &&
    event.conversation_id === conversation.conversation_id &&
    event.terminal_bridge_message_id === ownMessageId &&
    event.callback_message_id === callbackMessageId &&
    event.completion_id === completionClaim.completion_id &&
    event.completion_outcome === "success" &&
    validTimestampMs(event.ts) !== undefined &&
    (validTimestampMs(event.ts) as number) <= fenceAtMs
  );
  const hasDeliveredCallback = events.some((event) =>
    event.event === "callback_delivery_succeeded" &&
    event.conversation_id === conversation.conversation_id &&
    event.message_id === callbackMessageId &&
    event.status === "idle" &&
    event.ts === deliveredAt
  );
  const hasExactFence = events.some((event) =>
    event.event === "terminal_bridge_stalled_by_uncertain_dispatch" &&
    event.conversation_id === conversation.conversation_id &&
    event.uncertain_message_id === uncertainMessageId &&
    event.ts === fenceObservedAt
  );
  const hasExactOwnerClose = ownerEvents.some((event) =>
    event.event === "conversation_closed" &&
    event.conversation_id === owner.conversation_id &&
    event.status === "closed" &&
    event.ts === ownerClosedAt &&
    event.reason === owner.close_reason
  );
  if (
    !hasCompletionClaim ||
    !hasCompletionDetected ||
    !hasDeliveredCallback ||
    !hasExactFence ||
    !hasExactOwnerClose
  ) {
    return undefined;
  }
  return {
    uncertainMessageId,
    ownerConversationId: owner.conversation_id,
    restoredStatus: "idle"
  };
}

function reconcileTerminalBridgeCollateralStalls(
  storeDir: string,
  conversationId?: string
): {
  checked: number;
  repaired: number;
  skipped: number;
  errors: string[];
  items: Record<string, unknown>[];
} {
  const reservedSourceTurnIds = new Set(
    listDeferredForegroundTransfers(storeDir)
      .filter((transfer) =>
        transfer.version === 2 &&
        transfer.source_kind === "candidate_rollout_quiescent" &&
        !["resolved", "abort_resolved"].includes(transfer.status)
      )
      .flatMap((transfer) =>
        (transfer.source_turn_history ?? []).map((turn) => turn.turn_id)
      )
  );
  const candidates = listConversations(storeDir).filter((conversation) => {
    const takeover = isRecord(conversation.native_session_takeover)
      ? conversation.native_session_takeover
      : undefined;
    return (
      conversationId === undefined ||
      conversation.conversation_id === conversationId
    ) &&
      !reservedSourceTurnIds.has(turnIdForConversation(conversation)) &&
      conversation.status === "stalled" &&
      isRecord(takeover?.terminal_bridge_uncertain_dispatch_fence);
  });
  let repaired = 0;
  let skipped = 0;
  const errors: string[] = [];
  const items: Record<string, unknown>[] = [];
  for (const listed of candidates) {
    const statePath = stringValue(listed.state_path);
    if (!statePath) {
      skipped += 1;
      continue;
    }
    let releaseStateLock: (() => void) | undefined;
    try {
      releaseStateLock = acquireFileLock(`${statePath}.lock`);
      const current = loadState(statePath);
      const evidence = exactTerminalBridgeCollateralStallRepairEvidence({
        conversation: current,
        storeDir
      });
      if (!evidence) {
        skipped += 1;
        continue;
      }
      const takeover = {
        ...(current.native_session_takeover as Record<string, any>)
      };
      delete takeover.terminal_bridge_uncertain_dispatch_fence;
      const repairedAt = cliNow().toISOString();
      takeover.terminal_bridge_collateral_stall_repair = {
        repaired_at: repairedAt,
        uncertain_message_id: evidence.uncertainMessageId,
        uncertain_owner_conversation_id: evidence.ownerConversationId,
        restored_status: evidence.restoredStatus,
        evidence:
          "foreign_uncertain_fence+completion_claim+delivered_callback+closed_owner"
      };
      const repairedConversation: Conversation = {
        ...current,
        status: evidence.restoredStatus,
        native_session_takeover: takeover,
        updated_at: repairedAt
      };
      delete repairedConversation.stalled_at;
      delete repairedConversation.stalled_reason;
      saveState(statePath, repairedConversation);
      let eventWarning: string | undefined;
      try {
        appendEvent(
          stringValue(current.event_log_path) ?? logPathForStatePath(statePath),
          {
            ts: repairedAt,
            conversation_id: current.conversation_id,
            event: "terminal_bridge_collateral_stall_repaired",
            uncertain_message_id: evidence.uncertainMessageId,
            uncertain_owner_conversation_id: evidence.ownerConversationId,
            previous_status: "stalled",
            restored_status: evidence.restoredStatus,
            evidence:
              "foreign_uncertain_fence+completion_claim+delivered_callback+closed_owner"
          }
        );
      } catch (error) {
        eventWarning = error instanceof Error ? error.message : String(error);
        runtimeLog("warn", "terminal_bridge_collateral_stall_repair_event_failed", {
          conversation_id: current.conversation_id,
          uncertain_message_id: evidence.uncertainMessageId,
          error: eventWarning
        });
      }
      repaired += 1;
      items.push({
        conversation_id: current.conversation_id,
        status: "repaired",
        reason: "legacy_terminal_bridge_collateral_stall",
        uncertain_message_id: evidence.uncertainMessageId,
        uncertain_owner_conversation_id: evidence.ownerConversationId,
        restored_status: evidence.restoredStatus,
        ...(eventWarning ? { event_warning: eventWarning } : {})
      });
    } catch (error) {
      skipped += 1;
      const reason = error instanceof Error ? error.message : String(error);
      errors.push(`${listed.conversation_id}: ${reason}`);
      items.push({
        conversation_id: listed.conversation_id,
        status: "error",
        reason
      });
    } finally {
      releaseStateLock?.();
    }
  }
  return {
    checked: candidates.length,
    repaired,
    skipped,
    errors,
    items
  };
}

function environmentWithoutGatewayTokens(): NodeJS.ProcessEnv {
  const environment = { ...cliEnv() };
  delete environment.AKK_GATEWAY_TOKEN;
  delete environment.OPENCLAW_GATEWAY_TOKEN;
  return environment;
}

async function runList(options) {
  const storeDir = expandHome(options.storeDir ?? options.logDir ?? defaultStoreDir(cliCwd()));
  const store = inspectStoreCompatibility(storeDir);
  const reconciliation = options.reconcile === true
    ? await reconcileStoreForList(storeDir, options)
    : {
        status: "disabled",
        reason: "standalone list is read-only unless --reconcile is supplied"
      };
  const includeAll = Boolean(options.all);
  const agentFilter = options.agent ? resolveExecutor({ kind: options.agent }).kind : undefined;
  const statusFilter = options.status;
  const allStoredConversations = listConversations(storeDir);
  const allManagedConversations = allStoredConversations
    .filter(isDiscoverableTmuxConversation);
  const managedSessions = store.readable
    ? listManagedSessions(storeDir)
    : [];
  const storedConversations = allManagedConversations
    .filter((conversation) => includeAll || isActiveStatus(conversation.status))
    .filter((conversation) =>
      matchesConfiguredWorkspace(options.workspace, conversation.workspace)
    )
    .filter((conversation) =>
      !agentFilter || executorForConversation(conversation).kind === agentFilter
    )
    .filter((conversation) => !statusFilter || conversation.status === statusFilter);
  const terminalScan = await buildTerminalListGroup({ options, agentFilter, statusFilter });
  const physicalTerminals = terminalScan.terminalControlled.filter((entry) =>
    matchesConfiguredWorkspace(
      options.workspace,
      entry.workspace ?? entry.cwd
    )
  );
  const projection = terminalFirstListProjection({
    storeDir,
    terminals: physicalTerminals,
    managedSessions,
    sessionAuthorityRequired:
      Number(store.writer_protocol) >= STORE_SESSION_AUTHORITY_PROTOCOL,
    allConversations: allManagedConversations.filter((conversation) =>
      matchesConfiguredWorkspace(options.workspace, conversation.workspace)
    ),
    displayedConversations: storedConversations,
    includeAll,
    managedOnly: options.managedOnly === true,
    statusFilter,
    mutationsAllowed: store.writable === true
  });

  printJson({
    store_dir: storeDir,
    store,
    reconciliation,
    action_contracts: listActionContracts(),
    terminals: projection.terminals,
    unavailable_managed_turns: projection.unavailableManagedTurns,
    terminal_scan: {
      ...terminalScan.summary,
      terminal_count: projection.terminals.length
    }
  });
  runtimeLog("info", "terminals_listed", {
    store_dir: storeDir,
    terminal_count: projection.terminals.length,
    unavailable_managed_turn_count: projection.unavailableManagedTurns.length,
    terminal_scan_error: terminalScan.summary.error,
    include_all: includeAll,
    agent_filter: agentFilter,
    status_filter: statusFilter,
    reconciliation
  });
}

async function reconcileStoreForList(storeDir, options) {
  try {
    ensureStoreWritable(storeDir);
  } catch (error) {
    if (isRecord(error) && error.code === "AKK_STORE_INCOMPATIBLE") {
      return {
        status: "skipped",
        reason: error instanceof Error ? error.message : String(error),
        store: inspectStoreCompatibility(storeDir)
      };
    }
    throw error;
  }

  const monitors = await reconcileMonitors(options, {
    includeCallbackRecovery: false,
    reason: "list_reconciliation",
    conversationId: undefined
  });
  const idle = reconcileIdleConversations(storeDir, options);
  return {
    status: "completed",
    checked: Math.max(idle.checked, monitors.checked),
    changed: idle.closed + monitors.launched + monitors.repaired,
    closed: idle.closed,
    repaired: monitors.repaired,
    collateral_stalls_checked: monitors.collateral_stalls_checked,
    collateral_stalls_skipped: monitors.collateral_stalls_skipped,
    collateral_stall_repairs: monitors.items.filter((item) =>
      item.status === "repaired"
    ),
    monitors_launched: monitors.launched,
    monitors_already_running: monitors.already_running,
    skipped: idle.skipped + monitors.skipped,
    errors: monitors.errors,
    idle_timeout_minutes: idle.idle_timeout_minutes
  };
}

async function buildTerminalListGroup({ options, agentFilter, statusFilter }) {
  const empty = {
    terminalControlled: [],
    summary: {
      enabled: false,
      agents: [],
      error: undefined
    }
  };
  if (options.managedOnly) {
    return empty;
  }
  const registry = createRuntimeTerminalAgentRegistry(options);
  const adapters = agentFilter
    ? [registry.get(agentFilter)].filter((adapter) => adapter !== undefined)
    : registry.list();
  if (agentFilter && adapters.length === 0) {
    return {
      ...empty,
      summary: {
        enabled: true,
        agents: [],
        skipped: `terminal agent adapter is not registered for ${agentFilter}`
      }
    };
  }

  const terminalProvider = createTerminalControlProvider(options);
  const bridge = createTerminalAgentBridge(options, terminalProvider, registry);
  const terminalDiagnostics = options.terminalDebug
    ? await terminalControlDiagnostics(terminalProvider)
    : undefined;
  const terminalControlled: Record<string, any>[] = [];
  let activeCount = 0;
  const errors: string[] = [];
  try {
    const processSource = createTerminalProcessSource(options);
    const snapshots = await processSource.listProcessSnapshots((snapshot) =>
      adapters.some((adapter) =>
        adapter.capabilities.processDiscovery && adapter.classifyProcess(snapshot) !== undefined
      ),
      { includeAncestors: true }
    );
    const activeSessions = await bridge.listProcesses(
      snapshots,
      adapters.map((adapter) => adapter.agent)
    );
    const rootSessions = rootActiveProcesses(activeSessions);
    const controlledSessions = rootSessions.filter(
      (session) => session.terminalControl !== undefined
    );
    activeCount = controlledSessions.length;
    for (const session of controlledSessions) {
      terminalControlled.push(await terminalControlledListEntry(
        session,
        activeSessions,
        options,
        bridge
      ));
    }
  } catch (error) {
    errors.push(error instanceof Error ? error.message : String(error));
  }

  return {
    terminalControlled,
    summary: {
      enabled: true,
      agents: adapters.map((adapter) => adapter.agent),
      active_count: activeCount,
      terminal_count: terminalControlled.length,
      approval_scan: options.noApprovalScan ? "disabled" : "enabled",
      diagnostics: terminalDiagnostics,
      error: errors.length > 0 ? errors.join("; ") : undefined
    }
  };
}

async function terminalControlDiagnostics(provider: TerminalControlProvider) {
  return provider.diagnostics();
}

function managedTurnListEntry(
  task,
  {
    terminalBridge = false,
    approvalState,
    conversation
  }: {
    terminalBridge?: boolean;
    approvalState?: Record<string, any>;
    conversation?: Record<string, any>;
  } = {}
) {
  const sessionId = stringValue(task.session_id) ??
    stringValue(task.conversation_id);
  const turnId = stringValue(task.turn_id) ??
    stringValue(task.conversation_id) ??
    String(task.id ?? "");
  const entry = {
    ...task,
    session_id: sessionId,
    turn_id: turnId,
    id: turnId,
    short_ref: sessionShortRef(turnId),
    source: "managed_turn",
    ...(approvalState ? { approval_state: approvalState } : {}),
    commands: {
      respond: task.status === "waiting_for_openclaw",
      cancel: isWaitingForAgent(task.status),
      close: task.status !== "closed",
      status: true,
      approve: terminalBridge && isActiveStatus(task.status)
    }
  };
  const availableActions = availableListActions(entry, { conversation });
  const { commands: _commands, ...publicEntry } = entry;
  return {
    ...publicEntry,
    available_actions: availableActions
  };
}

async function terminalControlledListEntry(
  session: ActiveTerminalProcess,
  activeSessions: ActiveTerminalProcess[],
  options,
  bridge: TerminalAgentBridge = createTerminalAgentBridge(options)
) {
  const terminalControl = session.terminalControl;
  if (!terminalControl) {
    throw new Error(`process ${session.pid} is not terminal-controlled`);
  }
  const terminalState = await listStateForTerminal(
    session.agent,
    terminalControl,
    options,
    bridge,
    {
      pid: session.pid,
      cwd: session.cwd,
      // Raw Codex status and approval use the exact full terminal selector as
      // their runtime conversation identity. Use the same identity while
      // projecting list actions so a prompt-bound terminal token can be
      // revalidated by the later status/approve calls.
      ...(session.agent === "codex"
        ? { conversationId: bridge.terminalConversationId(session) }
        : { sessionId: session.sessionId }),
      terminalTarget: terminalControl.target
    }
  );
  const orphanedDispatch =
    orphanedTerminalDispatchForRecovery(terminalControl);
  let codexIdentityContext:
    | ReturnType<typeof codexManagedIdentityResolutionContext>
    | undefined;
  if (session.agent === "codex") {
    try {
      codexIdentityContext = codexManagedIdentityResolutionContext({
        storeDir: storeDirFromOptions(options),
        terminal: {
          conversationId: bridge.terminalConversationId(session),
          agent: session.agent,
          pid: session.pid,
          terminalControl
        }
      });
    } catch (error) {
      // Preserve generic discovery when Store hints are unavailable. Once an
      // exact hint exists, however, the constrained resolver below must fail
      // closed rather than retrying without its managed lineage fences.
      runtimeLog("warn", "terminal_managed_identity_context_unavailable", {
        agent: session.agent,
        terminal_target: terminalControl.target,
        pid: session.pid,
        error: error instanceof Error ? error.message : String(error)
      });
    }
  }
  const nativeIdentityObservation =
    await observeCurrentNativeAgentSessionIdentity({
      options,
      agent: session.agent,
      pid: session.pid,
      cwd: session.cwd ?? terminalControl.currentPath,
      preferredSessionId: codexIdentityContext?.preferredSessionId,
      allowedCompanionIdentity:
        codexIdentityContext?.companions.primary,
      allowedAdditionalIdentities:
        codexIdentityContext?.companions.additional
    });
  const nativeAgentIdentity = nativeIdentityObservation.status === "resolved"
    ? nativeIdentityObservation.identity
    : undefined;
  let codexOpenRootRolloutInventory:
    | CodexOpenRootRolloutInventory
    | undefined;
  if (session.agent === "codex") {
    try {
      const inventory = await inspectCodexOpenRootRolloutInventory({
        options,
        pid: session.pid,
        cwd: session.cwd ?? terminalControl.currentPath
      });
      if (inventory.roots.length > 0) {
        codexOpenRootRolloutInventory = inventory;
      }
    } catch (error) {
      runtimeLog("warn", "terminal_codex_open_root_inventory_unavailable", {
        terminal_target: terminalControl.target,
        pid: session.pid,
        error: error instanceof Error ? error.message : String(error)
      });
    }
  }
  if (nativeIdentityObservation.status === "unavailable") {
    runtimeLog("warn", "terminal_native_session_identity_unavailable", {
      agent: session.agent,
      terminal_target: terminalControl.target,
      pid: session.pid,
      error: nativeIdentityObservation.reason
    });
  }
  let nativeProcessUuid = nativeAgentIdentity?.processUuid;
  let nativeProcessBirth = nativeAgentIdentity?.processBirth;
  let nativeProcessEvidence = nativeAgentIdentity?.evidence;
  if (codexOpenRootRolloutInventory) {
    nativeProcessUuid = codexOpenRootRolloutInventory.processUuid;
    nativeProcessBirth = codexOpenRootRolloutInventory.processBirth;
    nativeProcessEvidence = "codex_open_root_rollout_inventory";
  }
  if (
    session.agent === "codex" &&
    (!nativeProcessUuid || !nativeProcessBirth)
  ) {
    try {
      const incarnation = codexProcessIncarnationForPid(session.pid);
      nativeProcessUuid = incarnation.processUuid;
      nativeProcessBirth = incarnation.processBirth;
      nativeProcessEvidence = nativeProcessEvidence ?? incarnation.evidence;
    } catch (error) {
      runtimeLog("warn", "terminal_process_incarnation_unavailable", {
        agent: session.agent,
        terminal_target: terminalControl.target,
        pid: session.pid,
        error: error instanceof Error ? error.message : String(error)
      });
    }
  }
  const statusCardObservation = session.agent === "codex" &&
      typeof terminalState.screen_excerpt === "string"
    ? bridge.registry.require("codex").observeThreadLifecycle?.({
        operation: { kind: "new_thread" },
        phase: "before",
        screen: terminalState.screen_excerpt
      })
    : undefined;
  const statusCardNativeThreadId =
    statusCardObservation?.status === "observed" &&
      terminalState.activity_state === "idle" &&
      terminalState.approval_state.blocked !== true &&
      isExactNativeThreadId(statusCardObservation.nativeThreadId)
      ? statusCardObservation.nativeThreadId
      : undefined;
  const agentVersion = agentVersionForRunningProcess(
    session.agent,
    session.pid,
    options
  );
  const lifecycleCapability = bridge.registry.require(session.agent)
    .probeThreadLifecycle?.(agentVersion) ?? {
      status: "unsupported" as const,
      agentVersion,
      newThread: false,
      resumeExact: false,
      reason: "native thread lifecycle is unavailable"
    };
  const nativeInspectionCapability = bridge.registry.require(session.agent)
    .probeNativeInspection?.(agentVersion) ?? {
      status: "unsupported" as const,
      agentVersion,
      statusInspection: false,
      reason: "native inspection is unavailable"
    };
  const codexLatentClearResumeObservationValue = session.agent === "codex"
    ? codexLatentClearResumeObservation({
        screen: terminalState.screen_excerpt,
        agentVersion
      })
    : undefined;
  const lifecycleBindingToken = unmanagedTerminalBindingToken({
    terminalId: bridge.terminalConversationId(session),
    terminalControl,
    agent: session.agent,
    pid: session.pid,
    workspace: session.cwd ?? terminalControl.currentPath ?? cliCwd(),
    nativeThreadId: nativeAgentIdentity?.sessionId,
    processUuid: nativeProcessUuid,
    processBirth: nativeProcessBirth,
    rollout: nativeAgentIdentity?.rollout
  });
  const codexLifecycleIncarnationAvailable =
    session.agent !== "codex" ||
    Boolean(nativeProcessUuid && nativeProcessBirth);
  const terminalHasBlockingTurn = terminalIncarnationBlockingTurns(
    storeDirFromOptions(options),
    terminalControl
  ).length > 0;
  let automatedInputComposerReady = nativeInspectionComposerEmpty(
    session.agent,
    terminalState.screen_excerpt
  );
  if (
    session.agent === "codex" &&
    (
      terminalState.activity_state === "idle" ||
      (
        terminalState.activity_state === "unknown" &&
        (
          nativeIdentityObservation.status === "verified_absent" ||
          codexOpenRootRolloutInventory !== undefined
        )
      )
    ) &&
    terminalState.approval_state.blocked !== true &&
    terminalControl.capabilities.includes("send_keys") &&
    terminalControl.capabilities.includes("screen_status")
  ) {
    try {
      const provider = createTerminalControlProvider(options);
      const resolvedTerminal = await provider.resolve(
        provider.endpoint(terminalControl)
      );
      const styledScreen = await provider.capture(
        resolvedTerminal,
        { scrollbackLines: 40, preserveEscapes: true }
      );
      automatedInputComposerReady = codexStyledComposerEmpty(styledScreen);
    } catch {
      // Advertising an input action is optional. The action itself repeats the
      // same styled composer proof under the terminal lock before any input.
      automatedInputComposerReady = false;
    }
  }
  const entry = {
    id: bridge.terminalConversationId(session),
    short_ref: sessionShortRef(bridge.terminalConversationId(session)),
    source: "terminal",
    agent: session.agent,
    process_state: "active",
    pid: session.pid,
    child_pids: childPidsForRoot(session, activeSessions),
    command: session.command,
    cwd: session.cwd,
    workspace: session.cwd,
    elapsed: session.elapsed,
    native_agent_session_id: nativeAgentIdentity?.sessionId,
    native_agent_status_card_session_id: statusCardNativeThreadId,
    native_agent_process_uuid: nativeProcessUuid,
    native_agent_process_birth: nativeProcessBirth,
    native_agent_rollout: nativeAgentIdentity?.rollout,
    native_agent_identity_evidence: nativeProcessEvidence,
    native_agent_identity_observation: {
      status: nativeIdentityObservation.status,
      ...(nativeIdentityObservation.status === "unavailable"
        ? { reason: nativeIdentityObservation.reason }
        : nativeIdentityObservation.status === "verified_absent"
          ? { evidence: nativeIdentityObservation.evidence }
          : {})
    },
    agent_version: agentVersion,
    native_thread_lifecycle: lifecycleCapability,
    native_inspection: nativeInspectionCapability,
    lifecycle_binding_token: lifecycleBindingToken,
    confidence: session.confidence,
    reason: session.reason,
    terminal_control: terminalControl,
    approval_state: terminalState.approval_state,
    activity_state: terminalState.activity_state,
    activity_reason: terminalState.activity_reason,
    // Internal action-projection evidence. terminalFirstListProjection strips
    // this field after gating every automated-input action that can follow a
    // human native-thread switch.
    _automated_input_composer_ready: automatedInputComposerReady,
    ...(codexLatentClearResumeObservationValue
      ? {
          _codex_latent_clear_resume: {
            source_native_thread_id:
              codexLatentClearResumeObservationValue.sourceNativeThreadId,
            fingerprint: codexLatentClearResumeObservationValue.fingerprint
          }
        }
      : {}),
    ...(codexOpenRootRolloutInventory
      ? {
          _codex_open_root_rollout_inventory:
            codexOpenRootRolloutInventory
        }
      : {}),
    ...(orphanedDispatch
      ? {
          orphaned_terminal_dispatch: {
            kind: stringValue(orphanedDispatch.kind) ?? "turn",
            status: orphanedDispatch.status,
            owner_conversation_id:
              stringValue(orphanedDispatch.conversation_id),
            message_id: stringValue(orphanedDispatch.message_id),
            transition_id: stringValue(orphanedDispatch.transition_id),
            recovery:
              `/akk close ${bridge.terminalConversationId(session)} ` +
              (orphanedDispatch.kind === "lifecycle"
                ? `--expected-transition-id ${String(
                    orphanedDispatch.transition_id
                  )}`
                : `--expected-message-id ${String(
                    orphanedDispatch.message_id
                  )}`)
          }
        }
      : {}),
    commands: {
      send: !terminalHasBlockingTurn,
      approve: terminalControl.capabilities.includes("terminal_approval") &&
        terminalState.approval_state.approvable === true,
      status: true,
      cancel: terminalControl.capabilities.includes("terminal_cancel"),
      close: orphanedDispatch !== undefined,
      new_thread:
        lifecycleCapability.status === "supported" &&
        lifecycleCapability.newThread === true &&
        codexLifecycleIncarnationAvailable &&
        !terminalHasBlockingTurn,
      list_resumable_threads:
        lifecycleCapability.status === "supported" &&
        lifecycleCapability.resumeExact === true &&
        codexLifecycleIncarnationAvailable,
      native_inspect:
        nativeInspectionCapability.status === "supported" &&
        nativeInspectionCapability.statusInspection === true &&
        terminalState.activity_state === "idle" &&
        automatedInputComposerReady &&
        terminalControl.capabilities.includes("send_keys") &&
        terminalControl.capabilities.includes("screen_status") &&
        (
          session.agent === "codex"
            ? codexLifecycleIncarnationAvailable
            : Boolean(
                nativeAgentIdentity?.sessionId &&
                nativeAgentIdentity.processUuid
              )
        ) &&
        orphanedDispatch === undefined &&
        !terminalHasBlockingTurn
    }
  };
  const availableActions = availableListActions(entry);
  const { commands: _commands, ...publicEntry } = entry;
  return {
    ...publicEntry,
    available_actions: availableActions
  };
}

function terminalFirstListProjection({
  storeDir,
  terminals,
  managedSessions,
  sessionAuthorityRequired,
  allConversations,
  displayedConversations,
  includeAll,
  managedOnly,
  statusFilter,
  mutationsAllowed
}: {
  storeDir: string;
  terminals: Record<string, any>[];
  managedSessions: ManagedSessionState[];
  sessionAuthorityRequired: boolean;
  allConversations: Conversation[];
  displayedConversations: Conversation[];
  includeAll: boolean;
  managedOnly: boolean;
  statusFilter?: string;
  mutationsAllowed: boolean;
}): {
  terminals: Record<string, any>[];
  unavailableManagedTurns: Record<string, any>[];
} {
  const nonterminalDeferredTransfers = listDeferredForegroundTransfers(
    storeDir
  ).filter((transfer) =>
    !["resolved", "abort_resolved"].includes(transfer.status)
  );
  const nonterminalDeferredTransferIds = new Set(
    nonterminalDeferredTransfers.map((transfer) => transfer.transfer_id)
  );
  const nonterminalDeferredSourceTurnIds = new Set(
    nonterminalDeferredTransfers.flatMap((transfer) =>
      transfer.version === 2 &&
        transfer.source_kind === "candidate_rollout_quiescent"
        ? (transfer.source_turn_history ?? []).map((turn) => turn.turn_id)
        : []
    )
  );
  const conversationHasNonterminalDeferredTransfer = (
    conversation: Conversation
  ): boolean => {
    if (
      nonterminalDeferredSourceTurnIds.has(
        turnIdForConversation(conversation)
      )
    ) {
      return true;
    }
    const takeover = isRecord(conversation.native_session_takeover)
      ? conversation.native_session_takeover
      : undefined;
    const transferId = stringValue(takeover?.deferred_foreground_transfer_id);
    return Boolean(
      transferId && nonterminalDeferredTransferIds.has(transferId)
    );
  };
  const discoveredTerminalControls = terminals.flatMap((terminal) => {
    const control = isRecord(terminal.terminal_control)
      ? terminal.terminal_control as unknown as TerminalControlRef
      : undefined;
    return control ? [control] : [];
  });

  const projectedTerminals = terminals.map((terminal) => {
    const {
      _automated_input_composer_ready: automatedInputComposerReady,
      _codex_open_root_rollout_inventory: codexOpenRootRolloutInventoryValue,
      _codex_latent_clear_resume: codexLatentClearResumeValue,
      ...publicTerminal
    } = terminal;
    const codexOpenRootRolloutInventory = isRecord(
      codexOpenRootRolloutInventoryValue
    )
      ? codexOpenRootRolloutInventoryValue as unknown as
          CodexOpenRootRolloutInventory
      : undefined;
    const terminalControl = isRecord(terminal.terminal_control)
      ? terminal.terminal_control as unknown as TerminalControlRef
      : undefined;
    const terminalHasNonterminalDeferredTransfer = Boolean(
      terminalControl && nonterminalDeferredTransfers.some((transfer) =>
        transfer.terminal_id === String(terminal.id) &&
        transfer.process_pid === Number(terminal.pid) &&
        terminalControlEvidenceMatches(
          transfer.terminal_endpoint,
          terminalControl
        )
      )
    );
    const allRelated = terminalControl
      ? allConversations.filter((conversation) =>
          terminalControlsShareIncarnation(
            terminalControlForManagedConversation(conversation),
            terminalControl
          )
        )
      : [];
    const displayedRelated = terminalControl
      ? displayedConversations.filter((conversation) =>
          terminalControlsShareIncarnation(
            terminalControlForManagedConversation(conversation),
            terminalControl
          )
        )
      : [];
    const relatedSessions = terminalControl
      ? managedSessions.filter((session) =>
          terminalControlsShareIncarnation(
            session.binding?.terminal_control,
            terminalControl
          )
        )
      : [];
    const matchingSessions = relatedSessions.filter((session) =>
      managedSessionMatchesLiveTerminalEntry(session, terminal, storeDir)
    );
    const conflictingBoundSessionClaims = relatedSessions.flatMap(
      (session): Array<{
        session: ManagedSessionState;
        kind: Exclude<
          ManagedBindingConflictKind,
          "stale_process_incarnation"
        >;
      }> => {
        const kind = managedBindingConflictKindForLiveTerminalEntry({
          storeDir,
          session,
          terminal
        });
        return kind && kind !== "stale_process_incarnation"
          ? [{ session, kind }]
          : [];
      }
    );
    const unresolvedSessionClaims = relatedSessions.filter((session) =>
      ["transitioning", "quarantined"].includes(session.status) &&
      managedSessionClaimsLiveTerminalEntry(session, terminal)
    );
    const sessionAuthorityConflict = unresolvedSessionClaims.length > 0
      ? {
          reason:
            "a first-class managed Session has an unresolved lifecycle binding on this terminal",
          session_ids: unresolvedSessionClaims.map((session) =>
            session.session_id
          ),
          binding_statuses: unresolvedSessionClaims.map((session) =>
            session.status
          ),
          transition_ids: unresolvedSessionClaims.map((session) =>
            session.last_transition_id ?? null
          ),
          recovery:
            "use only the lifecycle recovery action listed for this terminal"
        }
      : conflictingBoundSessionClaims.length === 1
      ? {
          kind: conflictingBoundSessionClaims[0].kind,
          reason:
            conflictingBoundSessionClaims[0].kind === "provisional_orphan"
              ? "a failed raw attach left a bound Session without an authoritative native-thread identity"
              : conflictingBoundSessionClaims[0].kind ===
                    "live_external_thread_change"
                ? "the live coding-agent thread changed outside AKK while its previous Session binding remained bound"
                : "the live terminal no longer matches a bound managed Session and the process relationship is unverifiable",
          session_ids: [
            conflictingBoundSessionClaims[0].session.session_id
          ],
          binding_ids: [
            conflictingBoundSessionClaims[0].session.binding?.binding_id ?? null
          ],
          session_revisions: [
            conflictingBoundSessionClaims[0].session.revision ?? null
          ],
          recovery:
            conflictingBoundSessionClaims[0].kind === "unverifiable"
              ? "inspect the terminal and Session identity; AKK cannot safely reconcile an unverifiable binding"
              : "use only the exact reconcile_binding action listed for this terminal"
        }
      : conflictingBoundSessionClaims.length > 1
      ? {
          kind: "ambiguous_bound_claims",
          reason:
            "multiple non-exact bound managed Sessions claim the same live terminal",
          session_ids: conflictingBoundSessionClaims.map(({ session }) =>
            session.session_id
          ),
          recovery:
            "inspect Session state; AKK will not reconcile ambiguous claims"
        }
      : matchingSessions.length > 1
      ? {
          reason:
            "multiple first-class managed Sessions claim the same live terminal binding",
          session_ids: matchingSessions.map((session) => session.session_id),
          recovery: "inspect Session state before performing a side effect"
        }
      : undefined;
    const authoritativeSession = matchingSessions[0];
    const discoveredOwnership = terminalControl
      ? terminalDispatchOwnership(terminalControl)
      : { state: "none" as const };
    let ownership = discoveredOwnership.state === "current"
      ? localTerminalDispatchOwnership(
          discoveredOwnership.conversation,
          allRelated,
          terminal
        )
      : discoveredOwnership;
    if (sessionAuthorityConflict) {
      ownership = {
        state: "conflict" as const,
        conflict: sessionAuthorityConflict
      };
    } else if (
      ownership.state === "current" &&
      authoritativeSession &&
      sessionIdForConversation(ownership.conversation) !==
        authoritativeSession.session_id
    ) {
      ownership = {
        state: "conflict" as const,
        conflict: {
          reason:
            "the current dispatch Turn and first-class Session binding disagree",
          owner_session_id: sessionIdForConversation(
            discoveredOwnership.state === "current"
              ? discoveredOwnership.conversation
              : ownership.conversation
          ),
          bound_session_id: authoritativeSession.session_id,
          recovery: "inspect Session and Turn state before performing a side effect"
        }
      };
    }
    const discoveredRawActions = isRecord(terminal.available_actions)
      ? terminal.available_actions
      : {};
    const rawActions = mutationsAllowed
      ? discoveredRawActions
      : readOnlyListActions(discoveredRawActions);
    const bindingAwareRawActions = authoritativeSession
      ? actionsForManagedSessionBinding(
          rawActions,
          authoritativeSession
        )
      : rawActions;
    const sessionAwareRawActionsBase =
      authoritativeSession &&
        managedSessionHasUnresolvedNativeTransition(
          storeDir,
          authoritativeSession
        )
        ? Object.fromEntries(
            Object.entries(bindingAwareRawActions).filter(
              ([actionName]) => actionName !== "native_inspect"
            )
          )
        : bindingAwareRawActions;
    const sessionAwareRawActions = terminalHasNonterminalDeferredTransfer
      ? readOnlyListActions(sessionAwareRawActionsBase)
      : sessionAwareRawActionsBase;
    const soleBindingConflict = conflictingBoundSessionClaims.length === 1
      ? conflictingBoundSessionClaims[0]
      : undefined;
    const externalHandoffDetected = conflictingBoundSessionClaims.some(
      ({ kind }) => kind === "live_external_thread_change"
    );
    const conflictingSessionRevision = Number(
      soleBindingConflict?.session.revision
    );
    const conflictingSessionTurns = soleBindingConflict
      ? managedTurnsForSession(
          storeDir,
          soleBindingConflict.session.session_id
        )
      : [];
    const expectedTerminalToken = stringValue(
      terminal.lifecycle_binding_token
    );
    const externalHandoffNativeThreadId = stringValue(
      terminal.native_agent_status_card_session_id
    ) ?? stringValue(terminal.native_agent_session_id);
    const resolvedNativeThreadId = stringValue(
      terminal.native_agent_session_id
    );
    const externalHandoffTerminalToken =
      terminalControl &&
      externalHandoffNativeThreadId &&
      isExactNativeThreadId(externalHandoffNativeThreadId)
        ? unmanagedTerminalBindingToken({
            terminalId: stringValue(terminal.id) as string,
            terminalControl,
            agent: terminal.agent,
            pid: Number(terminal.pid),
            workspace: terminal.workspace ?? terminal.cwd ?? cliCwd(),
            nativeThreadId: externalHandoffNativeThreadId,
            processUuid: stringValue(terminal.native_agent_process_uuid),
            processBirth: stringValue(terminal.native_agent_process_birth),
            rollout:
              resolvedNativeThreadId === externalHandoffNativeThreadId &&
              isRecord(terminal.native_agent_rollout)
                ? terminal.native_agent_rollout as any
                : undefined
          })
        : undefined;
    const externalHandoffTarget =
      soleBindingConflict?.kind === "live_external_thread_change" &&
      externalHandoffNativeThreadId &&
      isExactNativeThreadId(externalHandoffNativeThreadId)
        ? observedHandoffTargetResolution({
            storeDir,
            agent: terminal.agent,
            workspace: terminal.workspace ?? terminal.cwd ?? cliCwd(),
            nativeThreadId: externalHandoffNativeThreadId.toLowerCase(),
            sourceSessionId: soleBindingConflict.session.session_id
          })
        : undefined;
    const externalHandoffSnapshotToken =
      externalHandoffTerminalToken &&
      soleBindingConflict?.kind === "live_external_thread_change" &&
      externalHandoffTarget?.status === "eligible"
        ? humanObservedHandoffBindingToken({
            terminal_token: externalHandoffTerminalToken,
            source_session_id: soleBindingConflict.session.session_id,
            source_revision: managedSessionRevision(
              soleBindingConflict.session
            ),
            source_binding_token: managedSessionBindingToken(
              soleBindingConflict.session
            ),
            target: externalHandoffTarget.snapshot
          })
        : undefined;
    const blockingHandoffTurns = conflictingSessionTurns.filter((turn) =>
      SESSION_SEND_BLOCKING_STATUSES.has(turn.status)
    );
    const terminalBlockingTurns = terminalControl
      ? terminalIncarnationBlockingTurns(
          storeDir,
          terminalControl,
          allRelated
        )
      : [];
    const externalHandoffSourceSessionIds = new Set(
      conflictingBoundSessionClaims
        .filter(({ kind }) => kind === "live_external_thread_change")
        .map(({ session }) => session.session_id)
    );
    const handoffSourceBlockingTurns = terminalBlockingTurns.filter((turn) =>
      externalHandoffSourceSessionIds.has(sessionIdForConversation(turn))
    );
    const nativeIdentityObservation = isRecord(
      terminal.native_agent_identity_observation
    )
      ? terminal.native_agent_identity_observation
      : undefined;
    const verifiedEmptyProcessUuid = stringValue(
      terminal.native_agent_process_uuid
    );
    const verifiedEmptyProcessBirth = stringValue(
      terminal.native_agent_process_birth
    );
    const verifiedEmptyWorkspace = stringValue(
      terminal.workspace ?? terminal.cwd
    );
    const verifiedEmptySourceNativeThreadId = stringValue(
      soleBindingConflict?.session.binding?.native_thread_id
    )?.toLowerCase();
    const verifiedEmptySourceActiveElsewhere = Boolean(
      verifiedEmptySourceNativeThreadId &&
      terminals.some((candidate) =>
        candidate !== terminal &&
        candidate.agent === "codex" &&
        stringValue(candidate.native_agent_session_id)?.toLowerCase() ===
          verifiedEmptySourceNativeThreadId
      )
    );
    const verifiedEmptyRawSendAction = isRecord(rawActions.send)
      ? rawActions.send
      : {
          tool: "agent_knock_knock_send",
          arguments: { selector: stringValue(terminal.id) },
          missing_required: ["request"]
        };
    const verifiedEmptyCodexHandoffEligible = Boolean(
      mutationsAllowed &&
      terminal.agent === "codex" &&
      terminalControl &&
      discoveredOwnership.state === "none" &&
      unresolvedSessionClaims.length === 0 &&
      matchingSessions.length === 0 &&
      soleBindingConflict?.kind === "unverifiable" &&
      nativeIdentityObservation?.status === "verified_absent" &&
      verifiedEmptyProcessUuid &&
      verifiedEmptyProcessBirth &&
      verifiedEmptyWorkspace &&
      exactBoundCodexSourceForVerifiedEmptyHandoff({
        session: soleBindingConflict.session,
        terminalId: String(terminal.id),
        terminalControl,
        pid: Number(terminal.pid),
        workspace: verifiedEmptyWorkspace,
        processUuid: verifiedEmptyProcessUuid,
        processBirth: verifiedEmptyProcessBirth
      }) &&
      ["idle", "unknown"].includes(String(terminal.activity_state)) &&
      automatedInputComposerReady === true &&
      !(isRecord(terminal.approval_state) &&
        terminal.approval_state.blocked === true) &&
      blockingHandoffTurns.length === 0 &&
      terminalBlockingTurns.length === 0 &&
      !managedSessionHasUnresolvedNativeTransition(
        storeDir,
        soleBindingConflict.session
      ) &&
      !verifiedEmptySourceActiveElsewhere &&
      terminal.orphaned_terminal_dispatch === undefined &&
      terminalControl?.capabilities.includes("send_keys") &&
      terminalControl.capabilities.includes("screen_status")
    );
    const verifiedEmptyCodexSnapshotToken =
      verifiedEmptyCodexHandoffEligible &&
      terminalControl &&
      soleBindingConflict &&
      verifiedEmptyProcessUuid &&
      verifiedEmptyProcessBirth &&
      verifiedEmptyWorkspace
        ? verifiedEmptyCodexHandoffToken({
            terminalId: String(terminal.id),
            terminalControl,
            pid: Number(terminal.pid),
            workspace: verifiedEmptyWorkspace,
            processUuid: verifiedEmptyProcessUuid,
            processBirth: verifiedEmptyProcessBirth,
            sourceSession: soleBindingConflict.session
          })
        : undefined;
    const deferredCodexCandidateInventory =
      codexOpenRootRolloutInventory &&
        codexOpenRootRolloutInventory.roots.length > 0
        ? codexOpenRootRolloutInventory
        : undefined;
    const abandonedConflictSource =
      !authoritativeSession &&
      soleBindingConflict?.kind === "unverifiable" &&
      matchingSessions.length === 0 &&
      conflictingBoundSessionClaims.length === 1 &&
      unresolvedSessionClaims.length === 0 &&
      terminal.agent === "codex"
        ? soleBindingConflict.session
        : undefined;
    const deferredCodexSource = (authoritativeSession ??
        abandonedConflictSource) &&
        terminal.agent === "codex" &&
        (
          nativeIdentityObservation?.status === "verified_absent" ||
          deferredCodexCandidateInventory !== undefined
        )
      ? authoritativeSession ?? abandonedConflictSource
      : undefined;
    const deferredCodexProcessUuid = stringValue(
      terminal.native_agent_process_uuid
    );
    const deferredCodexProcessBirth = stringValue(
      terminal.native_agent_process_birth
    );
    const deferredCodexWorkspace = stringValue(
      terminal.workspace ?? terminal.cwd
    );
    const deferredCodexSourceNativeThreadId = stringValue(
      deferredCodexSource?.binding?.native_thread_id
    )?.toLowerCase();
    const deferredCodexLatentClearResumeFingerprint =
      isRecord(codexLatentClearResumeValue) &&
      stringValue(
        codexLatentClearResumeValue.source_native_thread_id
      )?.toLowerCase() === deferredCodexSourceNativeThreadId
        ? stringValue(codexLatentClearResumeValue.fingerprint)
        : undefined;
    const deferredCodexSourceActiveElsewhere = Boolean(
      deferredCodexSourceNativeThreadId &&
      terminals.some((candidate) =>
        candidate !== terminal &&
        candidate.agent === "codex" &&
        stringValue(candidate.native_agent_session_id)?.toLowerCase() ===
          deferredCodexSourceNativeThreadId
      )
    );
    const deferredCodexDispatchSnapshot = terminalControl
      ? tryDeferredCodexForegroundDispatchSnapshot(terminalControl)
      : undefined;
    const deferredCodexCandidateSourceTurnHistory =
      deferredCodexCandidateInventory &&
        deferredCodexSource?.binding?.native_process.rollout
        ? deferredCandidateSourceTurnHistory(
            storeDir,
            deferredCodexSource
          )
        : undefined;
    const deferredCodexSourceRolloutPresent = Boolean(
      deferredCodexCandidateInventory &&
      deferredCodexSource?.binding?.native_process.rollout &&
      deferredCodexCandidateInventory.roots.some((root) =>
        root.sessionId.toLowerCase() ===
          deferredCodexSource.binding?.native_thread_id?.toLowerCase() &&
        exactNativeRolloutMatches(
          root.rollout,
          deferredCodexSource.binding!.native_process.rollout!
        )
      )
    );
    const deferredCodexSourceRolloutAuthority:
      DeferredForegroundTransferSourceRolloutAuthority =
        abandonedConflictSource && !deferredCodexSourceRolloutPresent
          ? "explicitly_abandoned_predecessor"
          : "present";
    const deferredCodexSourceAbandonmentFingerprint =
      deferredCodexSourceRolloutAuthority ===
          "explicitly_abandoned_predecessor" &&
        deferredCodexSource &&
        deferredCodexCandidateSourceTurnHistory &&
        deferredCodexDispatchSnapshot
        ? explicitlyAbandonedCandidateSourceFingerprint({
            storeDir,
            session: deferredCodexSource,
            sourceTurnHistory: deferredCodexCandidateSourceTurnHistory,
            dispatchSnapshot: deferredCodexDispatchSnapshot
          })
        : undefined;
    const deferredCodexStatusCardSourceEligible = Boolean(
      deferredCodexSource &&
      terminalControl &&
      deferredCodexProcessUuid &&
      deferredCodexProcessBirth &&
      deferredCodexWorkspace &&
      exactBoundCodexStatusCardSourceForDeferredSend({
        session: deferredCodexSource,
        terminalId: String(terminal.id),
        terminalControl,
        pid: Number(terminal.pid),
        workspace: deferredCodexWorkspace,
        processUuid: deferredCodexProcessUuid,
        processBirth: deferredCodexProcessBirth
      }) &&
      managedTurnsForSession(
        storeDir,
        deferredCodexSource.session_id
      ).length === 0 &&
      !deferredCodexSource.last_transition_id &&
      !managedSessionHasAnyNativeTransition(storeDir, deferredCodexSource)
    );
    const deferredCodexCandidateSourceEligible = Boolean(
      deferredCodexSource &&
      terminalControl &&
      deferredCodexProcessUuid &&
      deferredCodexProcessBirth &&
      deferredCodexWorkspace &&
      deferredCodexCandidateInventory &&
      deferredCodexCandidateSourceTurnHistory &&
      exactBoundCodexCandidateSourceForDeferredSend({
        session: deferredCodexSource,
        terminalId: String(terminal.id),
        terminalControl,
        pid: Number(terminal.pid),
        workspace: deferredCodexWorkspace,
        processUuid: deferredCodexProcessUuid,
        processBirth: deferredCodexProcessBirth,
        inventory: deferredCodexCandidateInventory,
        sourceRolloutAuthority: deferredCodexSourceRolloutAuthority
      }) &&
      (deferredCodexSourceRolloutAuthority === "present" ||
        Boolean(deferredCodexSourceAbandonmentFingerprint)) &&
      codexCandidateInventoryHasNoOtherManagedClaim({
        storeDir,
        inventory: deferredCodexCandidateInventory,
        sourceSessionId: deferredCodexSource.session_id,
        includeDetached:
          deferredCodexSourceRolloutAuthority ===
            "explicitly_abandoned_predecessor"
      }) &&
      candidateSourceTransitionHistoryIsTerminal(
        storeDir,
        deferredCodexSource
      )
    );
    const deferredCodexCandidateRouteNeeded = Boolean(
      deferredCodexCandidateInventory &&
      (
        deferredCodexCandidateInventory.status === "unbound" ||
        nativeIdentityObservation?.status === "unavailable" ||
        deferredCodexSource?.binding?.native_process.rollout === undefined ||
        deferredCodexLatentClearResumeFingerprint !== undefined
      )
    );
    const deferredCodexForegroundEligible = Boolean(
      mutationsAllowed &&
      !terminalHasNonterminalDeferredTransfer &&
      deferredCodexSource &&
      terminalControl &&
      hasCanonicalTerminalEndpoint(terminalControl) &&
      discoveredOwnership.state === "none" &&
      unresolvedSessionClaims.length === 0 &&
      (
        (matchingSessions.length === 1 &&
          conflictingBoundSessionClaims.length === 0) ||
        (deferredCodexSourceRolloutAuthority ===
            "explicitly_abandoned_predecessor" &&
          matchingSessions.length === 0 &&
          conflictingBoundSessionClaims.length === 1)
      ) &&
      deferredCodexProcessUuid &&
      deferredCodexProcessBirth &&
      deferredCodexWorkspace &&
      (
        deferredCodexStatusCardSourceEligible ||
        (
          deferredCodexCandidateRouteNeeded &&
          deferredCodexCandidateSourceEligible
        )
      ) &&
      terminalBlockingTurns.length === 0 &&
      terminal.orphaned_terminal_dispatch === undefined &&
      deferredCodexDispatchSnapshot &&
      ["idle", "unknown"].includes(String(terminal.activity_state)) &&
      automatedInputComposerReady === true &&
      !(isRecord(terminal.approval_state) &&
        terminal.approval_state.blocked === true) &&
      !deferredCodexSourceActiveElsewhere &&
      terminalControl.capabilities.includes("send_keys") &&
      terminalControl.capabilities.includes("screen_status")
    );
    const deferredCodexForegroundToken =
      deferredCodexForegroundEligible &&
      deferredCodexSource &&
      terminalControl &&
      deferredCodexProcessUuid &&
      deferredCodexProcessBirth &&
      deferredCodexWorkspace &&
      deferredCodexDispatchSnapshot
        ? deferredCodexForegroundBindingToken({
            terminalId: String(terminal.id),
            terminalControl,
            pid: Number(terminal.pid),
            workspace: deferredCodexWorkspace,
            processUuid: deferredCodexProcessUuid,
            processBirth: deferredCodexProcessBirth,
            sourceSession: deferredCodexSource,
            dispatchSnapshot: deferredCodexDispatchSnapshot,
            sourceTurnHistory: deferredCodexCandidateSourceTurnHistory,
            candidateContextFingerprint:
              deferredCodexLatentClearResumeFingerprint,
            sourceRolloutAuthority:
              deferredCodexSourceRolloutAuthority,
            sourceAbandonmentFingerprint:
              deferredCodexSourceAbandonmentFingerprint,
            ...(deferredCodexCandidateInventory
              ? { candidateInventory: deferredCodexCandidateInventory }
              : {})
          })
        : undefined;
    const reconcileBindingAction =
      mutationsAllowed &&
      discoveredOwnership.state === "none" &&
      unresolvedSessionClaims.length === 0 &&
      matchingSessions.length === 0 &&
      soleBindingConflict &&
      soleBindingConflict.kind !== "unverifiable" &&
      Number.isSafeInteger(conflictingSessionRevision) &&
      conflictingSessionRevision > 0 &&
      expectedTerminalToken &&
      terminal.activity_state === "idle" &&
      !(isRecord(terminal.approval_state) &&
        terminal.approval_state.blocked === true) &&
      !conflictingSessionTurns.some((turn) =>
        SESSION_SEND_BLOCKING_STATUSES.has(turn.status)
      ) &&
      terminalBlockingTurns.length === 0 &&
      !managedSessionHasUnresolvedNativeTransition(
        storeDir,
        soleBindingConflict.session
      )
        ? {
            tool: "agent_knock_knock_reconcile_binding",
            arguments: {
              terminal_id: stringValue(terminal.id),
              conflicting_session_id:
                soleBindingConflict.session.session_id,
              expected_session_revision: conflictingSessionRevision,
              expected_binding_token: managedSessionBindingToken(
                soleBindingConflict.session
              ),
              expected_terminal_token: expectedTerminalToken
            },
            requires_user_intent: true
          }
        : undefined;
    const externalHandoffAdoptable = Boolean(
      mutationsAllowed &&
      discoveredOwnership.state === "none" &&
      unresolvedSessionClaims.length === 0 &&
      soleBindingConflict?.kind === "live_external_thread_change" &&
      terminal.activity_state === "idle" &&
      automatedInputComposerReady === true &&
      !(isRecord(terminal.approval_state) &&
        terminal.approval_state.blocked === true) &&
      !conflictingSessionTurns.some((turn) =>
        SESSION_SEND_BLOCKING_STATUSES.has(turn.status)
      ) &&
      terminalBlockingTurns.length === 0 &&
      !managedSessionHasUnresolvedNativeTransition(
        storeDir,
        soleBindingConflict.session
      ) &&
      externalHandoffTarget?.status === "eligible" &&
      isRecord(rawActions.send) &&
      Boolean(externalHandoffSnapshotToken)
    );
    const handoffDecisionTurn =
      mutationsAllowed &&
      soleBindingConflict?.kind === "live_external_thread_change" &&
      externalHandoffTarget?.status === "eligible" &&
      terminal.activity_state === "idle" &&
      !(isRecord(terminal.approval_state) &&
        terminal.approval_state.blocked === true) &&
      !managedSessionHasUnresolvedNativeTransition(
        storeDir,
        soleBindingConflict.session
      ) &&
      blockingHandoffTurns.length === 1 &&
      terminalBlockingTurns.every((turn) =>
        turn.conversation_id === blockingHandoffTurns[0].conversation_id
      )
        ? blockingHandoffTurns[0]
        : undefined;
    const handoffDecisionToken =
      handoffDecisionTurn &&
      externalHandoffSnapshotToken &&
      terminalControl
        ? activeTurnHandoffDecisionToken({
            handoffToken: externalHandoffSnapshotToken,
            turn: handoffDecisionTurn,
            ledger: loadTerminalBridgeDispatchLedger(terminalControl)
          })
        : undefined;
    const handoffDecision =
      handoffDecisionTurn &&
      handoffDecisionToken &&
      externalHandoffNativeThreadId
      ? {
          kind: "active_turn_requires_decision",
          source_session_id: soleBindingConflict?.session.session_id,
          source_turn_id: turnIdForConversation(handoffDecisionTurn),
          live_native_thread_id: externalHandoffNativeThreadId,
          choices: {
            take_over_current: {
              action: {
                tool: "agent_knock_knock_close",
                arguments: {
                  turn_id: turnIdForConversation(handoffDecisionTurn),
                  reason: "superseded_by_human_context_switch",
                  expected_handoff_token: handoffDecisionToken
                },
                requires_explicit_user_confirmation: true
              },
              after: "refresh list and use its follow-current send"
            },
            keep_source: {
              effect: "no Store or terminal mutation",
              after:
                "restore source native thread in the Codex/Claude TUI, then refresh list"
            }
          }
        }
      : undefined;
    const blockingHandoffTurnIds = new Set(
      handoffSourceBlockingTurns.map((turn) => turn.conversation_id)
    );
    // An active source Turn may be superseded only through the snapshot-bound
    // handoff decision above. Never expose the generic Store-only close action
    // for that Turn, because doing so would bypass expected_handoff_token after
    // the live native thread or Turn generation changed. `blocking_turns` is
    // reserved for other same-incarnation blockers such as legacy collateral
    // stalls; clear those first, refresh, and only then decide the handoff.
    const terminalRecoveryBlockingTurns = terminalBlockingTurns.filter(
      (turn) =>
        !blockingHandoffTurnIds.has(turn.conversation_id) &&
        !conversationHasNonterminalDeferredTransfer(turn)
    );
    let terminalScopedCodexApprovalAction: Record<string, any> | undefined;
    const terminalScopedCodexApprovalPrompt =
      terminalScopedCodexApprovalPromptSnapshot(terminal.approval_state);
    if (
      mutationsAllowed &&
      terminal.agent === "codex" &&
      terminalControl &&
      hasCanonicalTerminalEndpoint(terminalControl) &&
      authoritativeSession &&
      !sessionAuthorityConflict &&
      !terminalHasNonterminalDeferredTransfer &&
      unresolvedSessionClaims.length === 0 &&
      conflictingBoundSessionClaims.length === 0 &&
      terminalScopedCodexApprovalPrompt &&
      isRecord(rawActions.approve)
    ) {
      try {
        const ledger = loadTerminalBridgeDispatchLedger(terminalControl);
        const boundary =
          ownership.state === "conflict" &&
            discoveredOwnership.state === "current" &&
            ledger
            ? terminalScopedCodexApprovalBoundaryFromSnapshot({
                storeDir,
                terminal,
                owner: discoveredOwnership.conversation,
                session: authoritativeSession,
                ledger,
                approval: terminalScopedCodexApprovalPrompt
              })
            : ownership.state === "none" &&
                discoveredOwnership.state === "none"
              ? terminalScopedCodexApprovalWithoutDispatchOwnerBoundary({
                  storeDir,
                  terminal,
                  session: authoritativeSession,
                  ledger,
                  approval: terminalScopedCodexApprovalPrompt
                })
              : undefined;
        if (!boundary) {
          throw new Error(
            "terminal-scoped Codex approval has no eligible managed authority"
          );
        }
        terminalScopedCodexApprovalAction = {
          ...rawActions.approve,
          arguments: {
            conversation_id: String(terminal.id),
            expected_terminal_token: boundary.token
          },
          scope: "terminal_current_prompt",
          authority: boundary.authority.kind,
          managed_state_unchanged: true,
          automatic_approval_eligible: false,
          durable_dispatch_receipt: false,
          uncertain_outcome_recovery:
            "refresh status and inspect the live prompt; do not retry blindly"
        };
      } catch (error) {
        runtimeLog("info", "terminal_scoped_codex_approval_not_advertised", {
          terminal_id: String(terminal.id),
          terminal_target: terminalControl.target,
          reason: error instanceof Error ? error.message : String(error)
        });
      }
    }
    const terminalCanAcceptSend =
      ownership.state === "none" && isRecord(sessionAwareRawActions.send);
    if (
      ownership.state === "current" &&
      !allRelated.some((conversation) =>
        conversation.conversation_id === ownership.conversation.conversation_id
      )
    ) {
      allRelated.push(ownership.conversation);
    }

    const sessionIds = new Set(
      allRelated.map((conversation) => sessionIdForConversation(conversation))
    );
    const legacySessionId = [...displayedRelated]
          .sort(compareManagedConversationRecency)
          .map((conversation) => sessionIdForConversation(conversation))[0] ??
        [...allRelated]
          .sort(compareManagedConversationRecency)
          .map((conversation) => sessionIdForConversation(conversation))[0];
    const managedSessionId = authoritativeSession?.session_id ??
      (
        !sessionAuthorityRequired
          ? ownership.state === "current"
            ? sessionIdForConversation(ownership.conversation)
            : legacySessionId
          : undefined
      );
    // History remains useful when a pane has restarted and therefore no
    // first-class Session is authoritative for the new process incarnation.
    // Keep that display-only association separate from the send target: under
    // protocol 3, only authoritativeSession may populate managedSessionId.
    const historySessionId = managedSessionId ?? legacySessionId;
    const sessionAllRelated = historySessionId
      ? allRelated.filter((conversation) =>
          sessionIdForConversation(conversation) === historySessionId
        )
      : [];
    const sessionDisplayedRelated = historySessionId
      ? displayedRelated.filter((conversation) =>
          sessionIdForConversation(conversation) === historySessionId
        )
      : [];
    const sessionBindingMatchesLiveTerminal = authoritativeSession
      ? true
      : Boolean(
          !sessionAuthorityRequired &&
          sessionAllRelated.some((turn) =>
            managedTurnMatchesLiveTerminal(turn, terminal)
          )
        );

    const currentTurnValue = ownership.state === "current"
      ? currentManagedTurnForTerminal(
          ownership.conversation,
          terminal,
          sessionAwareRawActions
        )
      : undefined;
    const currentTurnProjection = currentTurnValue && (
      !mutationsAllowed ||
      (
        ownership.state === "current" &&
        conversationHasNonterminalDeferredTransfer(ownership.conversation)
      )
    )
      ? readOnlyManagedTurn(currentTurnValue)
      : currentTurnValue;
    const currentTurn = currentTurnProjection
      ? withoutGenericHandoffSourceClose(
          currentTurnProjection,
          blockingHandoffTurnIds
        )
      : undefined;
    const nonOwnerRawActions = authoritativeSession
      ? Object.fromEntries(
          Object.entries(sessionAwareRawActions).filter(
            ([actionName]) => actionName !== "approve"
          )
        )
      : sessionAwareRawActions;
    const sortedDisplayed = [...sessionDisplayedRelated]
      .filter((conversation) =>
        conversation.conversation_id !== currentTurn?.conversation_id
      )
      .sort(compareManagedConversationRecency);
    const recentConversation = currentTurn ? undefined : sortedDisplayed[0];
    const recentTurnValue = recentConversation
      ? historicalManagedTurnForTerminal(
          recentConversation,
          terminalCanAcceptSend,
          terminal
        )
      : undefined;
    const recentTurnProjection = recentTurnValue && (
      !mutationsAllowed ||
      Boolean(recentConversation &&
        conversationHasNonterminalDeferredTransfer(recentConversation))
    )
      ? readOnlyManagedTurn(recentTurnValue)
      : recentTurnValue;
    const recentTurn = recentTurnProjection
      ? withoutGenericHandoffSourceClose(
          recentTurnProjection,
          blockingHandoffTurnIds
        )
      : undefined;
    const historyConversations = includeAll
      ? sortedDisplayed.filter((conversation) =>
          conversation.conversation_id !== recentConversation?.conversation_id
        )
      : [];
    const history = historyConversations.map((conversation) => {
      const turn =
      historicalManagedTurnForTerminal(
        conversation,
        terminalCanAcceptSend,
        terminal
      );
      return withoutGenericHandoffSourceClose(
        mutationsAllowed &&
          !conversationHasNonterminalDeferredTransfer(conversation)
          ? turn
          : readOnlyManagedTurn(turn),
        blockingHandoffTurnIds
      );
    });
    const visibleTurnIds = new Set(
      [currentTurn, recentTurn, ...history]
        .map((turn) => stringValue(turn?.conversation_id))
        .filter((id): id is string => id !== undefined)
    );
    const management = {
      session_id: managedSessionId ?? null,
      session_short_ref: managedSessionId
        ? sessionShortRef(managedSessionId)
        : null,
      current_turn: currentTurn ?? null,
      recent_turn: recentTurn ?? null,
      turn_count: sessionAllRelated.length,
      hidden_turn_count: sessionAllRelated.filter((conversation) =>
        !visibleTurnIds.has(conversation.conversation_id)
      ).length,
      session_count: new Set([
        ...sessionIds,
        ...relatedSessions.map((session) => session.session_id)
      ]).size,
      ...(authoritativeSession
        ? {
            binding_status: authoritativeSession.status,
            binding_id: authoritativeSession.binding?.binding_id ?? null,
            binding_generation:
              authoritativeSession.binding?.generation ?? null,
            native_thread_id:
              authoritativeSession.binding?.native_thread_id ?? null,
            binding_token: managedSessionBindingToken(authoritativeSession)
          }
        : {}),
      ...(includeAll ? { history } : {})
    };
    const baseAvailableActions = ownership.state === "current"
      ? currentTerminalActions(currentTurn)
      : ownership.state === "conflict"
        ? {
            ...safeTerminalActionsDuringConflict(sessionAwareRawActions),
            ...(deferredCodexForegroundToken &&
                deferredCodexSourceRolloutAuthority ===
                  "explicitly_abandoned_predecessor"
              ? {
                  send: {
                    ...verifiedEmptyRawSendAction,
                    arguments: {
                      ...(isRecord(verifiedEmptyRawSendAction.arguments)
                        ? verifiedEmptyRawSendAction.arguments
                        : {}),
                      expected_terminal_token: deferredCodexForegroundToken
                    }
                  }
                }
              : {}),
            ...(externalHandoffAdoptable
              ? {
                  send: {
                    ...rawActions.send,
                    arguments: {
                      ...(isRecord(rawActions.send.arguments)
                        ? rawActions.send.arguments
                        : {}),
                      expected_terminal_token:
                        externalHandoffSnapshotToken
                    }
                  }
                }
              : {}),
            ...(verifiedEmptyCodexSnapshotToken
              ? {
                  send: {
                    ...verifiedEmptyRawSendAction,
                    arguments: {
                      ...(isRecord(verifiedEmptyRawSendAction.arguments)
                        ? verifiedEmptyRawSendAction.arguments
                        : {}),
                      expected_terminal_token:
                        verifiedEmptyCodexSnapshotToken
                    }
                  }
                }
              : {}),
            ...(reconcileBindingAction
              ? { reconcile_binding: reconcileBindingAction }
              : {})
          }
        : deferredCodexForegroundToken
          ? {
              ...nonOwnerRawActions,
              send: {
                ...verifiedEmptyRawSendAction,
                arguments: {
                  ...(isRecord(verifiedEmptyRawSendAction.arguments)
                    ? verifiedEmptyRawSendAction.arguments
                    : {}),
                  expected_terminal_token: deferredCodexForegroundToken
                }
              }
            }
        : managedSessionId &&
            sessionBindingMatchesLiveTerminal &&
            isRecord(sessionAwareRawActions.send)
          ? {
              ...nonOwnerRawActions,
              send: sendActionForManagedSession(
                sessionAwareRawActions.send,
                managedSessionId
              )
            }
          : nonOwnerRawActions;
    const availableActions = terminalScopedCodexApprovalAction
      ? {
          ...baseAvailableActions,
          approve: terminalScopedCodexApprovalAction
        }
      : baseAvailableActions;
    const authoritativeBinding = authoritativeSession?.binding;
    const authoritativeIdentity = authoritativeBinding?.native_thread_id
      ? {
          native_agent_session_id: authoritativeBinding.native_thread_id,
          native_agent_process_uuid:
            authoritativeBinding.native_process.process_uuid,
          native_agent_process_birth:
            authoritativeBinding.native_process.process_birth,
          // Assigning undefined after spreading the discovered terminal is
          // intentional: a Codex status-card binding must not accidentally
          // expose the resolver's lingering rollout as evidence for the new
          // logical thread.
          native_agent_rollout: authoritativeBinding.native_process.rollout,
          native_agent_identity_evidence:
            authoritativeBinding.native_process.evidence,
          lifecycle_binding_token:
            managedSessionBindingToken(authoritativeSession)
        }
      : {};
    const publicManagementConflict =
      ownership.state === "conflict" && verifiedEmptyCodexSnapshotToken
        ? {
            ...ownership.conflict,
            kind: "verified_empty_native_session",
            reason:
              "the previously bound Codex rollout is conclusively closed " +
              "while the same terminal process is at an exact empty prompt",
            recovery:
              "use only the exact snapshot-bound send action listed for this terminal"
          }
        : ownership.state === "conflict" &&
            deferredCodexForegroundToken &&
            deferredCodexSourceRolloutAuthority ===
              "explicitly_abandoned_predecessor"
          ? {
              ...ownership.conflict,
              kind: "explicitly_abandoned_predecessor_adoptable",
              reason:
                "the explicitly abandoned Codex predecessor rollout is no longer open and the current exact rollout inventory is unclaimed",
              recovery:
                "use only the exact snapshot-bound follow-current send action listed for this terminal"
            }
        : ownership.state === "conflict"
          ? ownership.conflict
          : undefined;
    return {
      ...publicTerminal,
      ...authoritativeIdentity,
      management_state: ownership.state === "conflict"
        ? "conflict"
        : ownership.state === "current" || Boolean(authoritativeSession)
          ? "managed"
          : "unmanaged",
      ...(ownership.state === "conflict"
        ? { management_conflict: publicManagementConflict }
        : {}),
      ...(externalHandoffDetected
        ? {
            handoff_state: externalHandoffAdoptable
              ? "external_handoff_adoptable"
              : "external_handoff_blocked",
            ...(terminalRecoveryBlockingTurns.length > 0
              ? {
                  handoff_blocked_reason:
                    "the terminal has unresolved managed Turn state; use only a listed blocking_turns recovery action"
                }
              : handoffDecision
              ? {
                  handoff_blocked_reason:
                    "the source Session has one active Turn; use only the snapshot-bound handoff_decision after explicit confirmation"
                }
              : handoffSourceBlockingTurns.length > 0
              ? {
                  handoff_blocked_reason:
                    "the conflicting source Session has unresolved Turn state but no snapshot-bound handoff decision is currently safe; inspect the conflict and refresh"
                }
              : automatedInputComposerReady !== true
              ? {
                  handoff_blocked_reason:
                    "the current terminal composer is not an exact empty idle frame"
                }
              : {})
          }
        : {}),
      ...(verifiedEmptyCodexSnapshotToken
        ? { handoff_state: "verified_empty_native_session_adoptable" }
        : {}),
      ...(handoffDecision ? { handoff_decision: handoffDecision } : {}),
      ...(terminalRecoveryBlockingTurns.length > 0
        ? {
            blocking_turns: terminalRecoveryBlockingTurns.map((turn) => ({
              session_id: sessionIdForConversation(turn),
              turn_id: turnIdForConversation(turn),
              status: turn.status,
              recovery_action: {
                tool: "agent_knock_knock_close",
                arguments: {
                  turn_id: turnIdForConversation(turn)
                },
                requires_explicit_user_confirmation: true
              }
            }))
          }
        : {}),
      managed: management,
      available_actions: availableActions
    };
  });

  const unavailableManagedTurns = displayedConversations
    .filter((conversation) => {
      const managedControl = terminalControlForManagedConversation(conversation);
      if (discoveredTerminalControls.some((control) =>
        terminalControlsShareIncarnation(managedControl, control)
      )) {
        return false;
      }
      return (
        includeAll ||
        managedOnly ||
        statusFilter !== undefined ||
        managedTurnNeedsAttention(conversation)
      );
    })
    .sort(compareManagedConversationRecency)
    .map((conversation) => {
      const managedTurn = managedTurnListEntry(
        summarizeConversation(conversation),
        {
          terminalBridge: terminalBridgeEnabled(conversation),
          approvalState: managedListApprovalState(conversation),
          conversation
        }
      );
      return {
        ...managedTurn,
        available_actions: mutationsAllowed &&
            !conversationHasNonterminalDeferredTransfer(conversation)
          ? safeUnavailableManagedTurnActions(
              isRecord(managedTurn.available_actions)
                ? managedTurn.available_actions
                : {}
            )
          : readOnlyListActions(
              isRecord(managedTurn.available_actions)
                ? managedTurn.available_actions
                : {}
            ),
        terminal_availability: {
          available: false,
          reason: managedOnly
            ? "terminal discovery was disabled by --managed-only"
            : "the referenced terminal pane is not currently available"
        }
      };
    });

  return {
    terminals: projectedTerminals,
    unavailableManagedTurns
  };
}

function managedSessionMatchesLiveTerminalEntry(
  session: ManagedSessionState,
  terminal: Record<string, any>,
  storeDir: string
): boolean {
  const binding = session.binding;
  const liveControl = isRecord(terminal.terminal_control)
    ? terminal.terminal_control as unknown as TerminalControlRef
    : undefined;
  if (
    session.status !== "bound" ||
    !binding ||
    session.agent !== terminal.agent ||
    binding.native_process.pid !== Number(terminal.pid) ||
    !terminalControlAliasMatches(
      binding.terminal_id,
      binding.terminal_control,
      terminal.id,
      liveControl
    ) ||
    !matchesConfiguredWorkspace(
      session.workspace,
      terminal.workspace ?? terminal.cwd
    )
  ) {
    return false;
  }
  const liveThreadId = stringValue(terminal.native_agent_session_id);
  const statusCardThreadId = stringValue(
    terminal.native_agent_status_card_session_id
  );
  if (
    isExactNativeThreadId(binding.native_thread_id) &&
    isExactNativeThreadId(statusCardThreadId) &&
    binding.native_thread_id.toLowerCase() !==
      statusCardThreadId.toLowerCase()
  ) {
    return false;
  }
  if (!liveThreadId) {
    const candidateInventory = isRecord(
      terminal._codex_open_root_rollout_inventory
    )
      ? terminal._codex_open_root_rollout_inventory as unknown as
          CodexOpenRootRolloutInventory
      : undefined;
    const boundRollout = binding.native_process.rollout;
    const candidateRoot = candidateInventory?.roots.find((root) =>
      root.sessionId.toLowerCase() ===
        binding.native_thread_id?.toLowerCase()
    );
    if (
      session.agent === "codex" &&
      binding.native_thread_id &&
      isCompleteNativeRollout(boundRollout) &&
      candidateRoot &&
      exactNativeRolloutMatches(candidateRoot.rollout, boundRollout) &&
      candidateInventory?.pid === binding.native_process.pid &&
      candidateInventory.processUuid ===
        binding.native_process.process_uuid &&
      candidateInventory.processBirth ===
        binding.native_process.process_birth
    ) {
      return true;
    }
    return Boolean(
      session.agent === "codex" &&
      binding.native_thread_id &&
      isCodexStatusCardEvidence(binding.native_process.evidence) &&
      binding.native_process.process_uuid &&
      binding.native_process.process_birth &&
      binding.native_process.process_uuid ===
        stringValue(terminal.native_agent_process_uuid) &&
      binding.native_process.process_birth ===
        stringValue(terminal.native_agent_process_birth)
    );
  }
  const liveRollout = isRecord(terminal.native_agent_rollout)
    ? terminal.native_agent_rollout
    : undefined;
  const exactIdentityMatch = Boolean(
    binding.native_thread_id === liveThreadId &&
    (
      !binding.native_process.process_uuid ||
      binding.native_process.process_uuid ===
        stringValue(terminal.native_agent_process_uuid)
    ) &&
    (
      !binding.native_process.process_birth ||
      binding.native_process.process_birth ===
        stringValue(terminal.native_agent_process_birth)
    ) &&
    (
      !binding.native_process.rollout ||
      (
        binding.native_process.rollout.fd === stringValue(liveRollout?.fd) &&
        binding.native_process.rollout.device ===
          stringValue(liveRollout?.device) &&
        binding.native_process.rollout.inode ===
          stringValue(liveRollout?.inode) &&
        binding.native_process.rollout.path === stringValue(liveRollout?.path)
      )
    )
  );
  if (exactIdentityMatch || session.agent !== "codex") {
    return exactIdentityMatch;
  }
  return codexLingeringBeforeIdentityMatchesSession({
    storeDir,
    session,
    identity: {
      sessionId: liveThreadId,
      processUuid: stringValue(terminal.native_agent_process_uuid),
      processBirth: stringValue(terminal.native_agent_process_birth),
      rollout: liveRollout && isCompleteNativeRollout(liveRollout)
        ? {
            fd: String(liveRollout.fd),
            device: String(liveRollout.device),
            inode: String(liveRollout.inode),
            path: String(liveRollout.path)
          }
        : undefined,
      evidence:
        stringValue(terminal.native_agent_identity_evidence) ??
        "terminal_scan"
    }
  });
}

function managedSessionClaimsLiveTerminalEntry(
  session: ManagedSessionState,
  terminal: Record<string, any>
): boolean {
  const binding = session.binding;
  const liveControl = isRecord(terminal.terminal_control)
    ? terminal.terminal_control as unknown as TerminalControlRef
    : undefined;
  return Boolean(
    binding &&
    session.agent === terminal.agent &&
    binding.native_process.pid === Number(terminal.pid) &&
    terminalControlsShareIncarnation(binding.terminal_control, liveControl)
  );
}

type ManagedBindingConflictKind =
  | "stale_process_incarnation"
  | "live_external_thread_change"
  | "provisional_orphan"
  | "unverifiable";

function listedTerminalProcessIncarnation(
  terminal: Record<string, any>
): { processUuid?: string; processBirth?: string } {
  const processUuid = stringValue(terminal.native_agent_process_uuid);
  const processBirth = stringValue(terminal.native_agent_process_birth);
  if (
    terminal.agent !== "codex" ||
    (processUuid && processBirth)
  ) {
    return { processUuid, processBirth };
  }
  const pid = Number(terminal.pid);
  if (!Number.isSafeInteger(pid) || pid <= 1) {
    return { processUuid, processBirth };
  }
  try {
    const incarnation = codexProcessIncarnationForPid(pid);
    return {
      processUuid: processUuid ?? incarnation.processUuid,
      processBirth: processBirth ?? incarnation.processBirth
    };
  } catch {
    return { processUuid, processBirth };
  }
}

function managedBindingConflictKindForLiveTerminalEntry({
  storeDir,
  session,
  terminal
}: {
  storeDir: string;
  session: ManagedSessionState;
  terminal: Record<string, any>;
}): ManagedBindingConflictKind | undefined {
  const binding = session.binding;
  if (
    session.status !== "bound" ||
    !binding ||
    !managedSessionClaimsLiveTerminalEntry(session, terminal) ||
    managedSessionMatchesLiveTerminalEntry(session, terminal, storeDir)
  ) {
    return undefined;
  }
  const livePid = Number(terminal.pid);
  const incarnation = listedTerminalProcessIncarnation(terminal);
  const relationship = processIncarnationRelationship({
    binding,
    livePid,
    liveProcessUuid: incarnation.processUuid,
    liveProcessBirth: incarnation.processBirth
  });
  if (relationship === "different") {
    return "stale_process_incarnation";
  }
  if (
    !terminalControlAliasMatches(
      binding.terminal_id,
      binding.terminal_control,
      terminal.id,
      isRecord(terminal.terminal_control)
        ? terminal.terminal_control
        : undefined
    ) ||
    !matchesConfiguredWorkspace(
      session.workspace,
      terminal.workspace ?? terminal.cwd
    )
  ) {
    return "unverifiable";
  }
  const statusCardThreadId = stringValue(
    terminal.native_agent_status_card_session_id
  );
  const liveNativeThreadId = stringValue(
    terminal.native_agent_session_id
  );
  if (
    isExactNativeThreadId(binding.native_thread_id) &&
    isExactNativeThreadId(statusCardThreadId) &&
    binding.native_thread_id.toLowerCase() !==
      statusCardThreadId.toLowerCase()
  ) {
    return relationship === "same" &&
        isExactNativeThreadId(liveNativeThreadId) &&
        (
          liveNativeThreadId.toLowerCase() ===
            statusCardThreadId.toLowerCase() ||
          liveNativeThreadId.toLowerCase() ===
            binding.native_thread_id.toLowerCase()
        )
      ? "live_external_thread_change"
      : "unverifiable";
  }
  if (
    session.lineage.created_by === "attach" &&
    !session.last_transition_id &&
    !binding.native_thread_id &&
    !binding.native_process.rollout &&
    managedTurnsForSession(storeDir, session.session_id).length === 0
  ) {
    return "provisional_orphan";
  }
  if (
    relationship === "same" &&
    isExactNativeThreadId(binding.native_thread_id) &&
    isExactNativeThreadId(liveNativeThreadId) &&
    binding.native_thread_id.toLowerCase() !==
      liveNativeThreadId.toLowerCase()
  ) {
    return "live_external_thread_change";
  }
  return "unverifiable";
}

function managedSessionHasUnresolvedNativeTransition(
  storeDir: string,
  session: ManagedSessionState
): boolean {
  const root = nativeThreadTransitionsDir(storeDir);
  if (!fs.existsSync(root)) {
    return false;
  }
  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(root, { withFileTypes: true });
  } catch {
    return true;
  }
  for (const entry of entries) {
    if (!entry.isDirectory()) {
      continue;
    }
    let transition: NativeThreadTransition;
    try {
      transition = loadNativeThreadTransition(storeDir, entry.name);
    } catch {
      return true;
    }
    if (
      transition.source_session_id !== session.session_id &&
      transition.target_session_id !== session.session_id
    ) {
      continue;
    }
    if (!["committed", "aborted"].includes(transition.status)) {
      return true;
    }
  }
  return false;
}

function managedSessionHasAnyNativeTransition(
  storeDir: string,
  session: ManagedSessionState
): boolean {
  const root = nativeThreadTransitionsDir(storeDir);
  if (!fs.existsSync(root)) {
    return false;
  }
  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(root, { withFileTypes: true });
  } catch {
    return true;
  }
  for (const entry of entries) {
    if (!entry.isDirectory()) {
      continue;
    }
    let transition: NativeThreadTransition;
    try {
      transition = loadNativeThreadTransition(storeDir, entry.name);
    } catch {
      return true;
    }
    if (
      transition.source_session_id === session.session_id ||
      transition.target_session_id === session.session_id
    ) {
      return true;
    }
  }
  return false;
}

function terminalControlForManagedConversation(
  conversation: Conversation
): TerminalControlRef | undefined {
  return terminalControlFromTakeover(
    isRecord(conversation.native_session_takeover)
      ? conversation.native_session_takeover
      : undefined
  );
}

function terminalIncarnationBlockingTurns(
  storeDir: string,
  terminalControl: TerminalControlRef,
  conversations: Conversation[] = listConversations(storeDir)
): Conversation[] {
  return conversations
    .filter(isDiscoverableTmuxConversation)
    .filter((turn) =>
      terminalControlsShareIncarnation(
        terminalControlForManagedConversation(turn),
        terminalControl
      ) &&
      SESSION_SEND_BLOCKING_STATUSES.has(turn.status)
    )
    .sort(compareManagedConversationRecency);
}

function assertTerminalIncarnationCanStartTurn(
  storeDir: string,
  terminalControl: TerminalControlRef
): void {
  const blocker = terminalIncarnationBlockingTurns(
    storeDir,
    terminalControl
  )[0];
  if (!blocker) {
    return;
  }
  throw new Error(
    `terminal ${terminalControl.target} still has unresolved Turn ` +
    `${turnIdForConversation(blocker)} (${blocker.status})`
  );
}

function compareManagedConversationRecency(
  left: Conversation,
  right: Conversation
): number {
  const leftTime = Date.parse(String(left.updated_at ?? left.created_at ?? ""));
  const rightTime = Date.parse(String(right.updated_at ?? right.created_at ?? ""));
  if (Number.isFinite(leftTime) && Number.isFinite(rightTime) && leftTime !== rightTime) {
    return rightTime - leftTime;
  }
  if (Number.isFinite(leftTime) !== Number.isFinite(rightTime)) {
    return Number.isFinite(leftTime) ? -1 : 1;
  }
  return left.conversation_id.localeCompare(right.conversation_id);
}

function managedTurnNeedsAttention(conversation: Conversation): boolean {
  if ([
    "created",
    "running",
    "waiting_for_agent",
    "waiting_for_openclaw",
    "stalled",
    "callback_pending",
    "callback_failed",
    "cancelling"
  ].includes(conversation.status)) {
    return true;
  }
  const delivery = isRecord(conversation.callback_delivery)
    ? conversation.callback_delivery
    : undefined;
  return ["pending", "failed"].includes(String(delivery?.status ?? ""));
}

function terminalDispatchOwnership(
  terminalControl: TerminalControlRef
):
  | { state: "none" }
  | { state: "current"; conversation: Conversation }
  | { state: "conflict"; conflict: Record<string, any> } {
  let ledger: Record<string, any> | undefined;
  try {
    ledger = loadTerminalBridgeDispatchLedger(terminalControl);
  } catch (error) {
    return {
      state: "conflict",
      conflict: {
        reason: error instanceof Error ? error.message : String(error),
        recovery: "inspect the shared terminal pane before performing a side effect"
      }
    };
  }
  if (!ledger || ledger.status === "resolved") {
    return { state: "none" };
  }
  if (
    terminalDispatchRecordMatchesControl(ledger, terminalControl, {
      requireProcessAnchor: false
    }) &&
    !terminalDispatchRecordMatchesControl(ledger, terminalControl)
  ) {
    return { state: "none" };
  }
  if (![
    "prepared",
    "text_injected",
    "enter_dispatched",
    "agent_accepted",
    "dispatching",
    "submitted",
    "not_accepted",
    "uncertain"
  ].includes(String(ledger.status))) {
    return { state: "none" };
  }
  const owner = loadTerminalDispatchLedgerOwner(ledger);
  if (!owner) {
    return {
      state: "conflict",
      conflict: terminalDispatchConflict(ledger, "dispatch owner state is unavailable")
    };
  }
  if (TERMINAL_DISPATCH_RELEASE_STATUSES.has(owner.status)) {
    return { state: "none" };
  }
  const ownerTerminalControl = terminalControlForManagedConversation(owner);
  if (!terminalControlsShareIncarnation(ownerTerminalControl, terminalControl)) {
    return {
      state: "conflict",
      conflict: terminalDispatchConflict(
        ledger,
        "dispatch owner does not reference this terminal pane incarnation"
      )
    };
  }
  const ownerTakeover = isRecord(owner.native_session_takeover)
    ? owner.native_session_takeover
    : undefined;
  const ledgerMessageId = stringValue(ledger.message_id);
  const ownerMessageId = stringValue(ownerTakeover?.terminal_bridge_message_id);
  if (
    [
      "prepared",
      "text_injected",
      "enter_dispatched",
      "agent_accepted",
      "dispatching",
      "submitted",
      "not_accepted",
      "uncertain"
    ].includes(
      String(ledger.status)
    ) &&
    ledgerMessageId &&
    ownerMessageId !== ledgerMessageId
  ) {
    return {
      state: "conflict",
      conflict: terminalDispatchConflict(
        ledger,
        "dispatch generation does not match the owner state"
      )
    };
  }
  return { state: "current", conversation: owner };
}

function terminalDispatchConflict(
  ledger: Record<string, any>,
  reason: string
): Record<string, any> {
  return {
    reason,
    dispatch_status: stringValue(ledger.status),
    owner_conversation_id: stringValue(ledger.conversation_id),
    message_id: stringValue(ledger.message_id),
    recovery: "inspect the shared terminal pane and explicitly resolve the current dispatch before performing a side effect"
  };
}

function localTerminalDispatchOwnership(
  ledgerOwner: Conversation,
  localConversations: Conversation[],
  terminal: Record<string, any>
):
  | { state: "current"; conversation: Conversation }
  | { state: "conflict"; conflict: Record<string, any> } {
  const localOwner = localConversations.find((conversation) =>
    conversation.conversation_id === ledgerOwner.conversation_id &&
    sameCanonicalStatePath(conversation.state_path, ledgerOwner.state_path)
  );
  if (localOwner) {
    if (!managedTurnMatchesLiveTerminal(localOwner, terminal)) {
      return {
        state: "conflict",
        conflict: {
          reason:
            "the terminal dispatch owner no longer matches the live coding-agent process identity or workspace",
          owner_conversation_id: ledgerOwner.conversation_id,
          recovery:
            "inspect the shared terminal pane and explicitly resolve the stale dispatch before performing a side effect"
        }
      };
    }
    return { state: "current", conversation: localOwner };
  }
  return {
    state: "conflict",
    conflict: {
      reason:
        "the terminal dispatch owner belongs to another AKK store or is not supported by this list view",
      owner_conversation_id: ledgerOwner.conversation_id,
      recovery:
        "inspect the shared terminal pane and use the AKK store that owns the current dispatch"
    }
  };
}

type TerminalScopedCodexApprovalPromptSnapshot = {
  fingerprint: string;
  keys: string[];
  requestId: string | null;
  digest: string;
};

type TerminalScopedCodexApprovalAuthority =
  | {
      kind: "current_dispatch_owner";
      owner: Conversation;
      session: ManagedSessionState;
      ledger: Record<string, any>;
    }
  | {
      kind: "managed_session_no_dispatch_owner";
      session: ManagedSessionState;
      ledger?: Record<string, any>;
    };

type TerminalScopedCodexApprovalBoundary = {
  authority: TerminalScopedCodexApprovalAuthority;
  approval: TerminalScopedCodexApprovalPromptSnapshot;
  token: string;
};

type TerminalScopedCodexApprovalResolution =
  | { state: "unmanaged" }
  | { state: "eligible"; boundary: TerminalScopedCodexApprovalBoundary }
  | { state: "blocked"; reason: string };

function terminalScopedCodexApprovalObservation(
  terminal: Record<string, any>
): Record<string, unknown> | undefined {
  const observation = isRecord(terminal.native_agent_identity_observation)
    ? terminal.native_agent_identity_observation
    : undefined;
  const status = stringValue(observation?.status);
  if (!status || !["resolved", "verified_absent", "unavailable"].includes(status)) {
    return undefined;
  }
  if (status !== "resolved") {
    return { status };
  }
  const rollout = isRecord(terminal.native_agent_rollout)
    ? terminal.native_agent_rollout
    : undefined;
  return {
    status,
    session_id: stringValue(terminal.native_agent_session_id) ?? null,
    process_uuid: stringValue(terminal.native_agent_process_uuid) ?? null,
    process_birth: stringValue(terminal.native_agent_process_birth) ?? null,
    rollout: isCompleteNativeRollout(rollout)
      ? {
          fd: rollout.fd,
          device: rollout.device,
          inode: rollout.inode,
          path: rollout.path
        }
      : null
  };
}

function terminalScopedCodexApprovalPromptSnapshot(
  approvalState: unknown
): TerminalScopedCodexApprovalPromptSnapshot | undefined {
  if (!isRecord(approvalState) || approvalState.approvable !== true) {
    return undefined;
  }
  const fingerprint = stringValue(approvalState.fingerprint);
  const rawKeys = Array.isArray(approvalState.keys)
    ? approvalState.keys
    : stringValue(approvalState.key)
      ? [approvalState.key]
      : [];
  const keys = rawKeys.filter(
    (value): value is string => typeof value === "string" && value.length > 0
  );
  if (
    !fingerprint ||
    !/^[0-9a-f]{64}$/u.test(fingerprint) ||
    keys.length === 0 ||
    keys.length !== rawKeys.length ||
    stringValue(approvalState.decision_mode) !== "keys"
  ) {
    return undefined;
  }
  const requestId = stringValue(approvalState.request_id) ?? null;
  return {
    fingerprint,
    keys,
    requestId,
    digest: terminalActionFingerprint({
      version: 1,
      kind: "terminal_scoped_codex_approval_prompt",
      fingerprint,
      keys,
      request_id: requestId
    })
  };
}

function terminalScopedCodexApprovalToken({
  storeDir,
  terminal,
  authority,
  approval
}: {
  storeDir: string;
  terminal: Record<string, any>;
  authority: TerminalScopedCodexApprovalAuthority;
  approval: TerminalScopedCodexApprovalPromptSnapshot;
}): string {
  const terminalControl = terminal.terminal_control as TerminalControlRef;
  const workspace = stringValue(terminal.workspace ?? terminal.cwd) as string;
  const processUuid = stringValue(terminal.native_agent_process_uuid) as string;
  const processBirth = stringValue(terminal.native_agent_process_birth) as string;
  const terminalToken = unmanagedTerminalBindingToken({
    terminalId: String(terminal.id),
    terminalControl,
    agent: "codex",
    pid: Number(terminal.pid),
    workspace,
    processUuid,
    processBirth
  });
  const session = authority.session;
  const owner = authority.kind === "current_dispatch_owner"
    ? authority.owner
    : undefined;
  const takeover = owner && isRecord(owner.native_session_takeover)
    ? owner.native_session_takeover
    : undefined;
  const ledger = authority.ledger;
  return createHash("sha256")
    .update(JSON.stringify({
      version: 2,
      kind: "terminal_scoped_codex_manual_approval",
      store_dir: path.resolve(storeDir),
      terminal_token: terminalToken,
      observation: terminalScopedCodexApprovalObservation(terminal),
      authority: authority.kind,
      owner_session_id: session.session_id,
      owner_session_revision: managedSessionRevision(session),
      owner_binding_token: managedSessionBindingToken(session),
      owner_turn_id: owner ? turnIdForConversation(owner) : null,
      owner_turn_status: owner?.status ?? null,
      owner_turn_updated_at: owner?.updated_at ?? null,
      owner_message_id:
        stringValue(takeover?.terminal_bridge_message_id) ?? null,
      dispatch_snapshot: ledger
        ? {
            status: stringValue(ledger.status),
            fingerprint: terminalActionFingerprint(ledger)
          }
        : { status: "none", fingerprint: null },
      approval_snapshot_digest: approval.digest,
      approval_fingerprint: approval.fingerprint,
      approval_keys: approval.keys,
      approval_request_id: approval.requestId
    }))
    .digest("hex");
}

function terminalScopedCodexApprovalBoundaryFromSnapshot({
  storeDir,
  terminal,
  owner,
  session,
  ledger,
  approval
}: {
  storeDir: string;
  terminal: Record<string, any>;
  owner: Conversation;
  session: ManagedSessionState;
  ledger: Record<string, any>;
  approval?: TerminalScopedCodexApprovalPromptSnapshot;
}): TerminalScopedCodexApprovalBoundary {
  const terminalControl = isRecord(terminal.terminal_control)
    ? terminal.terminal_control as unknown as TerminalControlRef
    : undefined;
  const binding = session.binding;
  const workspace = stringValue(terminal.workspace ?? terminal.cwd);
  const processUuid = stringValue(terminal.native_agent_process_uuid);
  const processBirth = stringValue(terminal.native_agent_process_birth);
  const observation = terminalScopedCodexApprovalObservation(terminal);
  if (
    terminal.agent !== "codex" ||
    !terminalControl ||
    !hasCanonicalTerminalEndpoint(terminalControl) ||
    !Number.isSafeInteger(Number(terminal.pid)) ||
    Number(terminal.pid) <= 1 ||
    !workspace ||
    !processUuid ||
    !processBirth ||
    !observation ||
    !approval
  ) {
    throw new Error(
      "terminal-scoped Codex approval requires an exact terminal and process incarnation"
    );
  }
  if (
    session.status !== "bound" ||
    session.agent !== "codex" ||
    !binding ||
    binding.native_process.pid !== Number(terminal.pid) ||
    binding.native_process.process_uuid !== processUuid ||
    binding.native_process.process_birth !== processBirth ||
    !terminalControlAliasMatches(
      binding.terminal_id,
      binding.terminal_control,
      terminal.id,
      terminalControl
    ) ||
    !terminalControlsShareIncarnation(binding.terminal_control, terminalControl) ||
    path.resolve(session.workspace) !== path.resolve(workspace) ||
    sessionIdForConversation(owner) !== session.session_id ||
    !["waiting_for_agent", "waiting_for_openclaw"].includes(owner.status)
  ) {
    throw new Error(
      "terminal-scoped Codex approval has no single current managed owner"
    );
  }
  const relatedBoundSessions = listManagedSessions(storeDir).filter((candidate) =>
    candidate.status === "bound" &&
    candidate.agent === "codex" &&
    candidate.binding?.native_process.pid === Number(terminal.pid) &&
    terminalControlsShareIncarnation(
      candidate.binding?.terminal_control,
      terminalControl
    )
  );
  if (
    relatedBoundSessions.length !== 1 ||
    relatedBoundSessions[0].session_id !== session.session_id
  ) {
    throw new Error(
      "terminal-scoped Codex approval has ambiguous managed Session ownership"
    );
  }
  const blockingTurns = terminalIncarnationBlockingTurns(
    storeDir,
    terminalControl
  );
  if (
    blockingTurns.length !== 1 ||
    turnIdForConversation(blockingTurns[0]) !== turnIdForConversation(owner)
  ) {
    throw new Error(
      "terminal-scoped Codex approval has collateral unresolved Turn state"
    );
  }
  if (
    managedSessionHasAnyNativeTransition(storeDir, session) ||
    listDeferredForegroundTransfers(storeDir).some((transfer) =>
      !["resolved", "abort_resolved"].includes(transfer.status) &&
      (
        transfer.source_session_id === session.session_id ||
        transfer.target_session_id === session.session_id ||
        (
          transfer.terminal_id === String(terminal.id) &&
          terminalControlEvidenceMatches(
            transfer.terminal_endpoint,
            terminalControl
          )
        )
      )
    )
  ) {
    throw new Error(
      "terminal-scoped Codex approval is blocked by managed recovery state"
    );
  }
  assertManagedTerminalDispatchOwner({
    storeDir,
    conversation: owner,
    terminalControl,
    action: "approve"
  });
  if (
    !terminalDispatchRecordMatchesControl(ledger, terminalControl) ||
    !["submitted", "agent_accepted"].includes(String(ledger.status))
  ) {
    throw new Error(
      `terminal-scoped Codex approval cannot use ${String(ledger.status)} dispatch ownership`
    );
  }
  const observedSessionId = stringValue(terminal.native_agent_session_id);
  const statusCardSessionId = stringValue(
    terminal.native_agent_status_card_session_id
  );
  for (const knownSessionId of [observedSessionId, statusCardSessionId]) {
    if (
      knownSessionId &&
      knownSessionId.toLowerCase() !==
        String(binding.native_thread_id ?? "").toLowerCase()
    ) {
      throw new Error(
        "terminal-scoped Codex approval observed a different native thread"
      );
    }
  }
  if (
    observedSessionId &&
    (
      stringValue(terminal.native_agent_process_uuid) !==
        binding.native_process.process_uuid ||
      stringValue(terminal.native_agent_process_birth) !==
        binding.native_process.process_birth ||
      (
        binding.native_process.rollout &&
        !exactNativeRolloutMatches(
          binding.native_process.rollout,
          isRecord(terminal.native_agent_rollout)
            ? terminal.native_agent_rollout as any
            : undefined
        )
      )
    )
  ) {
    throw new Error(
      "terminal-scoped Codex approval observed a changed native rollout incarnation"
    );
  }
  const currentIdentity = observedSessionId
    ? {
        sessionId: observedSessionId,
        processUuid,
        processBirth,
        rollout: isRecord(terminal.native_agent_rollout)
          ? terminal.native_agent_rollout as any
          : undefined,
        evidence: "terminal_scoped_approval"
      }
    : undefined;
  if (nativeAgentIdentityMatchesTurn(owner, currentIdentity)) {
    throw new Error(
      "the Codex managed identity is exact; use the managed Turn approval action"
    );
  }
  return {
    authority: {
      kind: "current_dispatch_owner",
      owner,
      session,
      ledger
    },
    approval,
    token: terminalScopedCodexApprovalToken({
      storeDir,
      terminal,
      authority: {
        kind: "current_dispatch_owner",
        owner,
        session,
        ledger
      },
      approval
    })
  };
}

function terminalScopedCodexApprovalWithoutDispatchOwnerBoundary({
  storeDir,
  terminal,
  session,
  ledger,
  approval
}: {
  storeDir: string;
  terminal: Record<string, any>;
  session: ManagedSessionState;
  ledger?: Record<string, any>;
  approval?: TerminalScopedCodexApprovalPromptSnapshot;
}): TerminalScopedCodexApprovalBoundary {
  const terminalControl = isRecord(terminal.terminal_control)
    ? terminal.terminal_control as unknown as TerminalControlRef
    : undefined;
  const binding = session.binding;
  const workspace = stringValue(terminal.workspace ?? terminal.cwd);
  const processUuid = stringValue(terminal.native_agent_process_uuid);
  const processBirth = stringValue(terminal.native_agent_process_birth);
  const observation = terminalScopedCodexApprovalObservation(terminal);
  if (
    terminal.agent !== "codex" ||
    !terminalControl ||
    !hasCanonicalTerminalEndpoint(terminalControl) ||
    !Number.isSafeInteger(Number(terminal.pid)) ||
    Number(terminal.pid) <= 1 ||
    !workspace ||
    !processUuid ||
    !processBirth ||
    !observation ||
    !approval
  ) {
    throw new Error(
      "terminal-scoped Codex approval requires an exact terminal, process, and prompt incarnation"
    );
  }
  if (
    session.status !== "bound" ||
    session.agent !== "codex" ||
    !binding ||
    !isExactNativeThreadId(binding.native_thread_id) ||
    binding.native_process.pid !== Number(terminal.pid) ||
    binding.native_process.process_uuid !== processUuid ||
    binding.native_process.process_birth !== processBirth ||
    !terminalControlAliasMatches(
      binding.terminal_id,
      binding.terminal_control,
      terminal.id,
      terminalControl
    ) ||
    !terminalControlsShareIncarnation(binding.terminal_control, terminalControl) ||
    path.resolve(session.workspace) !== path.resolve(workspace)
  ) {
    throw new Error(
      "terminal-scoped Codex approval has no single exact managed Session"
    );
  }
  const relatedBoundSessions = listManagedSessions(storeDir).filter((candidate) =>
    candidate.status === "bound" &&
    candidate.agent === "codex" &&
    candidate.binding?.native_process.pid === Number(terminal.pid) &&
    terminalControlsShareIncarnation(
      candidate.binding?.terminal_control,
      terminalControl
    )
  );
  if (
    relatedBoundSessions.length !== 1 ||
    relatedBoundSessions[0].session_id !== session.session_id
  ) {
    throw new Error(
      "terminal-scoped Codex approval has ambiguous managed Session ownership"
    );
  }
  if (terminalDispatchOwnership(terminalControl).state !== "none") {
    throw new Error(
      "terminal-scoped Codex approval acquired a current or conflicted dispatch owner"
    );
  }
  if (
    ledger &&
    (
      ledger.status !== "resolved" ||
      !terminalDispatchRecordMatchesControl(ledger, terminalControl)
    )
  ) {
    throw new Error(
      `terminal-scoped Codex approval cannot use ${String(ledger.status)} dispatch ownership`
    );
  }
  if (terminalIncarnationBlockingTurns(storeDir, terminalControl).length > 0) {
    throw new Error(
      "terminal-scoped Codex approval has unresolved managed Turn state"
    );
  }
  if (
    managedSessionHasAnyNativeTransition(storeDir, session) ||
    orphanedTerminalDispatchForRecovery(terminalControl) ||
    listDeferredForegroundTransfers(storeDir).some((transfer) =>
      !["resolved", "abort_resolved"].includes(transfer.status) &&
      (
        transfer.source_session_id === session.session_id ||
        transfer.target_session_id === session.session_id ||
        (
          transfer.terminal_id === String(terminal.id) &&
          terminalControlEvidenceMatches(
            transfer.terminal_endpoint,
            terminalControl
          )
        )
      )
    )
  ) {
    throw new Error(
      "terminal-scoped Codex approval is blocked by managed recovery state"
    );
  }
  const observedSessionId = stringValue(terminal.native_agent_session_id);
  const statusCardSessionId = stringValue(
    terminal.native_agent_status_card_session_id
  );
  for (const knownSessionId of [observedSessionId, statusCardSessionId]) {
    if (
      knownSessionId &&
      knownSessionId.toLowerCase() !== binding.native_thread_id.toLowerCase()
    ) {
      throw new Error(
        "terminal-scoped Codex approval observed a different native thread"
      );
    }
  }
  if (
    observedSessionId &&
    (
      stringValue(terminal.native_agent_process_uuid) !==
        binding.native_process.process_uuid ||
      stringValue(terminal.native_agent_process_birth) !==
        binding.native_process.process_birth ||
      (
        binding.native_process.rollout &&
        !exactNativeRolloutMatches(
          binding.native_process.rollout,
          isRecord(terminal.native_agent_rollout)
            ? terminal.native_agent_rollout as any
            : undefined
        )
      )
    )
  ) {
    throw new Error(
      "terminal-scoped Codex approval observed a changed native rollout incarnation"
    );
  }
  const authority: TerminalScopedCodexApprovalAuthority = {
    kind: "managed_session_no_dispatch_owner",
    session,
    ...(ledger ? { ledger } : {})
  };
  return {
    authority,
    approval,
    token: terminalScopedCodexApprovalToken({
      storeDir,
      terminal,
      authority,
      approval
    })
  };
}

async function resolveTerminalScopedCodexApproval({
  options,
  terminal,
  approvalSnapshot
}: {
  options: Record<string, any>;
  terminal: ResolvedTerminalConversation;
  approvalSnapshot?: TerminalScopedCodexApprovalPromptSnapshot;
}): Promise<TerminalScopedCodexApprovalResolution> {
  if (terminal.agent !== "codex") {
    return { state: "blocked", reason: "raw Claude approval remains unsupported" };
  }
  const storeDir = path.resolve(storeDirFromOptions(options));
  let ledger: Record<string, any> | undefined;
  try {
    ledger = loadTerminalBridgeDispatchLedger(terminal.terminalControl);
  } catch (error) {
    return {
      state: "blocked",
      reason: error instanceof Error ? error.message : String(error)
    };
  }
  const relatedSessions = listManagedSessions(storeDir).filter((session) =>
    session.binding?.native_process.pid === terminal.pid &&
    terminalControlsShareIncarnation(
      session.binding?.terminal_control,
      terminal.terminalControl
    )
  );
  const relatedTurns = listConversations(storeDir).filter((turn) =>
    terminalControlsShareIncarnation(
      terminalControlForManagedConversation(turn),
      terminal.terminalControl
    )
  );
  if (ledger?.status === "uncertain") {
    return {
      state: "blocked",
      reason:
        "terminal dispatch is uncertain; inspect the pane and do not retry approval"
    };
  }
  const ownership = terminalDispatchOwnership(terminal.terminalControl);
  if (ownership.state === "conflict") {
    return {
      state: "blocked",
      reason: stringValue(ownership.conflict.reason) ??
        "terminal dispatch ownership is conflicted"
    };
  }
  if (
    ownership.state === "none" &&
    relatedSessions.length === 0 &&
    relatedTurns.length === 0
  ) {
    return { state: "unmanaged" };
  }
  const owner = ownership.state === "current"
    ? ownership.conversation
    : undefined;
  if (owner) {
    const ownerStoreDir = managedSessionStoreDirForConversation(owner);
    if (!ownerStoreDir || path.resolve(ownerStoreDir) !== storeDir) {
      return {
        state: "blocked",
        reason: "terminal dispatch owner belongs to another AKK Store"
      };
    }
  }
  const ownerSession = owner
    ? tryLoadManagedSession(storeDir, sessionIdForConversation(owner))
    : undefined;
  if (owner && !ownerSession) {
    return {
      state: "blocked",
      reason: "terminal dispatch owner has no current managed Session"
    };
  }
  let identityContext:
    | ReturnType<typeof codexManagedIdentityResolutionContext>
    | undefined;
  try {
    identityContext = codexManagedIdentityResolutionContext({
      storeDir,
      terminal
    });
  } catch {
    // The terminal-scoped path deliberately tolerates an unavailable Codex
    // rollout resolver. Store, pane, process, owner, and prompt fences below
    // remain mandatory.
  }
  const observation = await observeCurrentNativeAgentSessionIdentity({
    options,
    agent: "codex",
    pid: terminal.pid,
    cwd: terminal.terminalControl.currentPath,
    preferredSessionId: identityContext?.preferredSessionId,
    allowedCompanionIdentity: identityContext?.companions.primary,
    allowedAdditionalIdentities: identityContext?.companions.additional
  });
  let processIncarnation: ReturnType<typeof codexProcessIncarnationForPid>;
  try {
    processIncarnation = codexProcessIncarnationForPid(terminal.pid);
  } catch (error) {
    return {
      state: "blocked",
      reason: error instanceof Error ? error.message : String(error)
    };
  }
  const identity = observation.status === "resolved"
    ? observation.identity
    : undefined;
  let approval = approvalSnapshot;
  if (!approval) {
    try {
      const terminalStatus = await terminalStatusForControl(
        "codex",
        terminal.terminalControl,
        options,
        {
          pid: terminal.pid,
          cwd: terminal.terminalControl.currentPath,
          conversationId: terminal.conversationId,
          terminalTarget: terminal.terminalControl.target
        }
      );
      approval = terminalScopedCodexApprovalPromptSnapshot(
        terminalStatus.approval_state
      );
    } catch (error) {
      return {
        state: "blocked",
        reason: error instanceof Error ? error.message : String(error)
      };
    }
  }
  if (!approval) {
    return {
      state: "blocked",
      reason:
        "terminal-scoped Codex approval requires one fresh exact approval prompt"
    };
  }
  const terminalSnapshot: Record<string, any> = {
    id: terminal.conversationId,
    source: "terminal",
    agent: "codex",
    pid: terminal.pid,
    cwd: terminal.terminalControl.currentPath,
    workspace: terminal.terminalControl.currentPath,
    terminal_control: terminal.terminalControl,
    native_agent_session_id: identity?.sessionId,
    native_agent_process_uuid:
      identity?.processUuid ?? processIncarnation.processUuid,
    native_agent_process_birth:
      identity?.processBirth ?? processIncarnation.processBirth,
    native_agent_rollout: identity?.rollout,
    native_agent_identity_observation: { status: observation.status },
    approval_state: {
      approvable: true,
      fingerprint: approval.fingerprint,
      keys: approval.keys,
      decision_mode: "keys",
      request_id: approval.requestId
    }
  };
  try {
    if (owner && ownerSession && ledger) {
      return {
        state: "eligible",
        boundary: terminalScopedCodexApprovalBoundaryFromSnapshot({
          storeDir,
          terminal: terminalSnapshot,
          owner,
          session: ownerSession,
          ledger,
          approval
        })
      };
    }
    if (ownership.state !== "none") {
      throw new Error(
        "managed terminal approval has no current exact dispatch owner"
      );
    }
    if (ledger && ledger.status !== "resolved") {
      throw new Error(
        `terminal-scoped Codex approval cannot use ${String(ledger.status)} dispatch ownership`
      );
    }
    const matchingSessions = relatedSessions.filter((session) =>
      managedSessionMatchesLiveTerminalEntry(
        session,
        terminalSnapshot,
        storeDir
      )
    );
    if (matchingSessions.length !== 1) {
      throw new Error(
        "terminal-scoped Codex approval has no single exact managed Session"
      );
    }
    return {
      state: "eligible",
      boundary: terminalScopedCodexApprovalWithoutDispatchOwnerBoundary({
        storeDir,
        terminal: terminalSnapshot,
        session: matchingSessions[0],
        ledger,
        approval
      })
    };
  } catch (error) {
    return {
      state: "blocked",
      reason: error instanceof Error ? error.message : String(error)
    };
  }
}

function sameCanonicalStatePath(left: unknown, right: unknown): boolean {
  const leftPath = stringValue(left);
  const rightPath = stringValue(right);
  return Boolean(
    leftPath &&
    rightPath &&
    path.resolve(leftPath) === path.resolve(rightPath)
  );
}

function currentTerminalActions(
  currentTurn: Record<string, any> | undefined
): Record<string, any> {
  if (!currentTurn || !isRecord(currentTurn.available_actions)) {
    return {};
  }
  const actions: Record<string, any> = {};
  for (const action of ["status", "respond", "approve", "cancel", "renew", "retry_callback"]) {
    if (isRecord(currentTurn.available_actions[action])) {
      actions[action] = currentTurn.available_actions[action];
    }
  }
  return actions;
}

function safeTerminalActionsDuringConflict(
  rawActions: Record<string, any>
): Record<string, any> {
  const actions: Record<string, any> = {};
  for (const action of ["status", "close"]) {
    if (isRecord(rawActions[action])) {
      actions[action] = rawActions[action];
    }
  }
  return actions;
}

function sendActionForManagedSession(
  action: Record<string, any>,
  sessionId: string
): Record<string, any> {
  const { selector: _selector, ...existingArguments } = isRecord(action.arguments)
    ? action.arguments
    : {};
  return {
    ...action,
    arguments: {
      ...existingArguments,
      session_id: sessionId
    }
  };
}

function actionsForManagedSessionBinding(
  actions: Record<string, any>,
  session: ManagedSessionState
): Record<string, any> {
  const token = managedSessionBindingToken(session);
  const next = { ...actions };
  for (const actionName of ["new_thread", "resume_thread", "native_inspect"]) {
    const action = isRecord(next[actionName]) ? next[actionName] : undefined;
    if (!action) {
      continue;
    }
    next[actionName] = {
      ...action,
      arguments: {
        ...(isRecord(action.arguments) ? action.arguments : {}),
        expected_binding_token: token
      }
    };
  }
  return next;
}

function safeUnavailableManagedTurnActions(
  actionsValue: Record<string, any>
): Record<string, any> {
  const actions: Record<string, any> = {};
  for (const action of ["status", "retry_callback", "close"]) {
    if (isRecord(actionsValue[action])) {
      actions[action] = actionsValue[action];
    }
  }
  return actions;
}

function readOnlyListActions(
  actionsValue: Record<string, any>
): Record<string, any> {
  return isRecord(actionsValue.status)
    ? { status: actionsValue.status }
    : {};
}

function readOnlyManagedTurn(
  managedTurn: Record<string, any>
): Record<string, any> {
  return {
    ...managedTurn,
    available_actions: readOnlyListActions(
      isRecord(managedTurn.available_actions)
        ? managedTurn.available_actions
        : {}
    )
  };
}

function withoutGenericHandoffSourceClose(
  managedTurn: Record<string, any>,
  blockingHandoffTurnIds: ReadonlySet<string>
): Record<string, any> {
  const conversationId = stringValue(managedTurn.conversation_id);
  if (!conversationId || !blockingHandoffTurnIds.has(conversationId)) {
    return managedTurn;
  }
  const availableActions = isRecord(managedTurn.available_actions)
    ? managedTurn.available_actions
    : {};
  const { close: _genericClose, ...safeActions } = availableActions;
  return {
    ...managedTurn,
    available_actions: safeActions
  };
}

function historicalManagedTurnForTerminal(
  conversation: Conversation,
  terminalCanAcceptSend: boolean,
  terminal: Record<string, any>
): Record<string, any> {
  const managedTurn = managedTurnListEntry(
    summarizeConversation(conversation),
    {
      terminalBridge: terminalBridgeEnabled(conversation),
      approvalState: managedListApprovalState(conversation),
      conversation
    }
  );
  const availableActions = isRecord(managedTurn.available_actions)
    ? managedTurn.available_actions
    : {};
  const safeActions = safeUnavailableManagedTurnActions(availableActions);
  return {
    ...managedTurn,
    available_actions: safeActions
  };
}

function managedTurnMatchesLiveTerminal(
  conversation: Conversation,
  terminal: Record<string, any>
): boolean {
  const takeover = isRecord(conversation.native_session_takeover)
    ? conversation.native_session_takeover
    : undefined;
  const liveControl = isRecord(terminal.terminal_control)
    ? terminal.terminal_control
    : undefined;
  const storedControl = terminalControlFromTakeover(takeover);
  const livePid = Number(terminal.pid);
  const storedPid = Number(takeover?.terminal_agent_pid);
  if (
    executorForConversation(conversation).kind !== terminal.agent ||
    !Number.isSafeInteger(livePid) ||
    livePid <= 1 ||
    storedPid !== livePid ||
    !terminalControlAliasMatches(
      stringValue(takeover?.native_session_id),
      storedControl,
      stringValue(terminal.id),
      liveControl
    ) ||
    !terminalControlsShareIncarnation(storedControl, liveControl)
  ) {
    return false;
  }
  const liveSessionId = stringValue(terminal.native_agent_session_id);
  const liveProcessUuid = stringValue(terminal.native_agent_process_uuid);
  const liveProcessBirth = stringValue(terminal.native_agent_process_birth);
  const liveRollout = isRecord(terminal.native_agent_rollout)
    ? terminal.native_agent_rollout
    : undefined;
  const liveNativeIdentity = liveSessionId
    ? {
        sessionId: liveSessionId,
        ...(liveProcessUuid ? { processUuid: liveProcessUuid } : {}),
        ...(liveProcessBirth ? { processBirth: liveProcessBirth } : {}),
        ...(liveRollout
          ? {
              rollout: {
                fd: String(liveRollout.fd ?? ""),
                device: String(liveRollout.device ?? ""),
                inode: String(liveRollout.inode ?? ""),
                path: String(liveRollout.path ?? "")
              }
            }
          : {}),
        evidence: "live_terminal"
      }
    : undefined;
  if (!nativeAgentIdentityMatchesTurn(conversation, liveNativeIdentity)) {
    return false;
  }
  const liveWorkspace = terminal.workspace ?? terminal.cwd;
  if (!matchesConfiguredWorkspace(conversation.workspace, liveWorkspace)) {
    return false;
  }
  const livePanePath = liveControl?.currentPath;
  if (
    livePanePath !== undefined &&
    !matchesConfiguredWorkspace(conversation.workspace, livePanePath)
  ) {
    return false;
  }
  return true;
}

function currentManagedTurnForTerminal(
  conversation: Conversation,
  terminal: Record<string, any>,
  rawTerminalActions: Record<string, any>
): Record<string, any> {
  const managedTurn = managedTurnListEntry(
    summarizeConversation(conversation),
    {
      terminalBridge: terminalBridgeEnabled(conversation),
      approvalState: managedListApprovalState(conversation),
      conversation
    }
  );
  const rawApproval = isRecord(rawTerminalActions.approve)
    ? rawTerminalActions.approve
    : undefined;
  if (!rawApproval || executorForConversation(conversation).kind !== "codex") {
    return managedTurn;
  }
  const ownerId = conversation.conversation_id;
  const approval = retargetConversationAction(rawApproval, ownerId);
  const terminalApprovalState = isRecord(terminal.approval_state)
    ? terminal.approval_state
    : undefined;
  return {
    ...managedTurn,
    ...(terminalApprovalState
      ? { approval_state: terminalApprovalState }
      : {}),
    available_actions: {
      ...(isRecord(managedTurn.available_actions)
        ? managedTurn.available_actions
        : {}),
      approve: approval
    }
  };
}

function retargetConversationAction(
  action: Record<string, any>,
  conversationId: string
): Record<string, any> {
  const beforeCall = isRecord(action.before_call)
    ? action.before_call
    : undefined;
  return {
    ...action,
    arguments: {
      ...(isRecord(action.arguments) ? action.arguments : {}),
      turn_id: conversationId,
      conversation_id: undefined
    },
    ...(beforeCall
      ? {
          before_call: {
            ...beforeCall,
            arguments: {
              ...(isRecord(beforeCall.arguments)
                ? beforeCall.arguments
                : {}),
              turn_id: conversationId,
              conversation_id: undefined
            }
          }
        }
      : {})
  };
}

async function listStateForTerminal(
  agent: ExecutorKind,
  terminalControl: TerminalControlRef,
  options,
  bridge: TerminalAgentBridge = createTerminalAgentBridge(options),
  runtime?: TerminalRuntimeIdentity
) {
  if (options.noApprovalScan) {
    return {
      approval_state: {
        scanned: false,
        blocked: false,
        approvable: false,
        reason: "approval scan disabled"
      },
      activity_state: "unknown",
      activity_reason: "terminal screen scan disabled"
    };
  }
  try {
    const status = await bridge.status(agent, terminalControl, {
      scrollbackLines: Number(options.scrollbackLines ?? 120),
      runtime
    });
    return {
      approval_state: {
        ...status.approval_state,
        screen_excerpt: status.approval_state.blocked ? status.screen.excerpt?.slice(-1000) : undefined
      },
      activity_state: status.activity_state,
      activity_reason: status.activity_reason,
      capability_limitation: status.capability_limitation,
      // Internal projection evidence; terminalControlledListEntry selects all
      // public fields explicitly and never exposes the pane excerpt itself.
      screen_excerpt: status.screen.excerpt
    };
  } catch (error) {
    return {
      approval_state: {
        scanned: false,
        blocked: false,
        approvable: false,
        error: error instanceof Error ? error.message : String(error)
      },
      activity_state: "unknown",
      activity_reason: error instanceof Error ? error.message : String(error)
    };
  }
}

function rootActiveProcesses(processes: ActiveTerminalProcess[]): ActiveTerminalProcess[] {
  const pids = new Set(processes.map((process) => `${process.agent}:${process.pid}`));
  const roots = processes.filter((process) =>
    !process.ppid || !pids.has(`${process.agent}:${process.ppid}`)
  );
  const seenTerminalIncarnations = new Set<string>();
  return roots.filter((process) => {
    const endpoint = process.terminalControl
      ? terminalEndpointFromControlRef(process.terminalControl)
      : undefined;
    const terminalIncarnation = endpoint
      ? JSON.stringify({
          agent: process.agent,
          identity: terminalEndpointIdentityKey(endpoint),
          process_anchor_pid: endpoint.processAnchorPid ?? null
        })
      : undefined;
    if (!terminalIncarnation) {
      return true;
    }
    if (seenTerminalIncarnations.has(terminalIncarnation)) {
      return false;
    }
    seenTerminalIncarnations.add(terminalIncarnation);
    return true;
  });
}

function childPidsForRoot(root: ActiveTerminalProcess, processes: ActiveTerminalProcess[]): number[] {
  return processes
    .filter((process) => process.agent === root.agent && process.ppid === root.pid)
    .map((process) => process.pid);
}

function managedListApprovalState(
  conversation
): Record<string, any> | undefined {
  if (
    !terminalBridgeEnabled(conversation) ||
    !["waiting_for_agent", "waiting_for_openclaw"].includes(
      String(conversation.status)
    )
  ) {
    return undefined;
  }
  const nativeTakeover = isRecord(conversation.native_session_takeover)
    ? conversation.native_session_takeover
    : undefined;
  if (
    !terminalControlFromTakeover(nativeTakeover) ||
    !stringValue(nativeTakeover?.terminal_bridge_message_id)
  ) {
    return undefined;
  }
  const approval = isRecord(nativeTakeover?.terminal_bridge_approval)
    ? nativeTakeover.terminal_bridge_approval
    : undefined;
  const approvalState = isRecord(approval?.approval_state)
    ? approval.approval_state
    : undefined;
  const fingerprint = stringValue(approval?.fingerprint);
  const notifiedAt = stringValue(approval?.notified_at);
  const notifiedAtMs = validTimestampMs(notifiedAt);
  if (
    !approvalState ||
    !fingerprint ||
    notifiedAtMs === undefined ||
    cliNowMs() - notifiedAtMs > CLAUDE_SCREEN_APPROVAL_TTL_MS
  ) {
    return undefined;
  }
  return {
    ...approvalState,
    fingerprint,
    notified_at: notifiedAt
  };
}

